INSERT INTO recipes (title, description, prep_time_mins, cook_time_mins, servings, difficulty, dietary_type, tags, visibility, equipment_needed, instructions) VALUES
('Ratatouille', 'Un ragoût de légumes provençal où chaque légume cuit séparément avant de se retrouver — sinon, tout se transforme en bouillie.', 25, 55, 4, 1, 'light', '["français", "végétarien", "provençal", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper l''aubergine et les courgettes en dés de 2 cm, les poivrons en lanières d''1 cm et l''oignon en fines lamelles. Inciser les tomates en croix, les plonger 30 secondes dans l''eau bouillante, les peler, les épépiner et les concasser.", "Chauffer 2 c.à.s d''huile dans une grande poêle à feu vif et faire dorer l''aubergine 6 à 8 min en remuant, jusqu''à ce que les bords soient dorés. Saler et réserver dans une cocotte. Ne pas rajouter d''huile en cours de route : l''aubergine la boit d''abord puis la restitue.", "Dans la même poêle, avec 1 c.à.s d''huile, faire dorer les courgettes 4 à 5 min : elles doivent rester fermes. Saler et ajouter à l''aubergine.", "Toujours avec 1 c.à.s d''huile, cuire les poivrons 6 à 8 min jusqu''à ce qu''ils soient tendres et légèrement colorés. Les ajouter aux autres légumes.", "Avec le reste de l''huile, faire fondre l''oignon 5 min à feu moyen, ajouter l''ail haché et le thym 30 secondes, puis les tomates, le laurier, du sel et du poivre. Laisser réduire à feu moyen 15 à 20 min, jusqu''à obtenir une sauce épaisse.", "Verser la sauce sur les légumes dans la cocotte, mélanger délicatement et laisser mijoter à couvert 15 min à feu doux. Retirer le thym et le laurier, ajouter le basilic ciselé et rectifier l''assaisonnement. Servir chaud ou tiède ; elle est encore meilleure réchauffée le lendemain."]'::jsonb),
('Soupe à l''oignon gratinée', 'Une soupe d''oignons, de bouillon et de pain gratiné. Toute la saveur vient de la caramélisation, qui prend quarante minutes et non vingt.', 15, 75, 4, 1, 'light', '["français", "soupe", "réconfortant", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Éplucher les oignons, les couper en deux et les émincer finement (3 mm d''épaisseur).", "Faire fondre le beurre dans une cocotte, ajouter les oignons et une pincée de sel, laisser à feu moyen en remuant régulièrement — les vingt premières minutes, les oignons rendent leur eau.", "La caramélisation commence ensuite : encore vingt-cinq minutes pour les amener à la couleur du thé fort. S''ils accrochent, baisser le feu et ajouter une cuillère d''eau.", "Ajouter la farine et cuire deux minutes pour perdre le goût cru.", "Verser le vin en grattant le fond, laisser réduire de moitié.", "Ajouter le bouillon et le thym, porter à ébullition et mijoter 20 min. Rectifier l''assaisonnement en fin de cuisson.", "Répartir dans des bols allant au four, garnir chacun d''une tranche de baguette, couvrir de fromage et passer sous le grill jusqu''à ce que ça bouillonne et dore, environ 3 min."]'::jsonb),
('Coq au vin', 'Poulet braisé au vin rouge avec lardons, champignons et petits oignons. Mariner la veille fait la moitié du travail.', 30, 90, 4, 2, 'gras', '["français", "mijoté", "classique", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["La veille, couper la carotte en rondelles et écraser l''ail. Mettre le poulet dans un saladier avec la carotte, l''ail, le thym et le laurier, couvrir de vin et laisser mariner au réfrigérateur toute la nuit.", "Le lendemain, égoutter la viande en gardant le vin et les légumes, et la sécher soigneusement avec du papier absorbant (mouillée, elle ne dore pas).", "Faire revenir les lardons dans une cocotte à feu moyen 5 min et les réserver. Dans leur graisse, faire dorer les morceaux de poulet sur toutes les faces, en plusieurs fois, 8 à 10 min par fournée. Saler et poivrer.", "Remettre tout le poulet, saupoudrer de farine, mélanger et cuire 2 min. Verser la marinade avec ses légumes et le bouillon, porter à ébullition et écumer.", "Couvrir et laisser mijoter 1h à 1h15 à feu très doux (ou au four à 160°C) : la sauce doit à peine frémir. Le poulet est cuit quand la chair se détache facilement de l''os.", "Pendant ce temps, faire dorer les petits oignons épluchés dans la moitié du beurre 10 min et, séparément, les champignons en quartiers dans le reste du beurre à feu vif 5 min, jusqu''à coloration.", "Ajouter oignons, champignons et lardons dans la cocotte et laisser 10 min à feu doux. Retirer le thym et le laurier. Si la sauce est trop liquide, sortir le poulet et la réduire quelques minutes à découvert. Rectifier l''assaisonnement et servir avec des pommes de terre vapeur ou des pâtes fraîches."]'::jsonb),
('Crème brûlée', 'Une crème aux jaunes d''œufs cuite au bain-marie sous une croûte de sucre brûlé.', 20, 45, 4, 2, 'gras', '["français", "dessert", "four", "goûter"]'::jsonb, 'public', '["oven"]'::jsonb, '["Préchauffer le four à 150°C.", "Fendre la vanille, gratter les graines dans la crème et chauffer jusqu''à frémissement. Retirer du feu et laisser infuser 15 min.", "Travailler les jaunes et le sucre sans incorporer d''air — pas de mousse ici. Verser la crème tiède en filet en remuant.", "Filtrer au tamis, écumer la mousse en surface, répartir dans des ramequins posés dans un plat profond.", "Verser de l''eau bouillante dans le plat jusqu''à mi-hauteur des ramequins et cuire 40 min à 150°C. Le centre doit encore trembler.", "Laisser refroidir complètement puis réfrigérer au moins 4h. Saupoudrer de sucre et caraméliser au chalumeau juste avant de servir."]'::jsonb),
('Quiche lorraine', 'Une pâte brisée garnie de lardons et d''un appareil œufs-crème. Ni fromage ni oignon — la recette classique n''en contient pas.', 40, 60, 6, 2, 'gras', '["français", "four", "classique", "plat"]'::jsonb, 'public', '["oven"]'::jsonb, '["Sabler du bout des doigts le beurre froid en dés avec la farine et une pincée de sel, ajouter 1 œuf et l''eau glacée et rassembler la pâte en boule sans la pétrir. Filmer et réfrigérer 1h.", "Étaler la pâte sur 3 mm, foncer un moule de 24 cm, piquer le fond à la fourchette et réfrigérer encore 20 min : c''est ce qui l''empêche de se rétracter. Préchauffer le four à 190°C.", "Couvrir la pâte de papier cuisson et de billes de cuisson (ou de légumes secs), cuire à blanc 15 min, retirer papier et billes et poursuivre 5 min pour que le fond soit sec. Baisser le four à 170°C.", "Faire dorer les lardons à la poêle sans matière grasse 5 min et les égoutter sur papier absorbant : trop de gras ferait trancher l''appareil.", "Battre les 3 autres œufs avec la crème et le lait sans faire mousser, assaisonner de muscade et de poivre. Peu ou pas de sel : les lardons en apportent déjà.", "Répartir les lardons sur le fond de tarte, verser l''appareil et cuire 30 à 35 min à 170°C. Le dessus doit être doré et le centre encore légèrement tremblotant à la sortie du four. Laisser reposer 10 min avant de couper."]'::jsonb),
('Croissant', 'Une pâte levée feuilletée à vingt-sept couches de beurre. Tout se joue sur la température : pâte et beurre doivent être également froids.', 180, 20, 8, 3, 'gras', '["français", "boulangerie", "four", "petit-déjeuner", "goûter"]'::jsonb, 'public', '["oven"]'::jsonb, '["Détrempe (la veille) : mélanger farine, lait froid, levure émiettée, sucre, sel et beurre mou pendant 5 min, pas plus, pour ne pas trop développer le gluten.", "Aplatir la pâte en rectangle, filmer et réfrigérer au moins 4h, idéalement toute la nuit.", "Taper le beurre de tourage froid au rouleau entre deux feuilles de papier cuisson pour former un carré d''un centimètre d''épaisseur. Il doit être froid mais souple : il plie sans casser ni fondre.", "Étaler la pâte deux fois plus grande que le carré de beurre, poser le beurre au centre et rabattre les bords comme une enveloppe en soudant bien les jointures.", "Étaler en long rectangle (3 fois plus long que large) et plier en trois. Filmer et réfrigérer 40 min. Répéter deux fois : trois tours en tout, avec un repos au froid entre chaque.", "Abaisser la pâte à 4 mm d''épaisseur et découper des triangles de 10 cm de base et 25 cm de hauteur. Les rouler de la base vers la pointe sans serrer, en étirant légèrement la pointe, et les poser sur une plaque, pointe dessous.", "Laisser pousser 2h à 2h30 à 25°C maximum, jusqu''à ce qu''ils aient presque doublé : plus chaud, le beurre fond et le feuilletage est perdu.", "Préchauffer le four à 190°C (170°C en chaleur tournante). Dorer à l''œuf battu avec une pincée de sel, sans toucher les tranches feuilletées, et cuire 15 à 18 min jusqu''à ce qu''ils soient bien dorés. Laisser tiédir sur une grille."]'::jsonb),
('Bouillabaisse', 'La soupe de poissons marseillaise, plusieurs espèces, safran et sauce rouille.', 50, 70, 6, 3, 'protéiné', '["français", "poisson", "provençal", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire écailler et vider les poissons par le poissonnier. Couper les gros poissons en tronçons de 5 cm. Émincer les oignons, le poireau et le fenouil, concasser les tomates et écraser 6 gousses d''ail (garder les 2 autres pour la rouille).", "Dans une grande marmite, faire suer oignons, poireau et fenouil dans 100 ml d''huile d''olive 10 min à feu moyen.", "Ajouter les petits poissons de roche entiers, les tomates, l''ail écrasé, le zeste d''orange et une pincée de safran, et remuer 5 min à feu vif.", "Mouiller avec 2 litres d''eau bouillante, saler, poivrer et cuire 30 à 40 min à gros bouillons : c''est l''ébullition vive qui émulsionne l''huile et lie le bouillon.", "Passer le tout au moulin à légumes (grille fine) en pressant bien la chair, puis filtrer au chinois et remettre le bouillon dans la marmite.", "Ajouter les pommes de terre en rondelles de 1 cm et cuire 15 min. Ajouter les poissons les plus fermes (lotte, grondin) et cuire 5 min, puis les plus tendres (rascasse, saint-pierre) 5 min encore, à petits frémissements pour ne pas les briser.", "Rouille : écraser les 2 gousses d''ail restantes avec une pincée de sel, de safran et de piment de Cayenne, ajouter le jaune d''œuf puis 50 ml d''huile d''olive en filet, en fouettant comme une mayonnaise.", "Faire griller les tranches de baguette. Servir d''abord le bouillon avec les croûtons tartinés de rouille, puis les poissons et les pommes de terre sur un plat à part."]'::jsonb),
('Tarte Tatin', 'Une tarte aux pommes renversée : les pommes caramélisent au fond, la pâte se pose dessus et devient la base.', 30, 60, 8, 2, 'gras', '["français", "dessert", "four", "goûter"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Préchauffer le four à 200°C. Éplucher les pommes, les couper en deux, retirer le cœur et les arroser de jus de citron.", "Dans une poêle en fonte de 26 cm allant au four, faire fondre le sucre à feu moyen jusqu''à obtenir un caramel ambré, sans remuer à la cuillère (faire tourner la poêle).", "Retirer du feu et incorporer le beurre en morceaux, les graines de vanille et une pincée de sel.", "Ranger les demi-pommes debout sur la tranche, bien serrées les unes contre les autres, en cercle.", "Cuire sur le feu 20 min à feu moyen, jusqu''à ce que les pommes s''affaissent et s''imprègnent de caramel.", "Couvrir d''un disque de pâte feuilletée en rentrant les bords à l''intérieur de la poêle et piquer à plusieurs endroits.", "Cuire 35 à 40 min au four, jusqu''à ce que la pâte soit bien dorée. Laisser reposer 5 min, poser un plat sur la poêle et renverser d''un geste franc. Servir tiède avec la crème."]'::jsonb),
('Blanquette de veau', 'Veau mijoté dans un bouillon clair, lié à la crème et au jaune d''œuf, avec carottes et champignons.', 25, 90, 4, 2, 'protéiné', '["français", "mijoté", "classique", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper le veau en cubes de 4 à 5 cm. Le mettre dans une cocotte, couvrir d''eau froide, porter à ébullition et écumer soigneusement pendant 5 min.", "Ajouter les carottes en tronçons, l''oignon piqué des clous de girofle, le poireau et le bouquet garni. Saler légèrement et laisser mijoter à couvert 1h15 à 1h30 à feu doux, jusqu''à ce que la viande soit tendre.", "Retirer la viande et les carottes, filtrer le bouillon et le réserver (jeter l''oignon, le poireau et le bouquet garni). Mettre le riz à cuire.", "Dans la cocotte, faire fondre le beurre, ajouter la farine et cuire 2 min en remuant sans colorer (roux blanc). Verser peu à peu 70 cl de bouillon chaud en fouettant, jusqu''à obtenir une sauce nappante.", "Ajouter les champignons émincés et cuire 10 min dans la sauce à feu doux.", "Remettre la viande et les carottes et réchauffer 5 min. Hors du feu, mélanger les jaunes d''œufs avec la crème et le jus d''un demi-citron, verser dans la cocotte et remuer : la sauce ne doit plus bouillir, sinon les jaunes coagulent. Rectifier l''assaisonnement et servir avec le riz."]'::jsonb),
('Cassoulet', 'Haricots blancs mijotés avec saucisse, porc et confit de canard, gratinés au four.', 40, 210, 6, 2, 'gras', '["français", "mijoté", "famille", "hiver", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["La veille, faire tremper les haricots secs dans un grand volume d''eau froide pendant 12h.", "Égoutter les haricots, les mettre dans une grande marmite avec la couenne coupée en lanières, un oignon et le bouquet garni, couvrir largement d''eau froide non salée (le sel les durcit) et cuire à frémissement 1h à 1h30, jusqu''à ce qu''ils soient tendres mais entiers. Saler en fin de cuisson.", "Pendant ce temps, retirer l''excès de graisse des cuisses de confit et en garder 2 c.à.s. Dans une cocotte, faire dorer dans cette graisse la poitrine de porc en cubes de 4 cm, puis les saucisses coupées en tronçons de 6 cm.", "Retirer les viandes et faire revenir dans la cocotte le second oignon émincé et les carottes en rondelles 5 min. Ajouter l''ail haché et le concentré de tomate et cuire 2 min.", "Préchauffer le four à 150°C. Égoutter les haricots en gardant leur bouillon, retirer le bouquet garni. Dans un grand plat en terre, alterner haricots, légumes, porc, saucisses et confit, en finissant par des haricots. Verser du bouillon de cuisson jusqu''à juste couvrir.", "Parsemer de chapelure et enfourner 2h. Toutes les 30 min, enfoncer la croûte qui se forme avec le dos d''une cuillère et ajouter un peu de bouillon si le cassoulet se dessèche. Laisser se former une dernière croûte bien dorée avant de servir."]'::jsonb),
('Pot-au-feu', 'Bœuf et légumes-racines mijotés longuement dans un bouillon clair, servi en deux temps : bouillon puis viande.', 30, 180, 6, 1, 'protéiné', '["français", "mijoté", "famille", "économique", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Mettre les viandes dans une grande marmite, couvrir largement d''eau froide, porter lentement à ébullition et écumer soigneusement pendant 10 min.", "Ajouter les oignons piqués des clous de girofle, l''ail, le bouquet garni, le gros sel et le poivre en grains. Laisser mijoter à découvert, à tout petits frémissements, pendant 2h.", "Éplucher les carottes et les navets et les couper en deux. Les ajouter et poursuivre la cuisson 40 min.", "Ajouter les poireaux ficelés en botte et le céleri, et cuire encore 30 min, jusqu''à ce que viande et légumes soient bien tendres.", "Frotter les extrémités des os à moelle de gros sel (cela empêche la moelle de s''échapper), les envelopper dans une mousseline et les pocher 20 min dans le bouillon.", "Servir le bouillon dégraissé en entrée avec du pain grillé et la moelle, puis la viande tranchée et les légumes avec du gros sel et de la moutarde."]'::jsonb),
('Gratin dauphinois', 'Pommes de terre en fines lamelles cuites lentement dans la crème et le lait, sans œuf ni fromage dans la version traditionnelle.', 20, 75, 6, 1, 'gras', '["français", "accompagnement", "économique", "four", "plat"]'::jsonb, 'public', '["oven"]'::jsonb, '["Préchauffer le four à 150°C. Éplucher les pommes de terre et les couper en rondelles régulières de 3 mm (à la mandoline de préférence), sans les rincer pour garder leur amidon : c''est lui qui lie la crème.", "Frotter un plat à gratin avec la gousse d''ail coupée en deux, puis le beurrer généreusement.", "Disposer les pommes de terre en couches régulières, en salant, poivrant et râpant un peu de muscade entre chaque couche.", "Chauffer la crème et le lait sans les faire bouillir et verser sur les pommes de terre, jusqu''à affleurer la dernière couche.", "Cuire 1h15 à 1h30, jusqu''à ce qu''une pointe de couteau s''enfonce sans résistance et que le dessus soit bien doré.", "Laisser reposer 10 min avant de servir : le gratin se tient mieux tiède que brûlant."]'::jsonb),
('Salade niçoise', 'Une salade méditerranéenne fraîche à base de légumes crus, thon ou anchois, œufs durs et olives.', 20, 10, 4, 1, 'light', '["français", "salade", "méditerranéen", "léger", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Plonger les œufs dans l''eau bouillante et les cuire 9 min, puis les refroidir dans l''eau froide et les écaler.", "Couper les tomates en quartiers et les saler légèrement. Couper le poivron en fines lanières, le concombre et les radis en rondelles et émincer finement l''oignon rouge.", "Disposer les légumes sur un grand plat, ajouter le thon émietté, les filets d''anchois et les olives.", "Couper les œufs en quartiers et les répartir sur la salade.", "Mélanger l''huile d''olive, le vinaigre, le sel et le poivre, arroser la salade et parsemer de basilic ciselé juste avant de servir."]'::jsonb),
('Croque-monsieur', 'Un sandwich chaud au jambon et à la béchamel, gratiné au fromage.', 10, 10, 2, 1, 'gras', '["français", "rapide", "économique", "étudiant", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Préparer une béchamel : fondre le beurre, ajouter la farine, cuire 1 min, verser le lait chaud en fouettant jusqu''à épaississement. Assaisonner de muscade et de moutarde.", "Tartiner deux tranches de pain de béchamel, garnir de jambon et d''un peu de fromage, refermer avec les tranches restantes.", "Napper le dessus de béchamel et parsemer généreusement de fromage râpé.", "Cuire à la poêle à feu doux à couvert, ou 8 min au four à 200°C, jusqu''à ce que le fromage soit doré et fondant."]'::jsonb),
('Mousse au chocolat', 'Chocolat noir fondu et blancs en neige, sans crème ni gélatine — la texture vient uniquement de l''air battu.', 20, 5, 6, 1, 'gras', '["français", "dessert", "économique", "goûter"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire fondre le chocolat au bain-marie ou à faible puissance au micro-ondes, en remuant, puis laisser tiédir.", "Séparer les blancs des jaunes. Incorporer les jaunes un à un dans le chocolat tiède.", "Monter les blancs en neige ferme avec une pincée de sel, en ajoutant le sucre en pluie à mi-parcours.", "Incorporer un tiers des blancs au chocolat pour le détendre, puis le reste délicatement à la maryse, en soulevant la masse.", "Répartir dans des verrines et réfrigérer au moins 4h avant de servir.", "Utiliser des œufs très frais : la mousse contient des œufs crus, déconseillée aux femmes enceintes et aux jeunes enfants."]'::jsonb),
('Crêpes', 'Une pâte fine à base de farine, œufs et lait, cuite à la poêle bien chaude.', 15, 20, 4, 1, 'gras', '["français", "économique", "étudiant", "petit-déjeuner", "goûter"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Mélanger la farine, le sucre et le sel dans un saladier, creuser un puits et casser les œufs au centre.", "Fouetter en incorporant peu à peu le lait pour éviter les grumeaux, jusqu''à obtenir une pâte lisse et fluide.", "Ajouter le beurre fondu et l''arôme choisi, laisser reposer la pâte 30 min à température ambiante.", "Chauffer une poêle légèrement huilée à feu moyen-vif, verser une louche de pâte en inclinant la poêle pour l''étaler finement.", "Cuire 1 à 2 min jusqu''à ce que les bords se détachent, retourner et cuire 1 min de plus. Empiler les crêpes au fur et à mesure.", "Garnir de sucre, de confiture ou de pâte à tartiner. La pâte donne environ 16 crêpes."]'::jsonb),
('Tarte aux pommes', 'Une pâte brisée garnie de pommes fines, simple et rapide, sans crème pâtissière.', 25, 40, 8, 1, 'gras', '["français", "dessert", "économique", "four", "goûter"]'::jsonb, 'public', '["oven"]'::jsonb, '["Préchauffer le four à 190°C. Foncer un moule à tarte de 26 à 28 cm avec la pâte brisée et piquer le fond à la fourchette.", "Éplucher les pommes, retirer le cœur et les couper en tranches fines et régulières de 3 mm.", "Disposer les tranches en rosace sur la pâte, en cercles concentriques bien serrés.", "Saupoudrer de sucre et de cannelle et parsemer de petits morceaux de beurre.", "Cuire 35 à 40 min, jusqu''à ce que les pommes soient dorées sur les bords et que le dessous de la pâte soit cuit.", "Chauffer la confiture d''abricot avec une cuillère d''eau et en badigeonner la tarte tiède au pinceau pour la faire briller."]'::jsonb),
('Poulet basquaise', 'Poulet mijoté avec poivrons, tomates et piment d''Espelette, spécialité du Pays basque.', 20, 50, 4, 1, 'protéiné', '["français", "mijoté", "famille", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper chaque cuisse en deux au niveau de la jointure (haut de cuisse et pilon). Saler et poivrer. Peler les tomates (30 secondes dans l''eau bouillante) et les concasser. Couper les poivrons en lanières, émincer les oignons et le jambon.", "Dans une cocotte, faire dorer les morceaux de poulet dans l''huile d''olive 8 à 10 min sur toutes les faces, puis les réserver.", "Dans la même cocotte, faire revenir oignons, poivrons et jambon 8 min à feu moyen, jusqu''à ce qu''ils ramollissent.", "Ajouter l''ail haché, les tomates et le piment d''Espelette et cuire 5 min.", "Remettre le poulet, verser le vin blanc, couvrir et laisser mijoter 35 à 40 min à feu doux, jusqu''à ce que la chair se détache de l''os. Pendant ce temps, cuire le riz.", "Rectifier l''assaisonnement et servir avec le riz."]'::jsonb),
('Choucroute garnie', 'Chou fermenté mijoté au vin blanc avec charcuteries variées, spécialité alsacienne.', 20, 90, 6, 2, 'gras', '["français", "famille", "hiver", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Rincer la choucroute et l''essorer légèrement. Faire fondre la graisse d''oie dans une grande cocotte et y faire revenir l''oignon émincé.", "Ajouter la choucroute, le lard, les baies de genièvre et le vin blanc, mélanger.", "Enfouir la poitrine fumée et le jarret dans la choucroute, couvrir et mijoter 1h15 à feu doux.", "Ajouter les pommes de terre épluchées entières et poursuivre la cuisson 25 min.", "Ajouter les saucisses pour les 10 dernières minutes, juste pour les réchauffer.", "Dresser la choucroute avec les viandes tranchées, les saucisses et les pommes de terre autour."]'::jsonb),
('Clafoutis aux cerises', 'Un appareil à flan versé sur des cerises entières et cuit au four, dessert économique et rapide.', 15, 40, 6, 1, 'gras', '["français", "dessert", "économique", "four", "goûter"]'::jsonb, 'public', '["oven"]'::jsonb, '["Préchauffer le four à 180°C. Beurrer un plat à gratin et y répartir les cerises lavées et équeutées en une couche régulière. Traditionnellement, on ne les dénoyaute pas : les noyaux parfument le clafoutis (prévenir les convives).", "Fouetter les œufs avec le sucre jusqu''à ce que le mélange blanchisse, puis ajouter la farine et le sel.", "Incorporer le lait petit à petit en fouettant pour obtenir une pâte lisse et fluide, et ajouter la vanille.", "Verser l''appareil sur les cerises.", "Cuire 35 à 40 min, jusqu''à ce que le clafoutis soit doré et pris au centre (une lame plantée au centre ressort propre).", "Servir tiède, saupoudré de sucre glace si on le souhaite."]'::jsonb),
('Tartiflette', 'Pommes de terre, lardons et oignons gratinés sous un reblochon fondant, spécialité savoyarde.', 20, 45, 4, 1, 'gras', '["français", "famille", "four", "montagne", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Cuire les pommes de terre en robe des champs 20 min dans l''eau bouillante salée, puis les éplucher et les couper en rondelles épaisses. Préchauffer le four à 200°C.", "Faire revenir les lardons à la poêle 5 min, ajouter l''oignon émincé et cuire encore 5 min jusqu''à coloration.", "Déglacer au vin blanc, laisser réduire 1 min, puis ajouter la crème fraîche et poivrer. Peu de sel : lardons et reblochon sont déjà salés.", "Disposer la moitié des pommes de terre dans un plat à gratin, couvrir de la moitié du mélange lardons-oignons et répéter.", "Couper le reblochon en deux dans l''épaisseur et poser les deux moitiés, croûte vers le haut, sur le gratin.", "Cuire 20 à 25 min, jusqu''à ce que le fromage soit fondu, doré et bouillonnant."]'::jsonb),
('Œufs mimosa', 'Des œufs durs coupés en deux, jaunes mélangés à la mayonnaise et remis en dôme, classique d''entrée économique.', 20, 10, 4, 1, 'protéiné', '["français", "entrée", "économique", "apéro", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Cuire les œufs 10 min à l''eau bouillante, les refroidir à l''eau froide et les écaler.", "Couper les œufs en deux dans la longueur, retirer délicatement les jaunes et les réserver dans un bol.", "Écraser les jaunes à la fourchette avec la mayonnaise et la moutarde jusqu''à obtenir une pâte lisse, assaisonner.", "Garnir les blancs d''œufs de ce mélange à la cuillère ou à la poche, en formant un petit dôme.", "Parsemer de ciboulette ciselée et d''une pincée de paprika avant de servir frais."]'::jsonb),
('Far breton', 'Un flan dense aux pruneaux, spécialité bretonne simple et bon marché.', 15, 45, 8, 1, 'gras', '["français", "dessert", "économique", "four", "goûter"]'::jsonb, 'public', '["oven"]'::jsonb, '["Faire tremper les pruneaux dans le rhum tiède 30 min.", "Fouetter les œufs avec le sucre jusqu''à ce que le mélange blanchisse, puis ajouter la farine et le sel et bien mélanger.", "Incorporer le lait petit à petit, puis le beurre fondu, jusqu''à obtenir une pâte lisse et liquide. Si possible, laisser reposer 1h.", "Préchauffer le four à 200°C. Beurrer un plat, y répartir les pruneaux égouttés et verser la pâte avec le rhum.", "Cuire 10 min à 200°C puis 35 à 40 min à 180°C, jusqu''à ce que le far soit bien doré et gonflé, encore légèrement tremblant au centre.", "Laisser refroidir complètement avant de découper : il se tient en refroidissant."]'::jsonb),
('Soupe au pistou', 'Une soupe de légumes d''été liée au pistou de basilic, ail et parmesan, sans viande.', 25, 45, 6, 1, 'light', '["français", "soupe", "végétarien", "été", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper les courgettes, les pommes de terre et les carottes en petits dés, les haricots verts en tronçons de 2 cm, et peler puis concasser les tomates.", "Mettre tous ces légumes dans une grande marmite avec 2 litres d''eau salée, porter à ébullition et cuire 25 min à frémissement.", "Ajouter les haricots blancs rincés et les pâtes et cuire encore 8 à 10 min, jusqu''à ce que les pâtes soient tendres.", "Pendant ce temps, préparer le pistou : piler au mortier l''ail avec une pincée de sel, ajouter le basilic et le piler, puis le parmesan râpé, et incorporer l''huile d''olive en filet (ou mixer brièvement).", "Poivrer la soupe et la servir bien chaude, avec une cuillère de pistou ajoutée dans chaque assiette au moment de manger : cuit, il perdrait sa fraîcheur."]'::jsonb),
('Camembert rôti au four', 'Un camembert entier fondu au four, à tartiner à la cuillère — apéritif rapide et convivial.', 5, 20, 4, 1, 'gras', '["français", "apéro", "rapide", "économique"]'::jsonb, 'public', '["oven"]'::jsonb, '["Préchauffer le four à 180°C. Retirer l''emballage et l''étiquette du camembert et le remettre dans sa boîte en bois, en vérifiant qu''elle n''a pas d''agrafe métallique (sinon utiliser un petit plat).", "Inciser le dessus en croisillons et glisser de fines lamelles d''ail dans les entailles.", "Parsemer de thym, arroser de miel et parsemer de noix concassées.", "Poser la boîte sur une plaque et cuire 15 à 20 min, jusqu''à ce que le centre soit coulant quand on appuie dessus.", "Servir aussitôt avec des tranches de baguette grillées à tremper dedans."]'::jsonb),
('Spaghetti carbonara', 'Pâtes à base de quatre ingrédients : guanciale, œufs, pecorino et poivre. Sans crème, il n''y en a jamais eu.', 10, 15, 2, 2, 'gras', '["italien", "pâtes", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Porter une grande casserole d''eau à ébullition et bien la saler — c''est le seul sel du plat.", "Mettre le guanciale dans une poêle froide et chauffer à feu moyen jusqu''à ce qu''il soit doré et croustillant, 6-8 min.", "Pendant ce temps, battre 3 jaunes d''œufs (les blancs se gardent pour une autre recette), 1 œuf entier, le pecorino râpé et le poivre en pâte épaisse, à température ambiante.", "Cuire les spaghetti une minute de moins que le temps indiqué, en réservant un verre d''eau de cuisson avant l''égouttage.", "Hors du feu, ajouter les pâtes à la poêle et mélanger avec la graisse. Laisser tiédir 20 secondes.", "Verser le mélange aux œufs et mélanger vivement en ajoutant l''eau de cuisson jusqu''à obtenir une sauce lisse et nappante. Servir aussitôt."]'::jsonb),
('Risotto alla milanese', 'Risotto au safran, à base de bouillon et d''un brassage quasi constant qui libère l''amidon du riz.', 10, 25, 4, 2, 'gras', '["italien", "végétarien", "riz", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Infuser le safran dans une louche de bouillon chaud ; garder le reste du bouillon frémissant.", "Faire fondre la moitié du beurre et suer l''oignon à feu doux jusqu''à ce qu''il soit translucide, environ 8 min.", "Ajouter le riz et remuer 2 min jusqu''à ce que les grains soient nacrés (la tostatura).", "Verser le vin et laisser s''évaporer complètement.", "Ajouter le bouillon louche par louche en remuant, environ 18 min, jusqu''à ce que le riz soit crémeux à l''extérieur et encore ferme au centre.", "Incorporer le safran, retirer du feu et ajouter le beurre froid et le parmesan en secouant la casserole pour lier le risotto."]'::jsonb),
('Pizza margherita', 'Une pâte longuement fermentée, tomate crue, mozzarella et basilic. Ici, c''est le temps qui fait tout, pas le nombre d''ingrédients.', 60, 10, 4, 2, 'gras', '["italien", "végétarien", "four", "plat"]'::jsonb, 'public', '["oven"]'::jsonb, '["Dissoudre la levure dans l''eau, ajouter la farine et mélanger grossièrement. Laisser reposer 20 min puis incorporer le sel et pétrir 10 min.", "Laisser lever 2h à température ambiante, diviser en 4 pâtons et réfrigérer 24h.", "Sortir la pâte 3h avant la cuisson. Écraser les tomates à la main avec une pincée de sel pour la sauce.", "Préchauffer le four avec une pierre ou plaque à sa puissance maximale pendant au moins 1h.", "Étaler un pâton du centre vers les bords avec les doigts, sans rouleau, en laissant la bordure intacte.", "Étaler une fine couche de sauce, ajouter la mozzarella et un filet d''huile. Cuire 7-9 min jusqu''à ce que la bordure soit marbrée, puis ajouter le basilic."]'::jsonb),
('Lasagnes bolognaise', 'Pâtes, ragù et béchamel en couches. Le ragù mijote trois heures au lait et au vin plutôt qu''à la tomate.', 40, 220, 8, 3, 'gras', '["italien", "four", "famille", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Hacher finement l''oignon, la carotte et le céleri. Faire revenir la pancetta en petits dés dans une cocotte, ajouter les légumes et les laisser suer 15 à 20 min à feu doux, jusqu''à ce qu''ils soient fondants.", "Ajouter les viandes et les cuire à feu vif en les émiettant, jusqu''à ce que toute l''eau soit évaporée et qu''elles commencent à colorer.", "Verser 300 ml de lait et laisser réduire presque à sec (20 min), puis le vin de la même façon.", "Ajouter le concentré de tomate et le bouillon, saler, poivrer, porter à ébullition et laisser mijoter 3h à couvert à feu très doux, en ajoutant un peu d''eau si ça attache.", "Béchamel : faire fondre le beurre, ajouter la farine et cuire 1 min, puis verser le reste du lait (1 L), chaud, en filet en fouettant jusqu''à épaississement. Saler, poivrer et ajouter la muscade.", "Préchauffer le four à 180°C. Dans un grand plat, monter les couches : béchamel, feuilles de lasagne, ragù, béchamel, parmesan. Répéter 4 à 5 fois et terminer par la béchamel et le parmesan.", "Cuire 40 min, couvert d''aluminium les 30 premières minutes. Laisser reposer 20 min avant de découper pour que les couches se tiennent."]'::jsonb),
('Tiramisu', 'Biscuits savoiardi imbibés de café sous une crème au mascarpone. Sans cuisson, mais deux étapes où tout peut basculer.', 30, 0, 6, 2, 'gras', '["italien", "dessert", "sans cuisson", "goûter"]'::jsonb, 'public', '[]'::jsonb, '["Séparer les blancs des jaunes. Fouetter les 4 jaunes avec la moitié du sucre au bain-marie sans toucher l''eau, jusqu''à blanchir et épaissir, environ 7 min. Laisser refroidir.", "Incorporer le mascarpone froid à la cuillère, jamais au fouet électrique, sinon la crème devient granuleuse.", "Monter 2 blancs (les 2 autres se congèlent pour une autre recette) avec le reste du sucre en pics fermes et les incorporer délicatement en trois fois.", "Mélanger le café et le marsala. Tremper chaque biscuit une seconde par face et les disposer en couche serrée.", "Étaler la moitié de la crème, répéter une couche de biscuits et de crème. Couvrir et réfrigérer au moins 6h, idéalement toute la nuit.", "Saupoudrer de cacao au tamis juste avant de servir.", "Utiliser des œufs très frais : le tiramisu contient des œufs crus, déconseillé aux femmes enceintes et aux jeunes enfants."]'::jsonb),
('Soupe miso', 'Une soupe de dashi et miso prête en dix minutes. Le miso ne doit jamais bouillir, sous peine de perdre arôme et intérêt.', 5, 15, 4, 1, 'light', '["japonais", "soupe", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couvrir le kombu d''eau froide et chauffer doucement jusqu''à frémissement, environ 10 min ; retirer l''algue avant l''ébullition.", "Porter l''eau à ébullition, ajouter les copeaux de bonite, retirer du feu aussitôt et laisser infuser 2 min.", "Filtrer sans presser les copeaux, sous peine d''amertume.", "Faire tremper le wakame 5 min dans l''eau froide.", "Réchauffer le dashi, ajouter le tofu et le wakame, chauffer doucement 2 min.", "Délayer le miso dans une louche de bouillon chaud, remettre dans la casserole et retirer immédiatement du feu. Parsemer d''oignon nouveau."]'::jsonb),
('Ramen shoyu', 'Bouillon, tare et huile assemblés dans le bol plutôt que cuits ensemble.', 30, 180, 4, 3, 'protéiné', '["japonais", "soupe", "mijoté", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couvrir les carcasses d''eau froide, porter à ébullition 10 min, puis jeter l''eau et rincer les os et la marmite : le bouillon sera plus clair.", "Rouler la poitrine de porc et la ficeler. Remettre les carcasses dans la marmite avec 3 litres d''eau fraîche, le gingembre en tranches, l''ail écrasé et la poitrine. Mijoter à petits frémissements 3h en écumant. Retirer la poitrine après 2h30, quand elle est tendre, et la laisser tiédir.", "Ajouter le kombu 20 min avant la fin de la cuisson du bouillon et le retirer avant qu''il ne bouille. Filtrer le bouillon.", "Tare : porter à frémissement la sauce soja, le mirin, le saké et les shiitake, et laisser réduire d''un tiers. Filtrer.", "Cuire les œufs 6 min 30 dans l''eau bouillante, les refroidir dans l''eau glacée, les écaler et les faire mariner 2h dans une partie du tare, couverts.", "Trancher la poitrine en tranches de 5 mm et les saisir 1 min par face dans une poêle chaude avec un peu de tare.", "Cuire les nouilles séparément selon le temps indiqué et les égoutter. Mettre 2 c.à.s de tare au fond de chaque bol, ajouter les nouilles puis le bouillon bouillant. Garnir de porc, d''un demi-œuf, d''oignon nouveau ciselé et d''un filet d''huile de sésame."]'::jsonb),
('Tempura', 'Légumes et crevettes dans une pâte glacée et grumeleuse. La lisser complètement serait justement l''erreur à ne pas commettre.', 25, 20, 4, 2, 'light', '["japonais", "friture", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Inciser les crevettes trois fois sur la face intérieure pour les empêcher de s''enrouler à la cuisson.", "Mélanger dashi, soja et mirin, porter à ébullition puis retirer du feu : c''est le tentsuyu, à servir avec le daikon râpé.", "Chauffer l''huile à 180°C. Ne préparer la pâte qu''une fois l''huile prête.", "Battre l''œuf froid dans l''eau glacée, ajouter farine et fécule et mélanger 5-6 coups aux baguettes, sans lisser.", "Fariner les morceaux, les tremper dans la pâte et les plonger par 3-4 dans l''huile. Frire 1 à 2 min.", "Égoutter sur une grille, jamais sur du papier, en écumant les résidus de pâte entre les fournées."]'::jsonb),
('Guacamole', 'Avocat, citron vert, oignon et piment écrasés à la fourchette. Ni mixeur ni crème fraîche : les deux en feraient une simple sauce.', 15, 0, 4, 1, 'light', '["mexicain", "apéro", "sans cuisson", "végan"]'::jsonb, 'public', '[]'::jsonb, '["Couper les avocats en deux, retirer les noyaux et prélever la chair.", "Ajouter aussitôt le jus de citron vert et le sel, avant que la chair ne s''oxyde.", "Écraser à la fourchette en une purée grossière, en laissant des morceaux.", "Incorporer l''oignon, le jalapeño et la coriandre, goûter et rectifier. Ajouter la tomate en dernier, délicatement.", "Servir aussitôt ; si besoin d''attendre, filmer au contact pour éviter l''oxydation."]'::jsonb),
('Tacos al pastor', 'Porc mariné aux piments séchés et à l''ananas, saisi jusqu''à caraméliser, dans une tortilla de maïs.', 30, 20, 4, 2, 'protéiné', '["mexicain", "épicé", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Épépiner les piments et les torréfier à sec dans une poêle 20 secondes par face, puis les couvrir d''eau bouillante et les laisser tremper 15 min.", "Mixer les piments égouttés avec la moitié de l''ananas, l''achiote, le vinaigre, l''ail, le cumin, l''origan et une pincée de sel, jusqu''à obtenir une pâte lisse.", "Couper le porc en tranches fines de 5 mm, l''enrober de marinade et laisser reposer au réfrigérateur au moins 2h, idéalement toute la nuit (pas plus de 24h).", "Saisir la viande par petites quantités dans une poêle très chaude, 2 min par face, sans remuer, jusqu''à ce qu''elle caramélise et soit bien cuite.", "Saisir le reste de l''ananas en tranches dans la même poêle et le couper en dés. Hacher la viande grossièrement.", "Réchauffer les tortillas 20 secondes par face dans une poêle sèche et garnir de viande, d''ananas, d''oignon et de coriandre hachés, avec un quartier de citron vert."]'::jsonb),
('Paella valenciana', 'Riz en large poêle avec poulet, lapin et haricots. On ne le remue jamais une fois le riz versé — c''est ce qui donne la croûte du fond.', 25, 45, 4, 2, 'protéiné', '["espagnol", "riz", "famille", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Chauffer l''huile dans une large poêle et faire dorer le poulet et le lapin sur toutes les faces, environ un quart d''heure.", "Pousser la viande sur les bords, faire revenir les haricots verts au centre, ajouter la tomate râpée et le paprika et cuire jusqu''à ce que la tomate perde son goût cru.", "Verser le bouillon, ajouter romarin, safran et haricots blancs, saler franchement et laisser bouillir 10 min.", "Répartir le riz en couche régulière et l''égaliser une fois à la cuillère. Ne plus toucher la poêle ensuite.", "Cuire à feu vif 10 min puis à feu moyen 8 min de plus, jusqu''à absorption du bouillon.", "Monter le feu 30 secondes pour obtenir le socarrat (le riz doit crépiter plutôt que bouillonner), puis couvrir d''un linge et laisser reposer 5 min."]'::jsonb),
('Moussaka', 'Aubergines, sauce à la viande et à la cannelle, épaisse couche de béchamel, cuites au four jusqu''à bien se tenir.', 40, 75, 6, 3, 'gras', '["grec", "four", "famille", "plat"]'::jsonb, 'public', '["oven"]'::jsonb, '["Préchauffer le four à 200°C. Couper les aubergines en tranches de 1 cm, les saler et les laisser dégorger 30 min, puis les éponger. Éplucher les pommes de terre et les couper en rondelles de 5 mm.", "Étaler aubergines et pommes de terre sur des plaques couvertes de papier cuisson, les badigeonner d''huile et les rôtir 20 à 25 min, jusqu''à ce qu''elles soient tendres et dorées.", "Faire revenir l''oignon haché dans un peu d''huile, ajouter la viande et la cuire à feu vif en l''émiettant jusqu''à ce que toute l''eau soit évaporée. Déglacer au vin et laisser réduire.", "Ajouter l''ail, les tomates et la cannelle, saler et poivrer et laisser mijoter 20 min, jusqu''à obtenir une sauce épaisse.", "Béchamel : faire fondre le beurre, ajouter la farine, cuire 1 min puis verser le lait chaud en fouettant jusqu''à épaississement. Hors du feu, ajouter la muscade, les jaunes d''œufs et la moitié du fromage râpé.", "Baisser le four à 180°C. Dans un plat, monter les couches : pommes de terre, la moitié des aubergines, la sauce à la viande, le reste des aubergines. Napper de béchamel et parsemer du reste de fromage.", "Cuire 45 min, jusqu''à ce que le dessus soit bien doré. Laisser reposer 30 min avant de découper, sinon les couches s''effondrent."]'::jsonb),
('Souvlaki', 'Porc en brochettes au citron, origan et huile d''olive, cuit rapidement à feu vif.', 20, 15, 4, 1, 'protéiné', '["grec", "grillade", "rapide", "plat"]'::jsonb, 'public', '["grill"]'::jsonb, '["Couper la viande en cubes de 3 cm en retirant les gros morceaux de gras. Mélanger l''huile, le jus et le zeste du citron, l''origan, deux gousses d''ail écrasées, du sel et du poivre, y enrober la viande et laisser mariner 2 à 4h au réfrigérateur.", "Tzatziki : râper le concombre, le saler, le laisser dégorger 10 min et le presser fortement. Le mélanger au yaourt avec la dernière gousse d''ail écrasée, une cuillère d''huile et du sel.", "Si les brochettes sont en bois, les faire tremper 30 min dans l''eau. Enfiler la viande sans trop serrer, pour que la chaleur circule entre les morceaux.", "Cuire sur un grill ou une plancha bien chaude, 3 min sur chacune des 4 faces, jusqu''à ce que la viande soit bien dorée et cuite à cœur.", "Laisser reposer 5 min, réchauffer les pitas 30 secondes par face et servir avec le tzatziki et des quartiers de citron."]'::jsonb),
('Fattet hommous', 'Des couches de pain pita frit, de pois chiches chauds et de yaourt à l''ail, avec du beurre doré et des pignons.', 30, 90, 5, 1, 'light', '["libanais", "végétarien", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["La veille, faire tremper les pois chiches secs 12h dans trois fois leur volume d''eau froide avec le bicarbonate.", "Les égoutter, les rincer et les cuire à petits frémissements dans de l''eau non salée 1h à 1h30, jusqu''à ce qu''ils s''écrasent facilement entre les doigts. Saler en fin de cuisson et garder l''eau de cuisson.", "Déchirer les pitas en morceaux et les frire dans l''huile chaude 2 à 3 min, jusqu''à ce qu''ils soient dorés et croustillants. Égoutter sur du papier absorbant.", "Fouetter le yaourt avec le tahini, l''ail écrasé, le jus de citron et du sel, puis le détendre avec quelques cuillères d''eau de cuisson des pois chiches, jusqu''à la consistance d''une crème épaisse.", "Faire dorer les pignons dans le ghee à feu moyen 2 à 3 min, en surveillant : ils brûlent vite.", "Étaler le pain frit dans un plat creux, couvrir des pois chiches chauds et d''un peu de leur jus.", "Napper de yaourt, arroser du ghee chaud avec les pignons, saupoudrer de paprika et de persil haché, et servir aussitôt pour que le pain reste croustillant."]'::jsonb),
('Bibimbap', 'Riz surmonté de légumes cuits séparément, de viande et d''un œuf, mélangés au gochujang juste avant de manger.', 40, 20, 4, 2, 'protéiné', '["coréen", "riz", "bowl", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Rincer le riz jusqu''à ce que l''eau soit claire, le mettre dans une casserole avec 360 ml d''eau, porter à ébullition, couvrir et cuire 12 min à feu très doux, puis laisser reposer 10 min sans ouvrir.", "Trancher le bœuf très finement et le mariner 20 min avec la sauce soja, le sucre, une gousse d''ail hachée et une cuillère d''huile de sésame.", "Blanchir les épinards 30 secondes dans l''eau bouillante, les refroidir, les presser et les assaisonner d''huile de sésame, de sel et d''ail. Cuire les pousses de soja 3 min dans la même eau et les assaisonner de la même façon.", "Dans un peu d''huile neutre, faire sauter séparément la carotte en julienne 2 min et les shiitake émincés 3 min, en salant chaque légume.", "Saisir le bœuf à feu vif 2 min. Cuire les œufs au plat dans une autre poêle, jaune coulant.", "Répartir le riz chaud dans les bols, disposer les légumes et le bœuf en sections, poser l''œuf au centre avec une cuillère de gochujang et parsemer de sésame. Chacun mélange son bol avant de manger."]'::jsonb),
('Baklava', 'Quarante couches de feuilles de yufka à la pistache, imbibées de sirop. Le baklava chaud reçoit le sirop froid, jamais l''inverse.', 60, 60, 12, 3, 'gras', '["turc", "dessert", "four", "goûter"]'::jsonb, 'public', '["oven"]'::jsonb, '["Préparer le sirop : porter le sucre et l''eau à ébullition, cuire 15 min, ajouter le citron et laisser refroidir complètement.", "Faire fondre le beurre et le laisser reposer ; utiliser seulement la couche claire du dessus, jeter le dépôt.", "Disposer vingt feuilles dans un plat beurré, en beurrant chacune. Répartir les pistaches en couche régulière.", "Couvrir de vingt feuilles supplémentaires, en beurrant chacune, la dernière généreusement.", "Découper en losanges avec un couteau bien aiguisé, jusqu''au fond du plat.", "Cuire à 170°C pendant 1h, à belle coloration dorée. Verser aussitôt le sirop froid dans les découpes.", "Laisser reposer 6h, idéalement toute la nuit, avant de servir."]'::jsonb),
('Moules marinières', 'Moules cuites à la vapeur de vin blanc, céleri et oignon. Cinq minutes sous couvercle, pas plus.', 25, 15, 4, 1, 'light', '["belge", "fruits de mer", "rapide", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Préchauffer le four à 220°C et y cuire les frites 20 à 25 min en les retournant à mi-cuisson, pour qu''elles soient prêtes en même temps que les moules (ou utiliser une friteuse).", "Trier les moules : jeter celles qui sont cassées ou qui restent ouvertes quand on les tapote. Retirer les filaments (byssus) et les rincer rapidement à l''eau froide, sans les laisser tremper.", "Dans une grande marmite, faire fondre le beurre et suer les échalotes, le céleri et l''ail hachés 5 min sans coloration.", "Verser le vin, ajouter le thym et le laurier et porter à ébullition.", "Ajouter les moules, couvrir aussitôt et cuire à feu vif 5 min en secouant la marmite deux fois.", "Vérifier que les coquilles sont ouvertes et jeter celles qui sont restées fermées. Parsemer de persil haché, poivrer et servir avec les frites et le jus de cuisson."]'::jsonb),
('Phô bo', 'Un bouillon de bœuf clair au gingembre grillé et épices entières, nouilles de riz et bœuf qui finit de cuire dans le bol.', 30, 240, 4, 3, 'protéiné', '["vietnamien", "soupe", "mijoté", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couvrir les os d''eau froide, porter à ébullition 10 min, jeter l''eau et rincer les os et la marmite : c''est ce qui donne un bouillon clair.", "Couper oignons et gingembre en deux et griller les faces coupées à sec dans une poêle, jusqu''à ce qu''elles noircissent par endroits.", "Torréfier les épices (badiane, cannelle, girofle, coriandre) 1 min à sec et les nouer dans une mousseline. Remettre les os dans la marmite propre avec la poitrine, l''oignon, le gingembre et les épices, et couvrir de 4 litres d''eau.", "Mijoter 3h à frémissement léger, en écumant pendant la première demi-heure. Retirer la poitrine après 1h30 et la laisser refroidir.", "Filtrer le bouillon et l''assaisonner de nuoc-mâm et de sucre : il doit être légèrement plus salé qu''agréable seul, car les nouilles en absorberont une partie.", "Placer le faux-filet 20 min au congélateur puis le trancher le plus finement possible. Trancher aussi la poitrine refroidie.", "Faire tremper les nouilles 30 min dans l''eau froide, puis les plonger 30 secondes à 1 min dans l''eau bouillante et les égoutter.", "Répartir les nouilles dans les bols, disposer la poitrine et le faux-filet cru dessus et napper de bouillon bouillant, qui cuit la viande. Servir avec les herbes, le citron vert et le piment."]'::jsonb),
('Bánh mì', 'Une baguette française garnie à la vietnamienne : pâté, porc, légumes marinés et coriandre dans un seul sandwich.', 25, 15, 4, 1, 'protéiné', '["vietnamien", "sandwich", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper la carotte et le daikon en fine julienne. Dissoudre le vinaigre, le sucre et une pincée de sel dans 100 ml d''eau tiède, verser sur les légumes et laisser mariner 1h.", "Couper le porc en tranches de 5 mm et le mariner 20 min avec le nuoc-mâm et une cuillère de sucre.", "Saisir le porc dans une poêle très chaude 2 à 3 min par face, jusqu''à ce qu''il caramélise et soit bien cuit.", "Couper chaque baguette en deux, les réchauffer 5 min dans le four à 200°C pour raviver la croûte, puis fendre chaque morceau sur la longueur sans séparer les deux moitiés.", "Tartiner une face de pâté et l''autre de mayonnaise. Garnir de porc, de légumes marinés bien égouttés, de lamelles de concombre, de coriandre et de piment. Refermer en appuyant et servir aussitôt."]'::jsonb),
('Poulet biryani', 'Riz et poulet mariné cuits ensemble sous couvercle : les couches cuisent à la vapeur plutôt qu''au brassage.', 45, 60, 6, 3, 'protéiné', '["indien", "riz", "épicé", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire dorer les oignons dans le ghee à coloration profonde, environ 20 min. En réserver la moitié : c''est le birista, l''arôme principal du plat.", "Mariner le poulet dans le yaourt avec gingembre, ail, épices, la moitié des oignons dorés, menthe et sel, 1h minimum, idéalement 3h.", "Cuire le riz dans une grande quantité d''eau salée avec les épices entières exactement 5 min, puis égoutter.", "Étaler le poulet mariné au fond d''une cocotte, couvrir du riz en couche régulière, arroser du lait safrané par endroits et parsemer du reste d''oignons et d''herbes.", "Couvrir hermétiquement, 5 min à feu vif puis 40 min à feu très doux, sans jamais soulever le couvercle.", "Laisser reposer 10 min puis mélanger une seule fois du bas vers le haut, en soulevant le poulet dans le riz plutôt qu''en remuant."]'::jsonb),
('Poulet Rôti aux Herbes', 'Un poulet entier rôti au four avec un beurre aux herbes glissé sous la peau : chair juteuse, peau croustillante.', 20, 75, 4, 2, 'protéiné', '["poulet", "viande", "four", "classique", "plat"]'::jsonb, 'public', '["oven"]'::jsonb, '["Sortir le poulet du réfrigérateur 30 min avant la cuisson. Préchauffer le four à 210°C (chaleur statique).", "Effeuiller la moitié du thym et hacher finement une branche de romarin. Écraser 2 gousses d''ail et les mélanger au beurre mou avec les herbes, 1/2 c.à.c de sel et du poivre.", "Sécher le poulet avec du papier absorbant. Décoller délicatement la peau des blancs avec les doigts et glisser le beurre aux herbes dessous, en l''étalant bien.", "Couper le citron en quatre et le glisser dans la cavité avec le reste du thym, du romarin et 2 gousses d''ail écrasées. Ficeler les cuisses si possible.", "Poser le poulet dans un plat, badigeonner d''huile, saler toute la peau avec le reste du sel et poivrer. Disposer les gousses d''ail restantes autour et verser l''eau au fond du plat.", "Enfourner 15 min à 210°C, puis baisser à 190°C et cuire encore 55 à 60 min pour un poulet de 1,6 kg, en arrosant avec le jus du plat toutes les 20 min. Rajouter un peu d''eau si le fond commence à brûler.", "Vérifier la cuisson : en piquant la jointure entre la cuisse et le corps, le jus doit couler clair, sans trace rosée (74°C à cœur avec un thermomètre). Sinon, prolonger par tranches de 10 min.", "Sortir le poulet, le couvrir de papier aluminium sans serrer et le laisser reposer 10 min avant de découper. Servir avec le jus du plat."]'::jsonb),
('Riz Complet aux Légumes', 'Du riz complet cuit par absorption dans un bouillon, mêlé à des légumes sautés qui restent croquants.', 15, 50, 2, 1, 'light', '["riz", "légumes", "végétarien", "sain", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Rincer le riz complet dans une passoire sous l''eau froide jusqu''à ce que l''eau soit presque claire. Faire chauffer le bouillon.", "Dans une casserole, faire revenir la moitié de l''oignon émincé dans 1 c.à.s d''huile 3 min à feu moyen. Ajouter le riz et remuer 1 min pour bien l''enrober.", "Verser le bouillon chaud, porter à ébullition, puis couvrir et cuire à feu très doux 40 min sans soulever le couvercle. Retirer du feu et laisser reposer 10 min à couvert : tout le liquide doit être absorbé et le grain tendre mais encore légèrement ferme.", "Pendant la cuisson du riz, détailler le brocoli en petits bouquets, la carotte en fines rondelles, la courgette en dés et le poivron en lanières.", "Dans une grande poêle, chauffer 1 c.à.s d''huile à feu vif. Faire sauter la carotte et le brocoli 4 min, puis ajouter le poivron, la courgette, le reste de l''oignon et l''ail haché et cuire encore 4 à 5 min en remuant : les légumes doivent être dorés mais croquants.", "Déglacer avec la sauce soja, mélanger avec le riz égrené à la fourchette, rectifier l''assaisonnement et servir chaud."]'::jsonb),
('Omelette aux Champignons', 'Une omelette baveuse à la française, garnie de champignons dorés au beurre et de persil.', 5, 10, 1, 1, 'protéiné', '["œufs", "champignons", "rapide", "petit-déjeuner", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Nettoyer les champignons avec un papier humide (ne pas les laisser tremper) et les couper en lamelles. Hacher le persil.", "Chauffer une poêle à feu vif avec la moitié du beurre. Quand il mousse, ajouter les champignons en une seule couche et les laisser dorer 5 à 6 min en remuant de temps en temps, jusqu''à ce que leur eau soit évaporée. Saler seulement à la fin, ajouter le persil et réserver dans une assiette.", "Battre les œufs à la fourchette avec une pincée de sel et du poivre, juste assez pour mélanger blancs et jaunes.", "Essuyer la poêle (20 cm idéalement), la remettre à feu moyen avec le reste du beurre. Quand il mousse sans brunir, verser les œufs.", "Remuer vivement avec une spatule pendant 20 à 30 secondes en secouant la poêle, puis laisser prendre sans toucher 1 min : le dessous doit être pris mais le dessus encore crémeux.", "Répartir les champignons sur une moitié, replier l''omelette et la faire glisser dans l''assiette. Servir aussitôt."]'::jsonb),
('Tacos au Poulet', 'Des tacos de poulet mariné au citron vert et aux épices, avec pico de gallo et guacamole maison.', 45, 15, 4, 1, 'protéiné', '["mexicain", "poulet", "street-food", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Mélanger le jus d''un citron vert, l''huile, l''ail pressé, le cumin, le paprika fumé, l''origan, le piment et 1 c.à.c de sel. Enrober le poulet de cette marinade et laisser 30 min au réfrigérateur (4h maximum : au-delà, l''acidité rend la viande farineuse).", "Pico de gallo : épépiner les tomates et les couper en petits dés, ajouter la moitié de l''oignon rouge finement haché, la moitié de la coriandre ciselée, un filet de jus de citron vert et une pincée de sel.", "Guacamole : écraser les avocats à la fourchette avec le jus du dernier demi-citron vert, le reste de l''oignon haché et une pincée de sel. Couvrir au contact d''un film pour éviter qu''il noircisse.", "Chauffer une poêle ou une plancha à feu moyen-vif. Égoutter le poulet et le cuire 6 à 7 min par face, jusqu''à ce qu''il soit bien doré et que la chair ne soit plus rosée au centre (74°C à cœur).", "Laisser reposer le poulet 5 min sur une planche, puis le trancher en fines lamelles.", "Réchauffer les tortillas 30 secondes de chaque côté dans une poêle sèche bien chaude et les garder enveloppées dans un torchon.", "Garnir chaque tortilla de poulet, de pico de gallo, de guacamole, d''une cuillère de crème et de coriandre. Servir avec le reste du citron vert en quartiers."]'::jsonb),
('Poke Bowl Saumon', 'Un bol hawaïen de riz vinaigré tiède, de saumon cru mariné à la sauce soja et de légumes croquants.', 30, 15, 2, 1, 'protéiné', '["hawaïen", "poisson", "frais", "bowl", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Rincer le riz à sushi dans plusieurs eaux en le frottant entre les mains, jusqu''à ce que l''eau soit claire. Égoutter 10 min.", "Mettre le riz et l''eau dans une casserole, porter à ébullition, couvrir et cuire 12 min à feu très doux. Retirer du feu et laisser reposer 10 min sans ouvrir.", "Dissoudre le sucre et le sel dans le vinaigre de riz, verser sur le riz chaud et mélanger délicatement en le soulevant à la spatule. Laisser tiédir.", "Utiliser impérativement du saumon vendu qualité sushi / sashimi (ou préalablement congelé 7 jours à -20°C). Le couper en cubes de 1,5 cm.", "Mélanger la sauce soja, l''huile de sésame et le gingembre râpé. Y enrober le saumon et laisser mariner 10 à 15 min au réfrigérateur, pas plus.", "Cuire les edamames 4 min dans l''eau bouillante salée, les refroidir sous l''eau froide. Couper l''avocat en tranches, le concombre en demi-rondelles, râper la carotte et émincer l''oignon nouveau.", "Répartir le riz dans deux bols, disposer le saumon et chaque garniture en sections, arroser du reste de marinade et parsemer de graines de sésame. Servir aussitôt."]'::jsonb),
('Curry de Pois Chiches', 'Un curry végétarien de pois chiches au lait de coco et aux épinards, servi avec du riz basmati.', 15, 35, 4, 1, 'protéiné', '["curry", "végétarien", "pois-chiches", "indien", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Émincer finement l''oignon, hacher l''ail et râper le gingembre. Égoutter et rincer les pois chiches.", "Chauffer l''huile dans une sauteuse à feu moyen et faire fondre l''oignon 8 à 10 min en remuant, jusqu''à ce qu''il soit bien doré : c''est la base du goût.", "Ajouter l''ail et le gingembre et cuire 1 min. Ajouter le curry en poudre, le cumin et le curcuma et remuer 1 min, jusqu''à ce que les épices embaument sans brûler (ajouter une cuillère d''eau si ça accroche).", "Verser les tomates concassées et cuire 5 min pour les réduire un peu. Ajouter le lait de coco, les pois chiches et le sel.", "Laisser mijoter à découvert 15 à 20 min à feu doux en remuant de temps en temps, jusqu''à ce que la sauce nappe la cuillère.", "Pendant ce temps, rincer le riz basmati, le mettre dans une casserole avec 1,5 fois son volume d''eau et une pincée de sel, porter à ébullition, couvrir et cuire 10 min à feu très doux, puis laisser reposer 5 min à couvert.", "Ajouter les épinards au curry et remuer 2 min jusqu''à ce qu''ils tombent. Hors du feu, ajouter le jus du citron vert, rectifier le sel et parsemer de coriandre. Servir avec le riz."]'::jsonb),
('Courgettes Farcies', 'Des courgettes évidées, farcies d''une viande hachée aux herbes et gratinées au four.', 25, 50, 4, 2, 'protéiné', '["légumes", "viande", "four", "provençal", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Préchauffer le four à 200°C. Couper les courgettes en deux dans la longueur et les évider à la petite cuillère en laissant 5 mm de chair sur les bords. Hacher grossièrement la chair retirée.", "Disposer les demi-courgettes dans un plat, face coupée vers le haut, badigeonner d''1 c.à.s d''huile, saler légèrement et précuire 10 min au four : elles ne rendront plus d''eau dans la farce.", "Pendant ce temps, faire revenir l''oignon haché dans le reste de l''huile 5 min à feu moyen. Ajouter l''ail haché et la chair de courgette et cuire 5 à 6 min jusqu''à ce que l''eau soit évaporée. Laisser tiédir.", "Faire tremper la mie de pain dans le lait puis l''essorer. Dans un saladier, mélanger la viande hachée, le mélange oignon-courgette, la mie de pain, l''œuf, le persil, les herbes de Provence, le sel et du poivre.", "Garnir généreusement les demi-courgettes de farce en tassant légèrement, et parsemer de fromage râpé.", "Verser l''eau au fond du plat et enfourner 35 à 40 min à 200°C : le dessus doit être bien doré et la farce cuite à cœur (plus de trace rosée au centre, 71°C). Couvrir d''aluminium en fin de cuisson si le fromage colore trop vite.", "Laisser reposer 5 min avant de servir."]'::jsonb),
('Tartines beurre-confiture', 'Le petit-déjeuner français par excellence : du bon pain, du beurre doux et de la confiture.', 5, 0, 1, 1, 'gras', '["français", "petit-déjeuner", "rapide", "sans cuisson"]'::jsonb, 'public', '[]'::jsonb, '["Sortir le beurre du réfrigérateur 10 à 15 min avant : un beurre trop froid déchire la mie.", "Couper le quart de baguette en deux dans la longueur. Pour des tartines grillées, passer le pain 2 à 3 min au grille-pain ou sous le gril du four, jusqu''à ce qu''il soit doré et croustillant.", "Étaler le beurre en couche fine et régulière jusqu''aux bords.", "Répartir la confiture par-dessus avec le dos d''une cuillère et servir aussitôt, avec un café, un thé ou un chocolat chaud."]'::jsonb),
('Tartines au miel', 'Des tartines de pain de campagne grillé, beurrées et nappées de miel.', 5, 3, 1, 1, 'light', '["français", "petit-déjeuner", "rapide"]'::jsonb, 'public', '[]'::jsonb, '["Couper deux tranches de pain de campagne d''environ 1,5 cm d''épaisseur.", "Les faire griller 2 à 3 min au grille-pain ou sous le gril du four, jusqu''à ce qu''elles soient dorées.", "Beurrer légèrement les tranches encore chaudes : le beurre fond et imprègne la mie.", "Napper de miel. S''il est cristallisé, le laisser tel quel (il se tartine bien sur le pain chaud) ou l''assouplir quelques minutes au bain-marie tiède, sans dépasser 40°C pour ne pas altérer son goût."]'::jsonb),
('Tartines de pâte à tartiner', 'Du pain de mie grillé et de la pâte à tartiner chocolat-noisette (type Nutella), le goûter préféré des enfants.', 3, 2, 1, 1, 'gras', '["petit-déjeuner", "goûter", "rapide", "enfants"]'::jsonb, 'public', '[]'::jsonb, '["Faire griller les tranches de pain de mie 1 à 2 min au grille-pain : elles doivent être juste blondes.", "Si la pâte à tartiner est dure (pièce froide), la remuer dans le pot avec un couteau pour l''assouplir. Ne pas la mettre au réfrigérateur : elle durcit et ne se tartine plus.", "Étaler la pâte à tartiner sur le pain encore tiède, elle fond légèrement. Couper les tranches en deux en triangle et servir."]'::jsonb),
('Pain et chocolat du goûter', 'Le goûter d''écolier classique : un morceau de baguette fraîche et deux carrés de chocolat.', 2, 0, 1, 1, 'gras', '["français", "goûter", "rapide", "sans cuisson", "enfants"]'::jsonb, 'public', '[]'::jsonb, '["Couper un quart de baguette bien fraîche et l''ouvrir en deux dans la longueur, sans séparer complètement les deux moitiés.", "Glisser les carrés de chocolat à l''intérieur, refermer et déguster. Variante : passer le pain garni 2 min au four chaud à 200°C pour faire fondre le chocolat."]'::jsonb),
('Café à la cafetière à piston', 'Un café doux et corsé à la fois, préparé à la cafetière à piston (French press), sans machine.', 3, 5, 2, 1, 'light', '["petit-déjeuner", "boisson", "rapide"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire chauffer l''eau jusqu''à ébullition puis la laisser reposer 30 secondes à 1 min : la bonne température est de 92 à 96°C. De l''eau bouillante brûle le café et le rend amer.", "Pendant ce temps, rincer la cafetière à l''eau chaude pour la préchauffer, puis la vider.", "Mettre le café moulu (mouture grosse, sinon il passe à travers le filtre) dans la cafetière. Verser un peu d''eau pour juste mouiller le café et attendre 30 secondes qu''il gonfle.", "Verser le reste de l''eau, remuer doucement, poser le couvercle sans enfoncer le piston et laisser infuser 4 min.", "Enfoncer le piston lentement et régulièrement, en 20 secondes environ, puis servir tout de suite : laissé dans la cafetière, le café continue d''infuser et devient amer. Sucrer ou ajouter du lait selon le goût."]'::jsonb),
('Café au lait', 'Un grand bol de café fort allongé de lait chaud et mousseux, comme au petit-déjeuner à la française.', 3, 5, 1, 1, 'light', '["français", "petit-déjeuner", "boisson", "rapide"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Préparer un café fort : 12 g de café moulu pour 100 ml d''eau à 92-96°C, à la cafetière à piston (4 min d''infusion), à la cafetière filtre ou à la machine.", "Faire chauffer le lait à feu moyen dans une petite casserole jusqu''à ce que de petites bulles apparaissent sur les bords (environ 65°C). Ne pas le laisser bouillir : il forme une peau et prend un goût de cuit.", "Hors du feu, fouetter énergiquement le lait 20 à 30 secondes pour le faire mousser.", "Verser le café dans un grand bol, ajouter le lait chaud en retenant la mousse avec une cuillère, puis déposer la mousse sur le dessus. Sucrer selon le goût."]'::jsonb),
('Thé noir', 'Une tasse de thé noir infusé dans les règles : bonne température, bon temps d''infusion, pas d''amertume.', 2, 5, 1, 1, 'light', '["petit-déjeuner", "goûter", "boisson", "rapide"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire chauffer l''eau jusqu''à frémissement, entre 90 et 95°C (juste avant l''ébullition). Une eau faiblement minéralisée ou filtrée donne un meilleur thé.", "Ébouillanter la théière ou la tasse pour la préchauffer, puis la vider.", "Mettre le thé en vrac dans un infuseur (ou le sachet dans la tasse) et verser l''eau chaude.", "Laisser infuser 3 min pour un thé léger, 4 à 5 min pour un thé plus corsé à boire avec du lait. Au-delà, les tanins le rendent amer.", "Retirer l''infuseur ou le sachet sans le presser. Ajouter selon le goût un nuage de lait, une rondelle de citron ou du sucre."]'::jsonb),
('Thé vert à la menthe', 'Le thé à la menthe à la marocaine : thé vert gunpowder, menthe fraîche et sucre, servi mousseux.', 5, 8, 4, 1, 'light', '["marocain", "goûter", "boisson"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Porter l''eau à ébullition. Rincer la menthe à l''eau froide et l''essorer.", "Mettre le thé vert dans une théière qui va sur le feu. Verser 150 ml d''eau bouillante, faire tourner 30 secondes puis jeter cette eau : ce rinçage retire l''amertume et la poussière du thé.", "Ajouter le sucre et la menthe en tassant les tiges au fond, puis verser le reste de l''eau bouillante.", "Poser la théière 3 à 4 min à feu très doux, sans jamais laisser bouillir (la menthe deviendrait âcre).", "Pour mélanger le sucre, verser un verre et le reverser dans la théière, deux ou trois fois. Goûter et ajuster le sucre.", "Servir en versant de haut, théière levée à 30 cm du verre, pour faire mousser le thé."]'::jsonb),
('Chocolat chaud', 'Un vrai chocolat chaud onctueux au chocolat noir fondu dans le lait, loin des poudres instantanées.', 5, 8, 2, 1, 'gras', '["petit-déjeuner", "goûter", "boisson", "hiver"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Hacher finement le chocolat pour qu''il fonde vite et sans grumeaux.", "Dans une casserole, fouetter le cacao et le sucre avec 3 cuillères à soupe de lait froid jusqu''à obtenir une pâte lisse, puis ajouter le reste du lait et la pincée de sel.", "Chauffer à feu moyen en fouettant jusqu''aux premiers frémissements, sans laisser bouillir.", "Retirer du feu, ajouter le chocolat haché et fouetter 1 min jusqu''à ce qu''il soit complètement fondu.", "Remettre 2 à 3 min à feu doux en fouettant sans arrêt : le chocolat épaissit légèrement et devient mousseux. Servir aussitôt."]'::jsonb),
('Jus d''orange pressé', 'Des oranges à jus pressées minute : rien d''autre, et à boire tout de suite.', 10, 0, 2, 1, 'light', '["petit-déjeuner", "boisson", "sans cuisson", "vitaminé"]'::jsonb, 'public', '[]'::jsonb, '["Choisir des oranges à jus (Navel en hiver, Valencia au printemps), lourdes pour leur taille : ce sont les plus juteuses. Compter environ 3 oranges par verre de 20 cl.", "Rouler chaque orange sur le plan de travail en appuyant avec la paume pendant quelques secondes : la pulpe se détend et rend plus de jus.", "Couper les oranges en deux dans la largeur et les presser au presse-agrumes, en tournant bien pour extraire toute la pulpe.", "Filtrer au tamis si on n''aime pas la pulpe. Boire dans les 15 minutes : le jus s''oxyde, perd sa vitamine C et devient amer en attendant."]'::jsonb),
('Smoothie banane-fraise', 'Un smoothie crémeux à la banane, aux fraises et au yaourt, prêt en 5 minutes.', 5, 0, 2, 1, 'light', '["petit-déjeuner", "goûter", "boisson", "sans cuisson", "vitaminé"]'::jsonb, 'public', '["blender"]'::jsonb, '["Rincer et équeuter les fraises (des fraises surgelées conviennent aussi et rendent le smoothie plus frais). Éplucher la banane et la couper en rondelles : plus elle est mûre, plus le smoothie est sucré.", "Mettre dans le blender, dans cet ordre : le lait, le yaourt, la banane, les fraises et le miel. Les liquides au fond aident les lames à tourner.", "Mixer 45 secondes à 1 min à pleine puissance, jusqu''à ce que ce soit parfaitement lisse.", "Goûter, ajouter un peu de miel si besoin, ou un trait de lait si c''est trop épais. Servir aussitôt."]'::jsonb),
('Pain perdu', 'Des tranches de pain rassis trempées dans un mélange lait-œufs puis dorées au beurre, croustillantes dehors et moelleuses dedans.', 10, 15, 4, 1, 'gras', '["français", "petit-déjeuner", "goûter", "anti-gaspi"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper le pain rassis (baguette de la veille ou brioche) en tranches de 2 cm d''épaisseur. Du pain frais se désagrège : il doit être sec.", "Dans une assiette creuse, fouetter les œufs avec le sucre, le sucre vanillé et la cannelle, puis ajouter le lait.", "Tremper chaque tranche 10 à 20 secondes par face : elle doit être imbibée mais ne pas s''effondrer. Le pain très sec demande un peu plus de temps.", "Faire fondre une noix de beurre dans une poêle à feu moyen. Quand il mousse, poser les tranches sans les serrer et les cuire 2 à 3 min par face, jusqu''à ce qu''elles soient bien dorées. Si le beurre noircit, baisser le feu.", "Cuire en plusieurs fois en rajoutant du beurre, et garder les tranches cuites au chaud dans le four à 100°C.", "Saupoudrer d''un peu de sucre au moment de servir, ou napper de miel ou de sirop d''érable."]'::jsonb),
('Pancakes', 'Des pancakes épais et moelleux à l''américaine, à servir avec du sirop d''érable et des fruits.', 10, 20, 4, 1, 'gras', '["américain", "petit-déjeuner", "goûter"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire fondre le beurre et le laisser tiédir.", "Dans un saladier, mélanger la farine, la levure chimique, le sucre et le sel. Creuser un puits.", "Dans un autre récipient, battre les œufs avec le lait. Verser dans le puits et mélanger au fouet juste assez pour qu''il ne reste plus de farine sèche, puis ajouter le beurre fondu. Quelques petits grumeaux sont normaux : trop fouetter rend les pancakes caoutchouteux.", "Laisser reposer la pâte 10 min : la levure commence à agir et les pancakes seront plus épais.", "Chauffer une poêle antiadhésive à feu moyen et la graisser très légèrement avec un papier imbibé de beurre. Verser une petite louche de pâte (environ 60 ml) sans l''étaler.", "Cuire environ 2 min, jusqu''à ce que des bulles apparaissent à la surface et que les bords paraissent secs, puis retourner et cuire encore 1 min. Si le dessous brunit avant que les bulles apparaissent, le feu est trop fort.", "Empiler les pancakes sur une assiette couverte d''un torchon pour les garder chauds, et servir avec le sirop d''érable."]'::jsonb),
('Porridge aux flocons d''avoine', 'Un bol de flocons d''avoine cuits dans le lait, crémeux et nourrissant, garni de banane et de miel.', 2, 6, 1, 1, 'light', '["anglais", "petit-déjeuner", "rapide", "sain"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Mettre les flocons d''avoine, le lait et la pincée de sel dans une petite casserole. Le sel ne se sent pas mais réveille le goût de l''avoine.", "Porter à frémissement à feu moyen, puis baisser le feu et cuire en remuant souvent : 3 min pour des flocons fins, 5 à 7 min pour des gros flocons, jusqu''à ce que le mélange soit crémeux.", "Retirer du feu et laisser reposer 1 min : le porridge épaissit encore. S''il est trop épais, ajouter un trait de lait.", "Verser dans un bol, garnir de rondelles de banane, arroser de miel et saupoudrer de cannelle."]'::jsonb),
('Œufs brouillés', 'Des œufs brouillés crémeux cuits à feu doux, la méthode française, sans jamais les dessécher.', 3, 6, 2, 1, 'protéiné', '["français", "petit-déjeuner", "œufs", "rapide"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Casser les œufs dans un bol et les battre à la fourchette avec une pincée de sel, juste pour mélanger blancs et jaunes.", "Faire fondre le beurre à feu doux dans une petite casserole à fond épais ou une poêle antiadhésive. Il doit fondre sans mousser ni colorer.", "Verser les œufs et remuer sans arrêt avec une spatule, en raclant le fond et les bords. À feu doux, il faut 4 à 5 min pour que de petits grumeaux crémeux se forment.", "Retirer du feu quand les œufs sont encore un peu plus coulants que souhaité : ils continuent de cuire dans la casserole.", "Ajouter aussitôt la crème fraîche froide, qui stoppe la cuisson et les rend onctueux. Poivrer, parsemer de ciboulette et servir immédiatement, avec du pain grillé."]'::jsonb),
('Œufs à la coque et mouillettes', 'Des œufs au jaune coulant, avec des mouillettes de pain grillé beurré à tremper dedans.', 5, 4, 2, 1, 'protéiné', '["français", "petit-déjeuner", "œufs", "rapide"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Sortir les œufs du réfrigérateur 15 min avant si possible : un œuf trop froid risque de se fendre dans l''eau bouillante.", "Porter une casserole d''eau à ébullition franche, en quantité suffisante pour couvrir les œufs.", "Déposer délicatement les œufs dans l''eau avec une cuillère et lancer le minuteur : 3 min pour des œufs moyens à température ambiante, 3 min 30 s s''ils sortent du réfrigérateur. Maintenir une ébullition douce.", "Pendant la cuisson, faire griller les tranches de pain, les beurrer et les couper en bâtonnets d''1 cm de large.", "Sortir les œufs, les poser dans des coquetiers et décalotter aussitôt le haut à la cuillère ou au couteau pour arrêter la cuisson. Le blanc doit être pris et le jaune coulant. Saler et servir avec les mouillettes."]'::jsonb),
('Tartine avocat et œuf', 'Une tartine de pain de campagne grillé, avocat écrasé au citron et œuf au plat.', 5, 5, 2, 1, 'light', '["petit-déjeuner", "rapide", "végétarien"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper l''avocat en deux, retirer le noyau et récupérer la chair à la cuillère. L''écraser à la fourchette avec le jus de citron, une pincée de sel et du poivre, en gardant quelques morceaux.", "Faire griller les tranches de pain 2 à 3 min.", "Chauffer l''huile dans une poêle à feu moyen, casser les œufs et les cuire 3 min, jusqu''à ce que le blanc soit entièrement pris et le jaune encore coulant. Saler le blanc seulement (le sel sur le jaune laisse des points blancs).", "Étaler l''avocat sur le pain grillé, poser un œuf sur chaque tartine et parsemer de piment d''Espelette."]'::jsonb),
('Granola maison', 'Un granola croustillant aux flocons d''avoine, fruits secs et miel, cuit au four. Se garde deux semaines en bocal.', 10, 30, 10, 1, 'gras', '["petit-déjeuner", "végétarien", "four"]'::jsonb, 'public', '["oven"]'::jsonb, '["Préchauffer le four à 160°C et couvrir une grande plaque de papier cuisson.", "Dans un saladier, mélanger les flocons d''avoine, les amandes et noisettes concassées, les graines, la cannelle et le sel.", "Faire tiédir le miel et l''huile dans une petite casserole juste assez pour qu''ils soient fluides, verser sur les flocons et mélanger jusqu''à ce que tout soit bien enrobé.", "Étaler en couche fine et régulière sur la plaque en tassant légèrement : c''est ce qui forme des amas croustillants.", "Cuire 25 à 30 min en retournant délicatement à mi-cuisson, jusqu''à ce que le granola soit doré. Surveiller les 5 dernières minutes : il passe vite de doré à brûlé.", "Laisser refroidir complètement sur la plaque sans toucher : il durcit en refroidissant. Casser en morceaux, ajouter les raisins secs (cuits, ils durciraient) et conserver en bocal hermétique. Servir avec du yaourt ou du lait."]'::jsonb),
('Pain au chocolat', 'Une pâte levée feuilletée au beurre roulée autour de deux barres de chocolat. Compter une nuit de repos pour la pâte.', 180, 18, 12, 3, 'gras', '["français", "boulangerie", "petit-déjeuner", "goûter", "four"]'::jsonb, 'public', '["oven"]'::jsonb, '["Détrempe (la veille) : mélanger la farine, le sel, le sucre, la levure émiettée, le lait froid et le beurre mou pendant 5 min, pas plus, jusqu''à obtenir une pâte homogène. Aplatir en rectangle, filmer et réfrigérer toute la nuit (au moins 4h).", "Le jour même, taper le beurre de tourage froid entre deux feuilles de papier cuisson pour former un carré de 18 cm d''environ 1 cm d''épaisseur. Il doit être froid mais souple : il plie sans casser.", "Étaler la détrempe en carré deux fois plus grand que le beurre, poser le beurre en losange au centre et rabattre les quatre coins de pâte dessus en soudant bien les jointures.", "Étaler en long rectangle (3 fois plus long que large) et plier en trois comme un portefeuille : c''est un tour simple. Filmer et réfrigérer 30 à 40 min. Faire 3 tours au total, avec un repos au froid entre chaque. Si le beurre perce ou devient mou, remettre au froid.", "Abaisser la pâte à 4 mm d''épaisseur et découper des rectangles de 8 x 14 cm. Poser une barre de chocolat sur le petit côté, rouler d''un tour, poser la seconde barre et rouler jusqu''au bout. Placer sur la plaque, soudure en dessous.", "Laisser pousser 2h à 2h30 dans un endroit à 25°C maximum (four éteint avec un bol d''eau chaude), jusqu''à ce que les pains aient presque doublé et tremblent quand on secoue la plaque. Au-delà de 28°C, le beurre fond et le feuilletage est perdu.", "Préchauffer le four à 200°C (180°C en chaleur tournante). Dorer délicatement à l''œuf battu avec une pincée de sel, sans en mettre sur les tranches feuilletées.", "Cuire 15 à 18 min, jusqu''à ce qu''ils soient bien dorés, plutôt foncés : pâles, ils restent pâteux à l''intérieur. Laisser tiédir sur une grille."]'::jsonb),
('Brioche maison', 'Une brioche pur beurre à la mie filante, façonnée en boules dans un moule à cake. Pâte préparée la veille.', 180, 35, 12, 3, 'gras', '["français", "boulangerie", "petit-déjeuner", "goûter", "four"]'::jsonb, 'public', '["oven"]'::jsonb, '["La veille, dans le bol d''un robot pétrisseur avec le crochet : mettre la farine, le sel et le sucre d''un côté, la levure émiettée de l''autre (le sel au contact direct de la levure la neutralise), puis 6 œufs et le lait froids (le dernier œuf sert à dorer).", "Pétrir 5 min à vitesse lente puis 10 min à vitesse moyenne, jusqu''à ce que la pâte se décolle des parois et devienne élastique.", "Ajouter le beurre mou (souple mais pas fondu) en 4 fois, en attendant que chaque morceau soit absorbé. Pétrir encore 5 min jusqu''à ce que la pâte soit lisse, brillante et se décolle à nouveau du bol. À la main, compter 20 à 25 min de pétrissage énergique.", "Couvrir et laisser pousser 1h à température ambiante. Rabattre la pâte pour la dégazer, filmer au contact et réfrigérer toute la nuit (au moins 6h) : la pâte froide est bien plus facile à façonner.", "Le lendemain, beurrer deux moules à cake de 25 cm. Diviser la pâte froide en 12 boules égales (environ 90 g), les bouler serré et en placer 6 dans chaque moule, côte à côte.", "Laisser pousser 2h à 2h30 à 25°C environ, jusqu''à ce que la pâte arrive au bord des moules.", "Préchauffer le four à 170°C. Dorer au pinceau avec l''œuf battu avec une pincée de sel, et enfourner 30 à 35 min. Si le dessus colore trop vite, couvrir de papier aluminium à mi-cuisson. La brioche est cuite quand elle sonne creux en tapotant le dessous (ou 90°C à cœur).", "Démouler aussitôt et laisser refroidir sur une grille avant de trancher."]'::jsonb),
('Pain de mie maison', 'Un pain de mie moelleux au lait et au beurre, à la mie serrée et régulière, idéal pour les tartines et les croque-monsieur.', 150, 35, 12, 2, 'light', '["français", "boulangerie", "petit-déjeuner", "four"]'::jsonb, 'public', '["oven"]'::jsonb, '["Faire tiédir le lait (37°C maximum, tiède au doigt) et y délayer la levure. Du lait trop chaud tue la levure.", "Dans un grand saladier, mélanger la farine, le sucre et le sel. Ajouter le lait à la levure et mélanger jusqu''à ce que la pâte forme une boule.", "Pétrir 10 min sur le plan de travail (ou 8 min au robot, crochet, vitesse moyenne), puis incorporer le beurre mou et pétrir encore 5 min jusqu''à ce que la pâte soit lisse et souple. Elle doit s''étirer en fine membrane sans se déchirer.", "Couvrir d''un torchon et laisser pousser 1h dans un endroit tiède, jusqu''à ce qu''elle double de volume.", "Beurrer un moule à pain de mie ou un moule à cake de 28 à 30 cm. Dégazer la pâte, l''étaler en rectangle de la longueur du moule et la rouler en boudin bien serré. La poser dans le moule, soudure en dessous.", "Laisser pousser encore 1h à 1h30, jusqu''à ce que la pâte arrive à 1 cm du bord. Pour des tranches bien carrées, poser le couvercle du moule (ou une plaque avec un poids) avant cette seconde pousse.", "Préchauffer le four à 180°C et cuire 30 à 35 min : le pain doit être doré et sonner creux quand on tapote le dessous une fois démoulé.", "Démouler aussitôt et laisser refroidir complètement sur une grille (au moins 1h) avant de trancher, sinon la mie devient collante. Conserver emballé dans un sac ou un torchon."]'::jsonb),
('Pain de campagne maison', 'Un pain de campagne à la farine de blé et de seigle, cuit en cocotte en fonte pour une croûte épaisse et craquante.', 150, 45, 8, 2, 'light', '["français", "boulangerie", "four", "petit-déjeuner"]'::jsonb, 'public', '["oven"]'::jsonb, '["Délayer la levure dans l''eau tiède (environ 30°C). Dans un grand saladier, mélanger les deux farines et le sel, ajouter l''eau et mélanger jusqu''à ce qu''il ne reste plus de farine sèche.", "Pétrir 10 min sur le plan de travail légèrement fariné. La pâte est collante à cause du seigle : ne pas rajouter trop de farine, elle devient plus lisse en pétrissant.", "Mettre en boule dans le saladier, couvrir et laisser pousser 1h30. Au bout de 45 min, faire un rabat : étirer un bord de la pâte et le replier sur le centre, sur les quatre côtés, pour lui donner de la force.", "Dégazer légèrement, façonner une boule serrée en ramenant les bords dessous et la poser, soudure vers le haut, dans un saladier tapissé d''un torchon bien fariné. Laisser pousser 45 min à 1h.", "Pendant ce temps, placer une cocotte en fonte avec son couvercle dans le four et préchauffer à 250°C pendant au moins 30 min.", "Retourner le pain sur une feuille de papier cuisson, faire une entaille de 1 cm de profondeur au couteau bien aiguisé ou à la lame, puis le déposer avec le papier dans la cocotte brûlante (attention aux mains). Couvrir.", "Cuire 25 min à couvert, puis retirer le couvercle, baisser à 220°C et cuire encore 15 à 20 min, jusqu''à ce que la croûte soit bien brune. Le pain est cuit quand il sonne creux en tapotant dessous.", "Laisser refroidir au moins 1h sur une grille avant de le couper : la mie finit de cuire en refroidissant."]'::jsonb),
('Pain au lait', 'Des petits pains au lait brioches, moelleux et légèrement sucrés, parsemés de sucre perlé.', 150, 15, 12, 2, 'gras', '["français", "boulangerie", "petit-déjeuner", "goûter", "four", "enfants"]'::jsonb, 'public', '["oven"]'::jsonb, '["Faire tiédir le lait (37°C maximum) et y délayer la levure.", "Mélanger la farine, le sucre et le sel dans un saladier ou le bol du robot. Ajouter le lait à la levure et 1 œuf, puis pétrir 10 min jusqu''à ce que la pâte soit homogène.", "Incorporer le beurre mou en morceaux et pétrir encore 5 à 8 min, jusqu''à ce que la pâte soit lisse, souple et se décolle des parois.", "Couvrir et laisser pousser 1h30 dans un endroit tiède, jusqu''à ce que la pâte double de volume.", "Dégazer la pâte et la diviser en 12 morceaux d''environ 75 g. Les bouler, puis les rouler en petits boudins de 12 cm. Les poser sur une plaque couverte de papier cuisson en les espaçant de 5 cm.", "Couvrir d''un torchon et laisser pousser 1h à 1h30, jusqu''à ce qu''ils aient bien gonflé.", "Préchauffer le four à 180°C. Dorer au pinceau avec le second œuf battu avec une cuillère de lait, faire des petites entailles aux ciseaux sur le dessus et parsemer de sucre perlé.", "Cuire 12 à 15 min, jusqu''à ce qu''ils soient dorés. Laisser tiédir sur une grille ; garder ensuite dans un sac pour qu''ils restent moelleux."]'::jsonb),
('Confiture de fraises', 'Une confiture de fraises maison, macérées la veille puis cuites rapidement pour garder le goût du fruit. Environ 6 pots de 250 g.', 30, 25, 6, 2, 'light', '["français", "petit-déjeuner", "goûter", "conserve"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["La veille, rincer les fraises rapidement avant de les équeuter (sinon elles se gorgent d''eau), les couper en deux ou en quatre si elles sont grosses. Les mélanger avec le sucre et le jus de citron dans un grand saladier, couvrir et laisser macérer au réfrigérateur toute la nuit : les fraises rendent leur jus.", "Le jour même, stériliser les pots et couvercles en les plongeant 10 min dans l''eau bouillante, puis les laisser sécher à l''envers sur un torchon propre. Placer une petite assiette au congélateur pour le test de prise.", "Verser les fraises et leur sirop dans une grande bassine ou une large casserole (la confiture monte en bouillant). Porter à ébullition à feu vif en remuant.", "Cuire à gros bouillons 10 à 15 min en remuant régulièrement et en retirant l''écume avec une écumoire.", "Vérifier la prise : déposer une goutte de confiture sur l''assiette glacée. Si elle se fige et se ride quand on la pousse du doigt, c''est prêt (105°C au thermomètre). Sinon, poursuivre 2 à 3 min et refaire le test.", "Remplir aussitôt les pots de confiture bouillante jusqu''à 5 mm du bord, essuyer le bord, fermer immédiatement et laisser refroidir. Conserver à l''abri de la lumière ; une fois ouvert, garder le pot au réfrigérateur."]'::jsonb),
('Compote de pommes', 'Une compote de pommes maison, peu sucrée, parfumée à la vanille ou à la cannelle.', 15, 25, 6, 1, 'light', '["français", "goûter", "enfants", "économique"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Éplucher les pommes, retirer le cœur et les pépins et les couper en morceaux de 2 cm. Mélanger deux variétés (une qui fond comme la golden ou la reinette, une plus acidulée comme la boskoop) donne plus de goût.", "Mettre les pommes dans une casserole avec l''eau, le jus de citron, le sucre et la gousse de vanille fendue (ou la cannelle).", "Couvrir et cuire à feu doux 20 à 25 min en remuant de temps en temps, jusqu''à ce que les pommes s''écrasent facilement. Si ça accroche, ajouter un peu d''eau.", "Retirer la vanille. Écraser à la fourchette pour une compote avec morceaux, ou mixer pour une compote lisse. Goûter et ajuster le sucre.", "Servir tiède ou froide. Se garde 4 à 5 jours au réfrigérateur dans un récipient fermé."]'::jsonb),
('Gâteau au yaourt', 'Le gâteau de l''enfance, mesuré avec le pot de yaourt : simple, moelleux et inratable.', 10, 35, 8, 1, 'gras', '["français", "goûter", "four", "enfants", "économique"]'::jsonb, 'public', '["oven"]'::jsonb, '["Préchauffer le four à 180°C. Beurrer et fariner un moule rond de 22 à 24 cm.", "Verser le yaourt dans un saladier et garder le pot vide comme mesure (1 pot de farine = environ 70 g, 1 pot de sucre = environ 80 g).", "Ajouter le sucre, le sucre vanillé et les œufs, et fouetter jusqu''à ce que le mélange soit homogène et légèrement mousseux.", "Ajouter la farine mélangée à la levure et au sel, et mélanger juste jusqu''à ce qu''elle disparaisse. Incorporer l''huile en dernier.", "Verser dans le moule et cuire 30 à 35 min. Le gâteau est cuit quand il est doré et que la lame d''un couteau plantée au centre ressort sèche.", "Laisser tiédir 10 min dans le moule avant de démouler sur une grille."]'::jsonb),
('Quatre-quarts', 'Le gâteau breton aux quatre ingrédients à poids égal : œufs, beurre, sucre et farine.', 15, 45, 8, 1, 'gras', '["français", "breton", "goûter", "four"]'::jsonb, 'public', '["oven"]'::jsonb, '["Sortir le beurre 1h à l''avance pour qu''il soit mou (pommade). Préchauffer le four à 170°C et beurrer un moule à cake de 25 cm.", "Peser les œufs avec leur coquille : la recette traditionnelle utilise le même poids de beurre, de sucre et de farine (environ 200 g pour 4 œufs).", "Travailler le beurre pommade avec le sucre au fouet 3 à 4 min, jusqu''à ce que le mélange blanchisse et devienne crémeux.", "Ajouter les œufs un par un en fouettant bien entre chaque. Si le mélange tranche (aspect granuleux), ajouter une cuillère de farine.", "Incorporer la farine tamisée avec la levure et le sel à la spatule, sans trop travailler la pâte.", "Verser dans le moule et cuire 40 à 45 min. Si le dessus colore trop vite, couvrir de papier aluminium. Le gâteau est cuit quand la lame d''un couteau ressort sèche.", "Laisser tiédir 10 min, démouler et laisser refroidir sur une grille. Il est encore meilleur le lendemain."]'::jsonb),
('Cake marbré', 'Un cake moelleux à la pâte vanille et chocolat marbrée, le goûter classique à la française.', 20, 50, 10, 2, 'gras', '["français", "goûter", "four", "enfants"]'::jsonb, 'public', '["oven"]'::jsonb, '["Sortir le beurre à l''avance pour qu''il soit mou. Préchauffer le four à 170°C et beurrer-fariner un moule à cake de 25 cm (ou le tapisser de papier cuisson).", "Fouetter le beurre mou avec le sucre 3 min jusqu''à ce que le mélange soit crémeux et pâle. Ajouter les œufs un par un en fouettant entre chaque, puis la vanille.", "Incorporer la farine tamisée avec la levure et le sel, à la spatule, juste jusqu''à ce que la pâte soit homogène.", "Séparer la pâte en deux. Dans une moitié, ajouter le cacao et le lait et mélanger : les deux pâtes doivent avoir la même consistance.", "Déposer dans le moule des cuillerées de pâte en alternant les deux couleurs, puis passer une seule fois la pointe d''un couteau en zigzag dans la longueur pour créer le marbrage (plus, les pâtes se mélangent).", "Cuire 45 à 50 min. Couvrir de papier aluminium après 30 min si le dessus brunit trop. Le cake est cuit quand la lame d''un couteau ressort sèche.", "Laisser tiédir 10 min, démouler et laisser refroidir sur une grille."]'::jsonb),
('Madeleines', 'Des madeleines au beurre et au citron avec leur bosse, grâce au repos au froid et au choc thermique à la cuisson. Environ 24 pièces.', 15, 12, 8, 2, 'gras', '["français", "goûter", "four"]'::jsonb, 'public', '["oven"]'::jsonb, '["Faire fondre le beurre et le laisser tiédir. Zester le citron.", "Fouetter les œufs avec le sucre et le miel 2 à 3 min, jusqu''à ce que le mélange blanchisse légèrement.", "Ajouter la farine tamisée avec la levure et le sel, mélanger, puis incorporer le beurre fondu tiède et le zeste.", "Couvrir au contact et réfrigérer au moins 3h, idéalement toute la nuit. C''est le repos au froid qui donne la bosse : la pâte froide gonfle d''un coup dans le four chaud.", "Préchauffer le four à 220°C. Beurrer généreusement les moules à madeleines et les fariner (inutile en silicone). Garnir chaque empreinte aux trois quarts avec une cuillerée de pâte bien froide, sans l''étaler.", "Enfourner 5 min à 220°C, jusqu''à ce que la bosse se forme, puis baisser à 180°C et cuire encore 6 à 8 min, jusqu''à ce que les bords soient dorés.", "Démouler aussitôt en tapant le moule sur le plan de travail et laisser refroidir sur une grille. Conserver dans une boîte hermétique."]'::jsonb),
('Cookies aux pépites de chocolat', 'Des cookies à l''américaine, croustillants sur les bords et fondants au centre. Environ 14 cookies.', 20, 12, 7, 1, 'gras', '["américain", "goûter", "four", "enfants"]'::jsonb, 'public', '["oven"]'::jsonb, '["Travailler le beurre mou avec les deux sucres au fouet ou à la cuillère 2 min, jusqu''à obtenir un mélange crémeux.", "Ajouter l''œuf et la vanille et mélanger.", "Incorporer la farine, le bicarbonate et le sel, et mélanger juste jusqu''à ce que la pâte soit homogène. Ajouter le chocolat concassé.", "Filmer et réfrigérer la pâte au moins 1h (jusqu''à 24h) : les cookies s''étaleront moins et auront plus de goût.", "Préchauffer le four à 180°C et couvrir deux plaques de papier cuisson. Former des boules d''environ 45 g et les espacer de 6 cm, car elles s''étalent.", "Cuire 10 à 12 min : les bords doivent être dorés et le centre encore pâle et mou. Ils semblent pas assez cuits mais durcissent en refroidissant ; trop cuits, ils deviennent secs.", "Laisser 10 min sur la plaque avant de les déplacer sur une grille."]'::jsonb),
('Brownies', 'Des brownies denses et fondants au chocolat noir et aux noix de pécan.', 15, 25, 12, 1, 'gras', '["américain", "goûter", "four"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Préchauffer le four à 180°C. Tapisser un moule carré de 20 cm de papier cuisson en le laissant dépasser pour démouler facilement.", "Faire fondre le chocolat en morceaux et le beurre au bain-marie (ou au micro-ondes par tranches de 30 secondes), en remuant jusqu''à ce que ce soit lisse. Laisser tiédir 5 min.", "Ajouter le sucre et fouetter, puis les œufs un par un en fouettant bien entre chaque : la pâte devient brillante.", "Incorporer la farine et le sel à la spatule, puis les noix de pécan concassées.", "Verser dans le moule, lisser et cuire 20 à 25 min. Le brownie est prêt quand le dessus est craquelé et que le centre tremble encore un peu : un cure-dent planté au centre ressort avec quelques miettes humides, pas de pâte liquide. Trop cuit, il devient sec.", "Laisser refroidir complètement dans le moule (au moins 1h) avant de le couper en 12 carrés."]'::jsonb),
('Muffins aux myrtilles', 'Des muffins bien gonflés et moelleux, garnis de myrtilles.', 15, 22, 12, 1, 'gras', '["américain", "goûter", "petit-déjeuner", "four"]'::jsonb, 'public', '["oven"]'::jsonb, '["Préchauffer le four à 190°C et placer 12 caissettes en papier dans un moule à muffins.", "Dans un grand saladier, mélanger la farine, le sucre, la levure et le sel.", "Dans un autre récipient, fouetter les œufs, le yaourt, le lait, le beurre fondu tiède et la vanille.", "Verser les liquides sur les ingrédients secs et mélanger à la spatule en quelques mouvements seulement, jusqu''à ce qu''il n''y ait plus de farine sèche. La pâte doit rester grumeleuse : trop mélangée, elle donne des muffins durs et plats.", "Rouler les myrtilles dans une cuillère de farine (elles ne tomberont pas au fond) et les incorporer délicatement. Surgelées, les utiliser sans les décongeler.", "Remplir les caissettes aux trois quarts et cuire 20 à 22 min, jusqu''à ce qu''ils soient dorés et qu''un cure-dent planté au centre ressorte sec.", "Laisser tiédir 5 min dans le moule puis sur une grille."]'::jsonb),
('Banana bread', 'Un cake moelleux aux bananes très mûres et aux noix, parfait pour utiliser les bananes tachées.', 15, 55, 10, 1, 'gras', '["américain", "goûter", "petit-déjeuner", "four", "anti-gaspi"]'::jsonb, 'public', '["oven"]'::jsonb, '["Préchauffer le four à 175°C. Beurrer et fariner un moule à cake de 25 cm ou le tapisser de papier cuisson.", "Écraser les bananes à la fourchette dans un saladier : plus elles sont noires, plus le gâteau sera sucré et parfumé.", "Ajouter le beurre fondu, la cassonade, les œufs et la vanille, et mélanger.", "Incorporer la farine, le bicarbonate, la cannelle et le sel sans trop mélanger, puis les noix concassées.", "Verser dans le moule et cuire 50 à 60 min. Couvrir de papier aluminium après 35 min si le dessus fonce trop. Il est cuit quand un cure-dent planté au centre ressort sec.", "Laisser tiédir 15 min dans le moule, démouler et laisser refroidir sur une grille avant de trancher."]'::jsonb),
('Gaufres', 'Des gaufres dorées et croustillantes au gaufrier, légères à l''intérieur.', 15, 25, 6, 1, 'gras', '["français", "belge", "goûter"]'::jsonb, 'public', '[]'::jsonb, '["Faire fondre le beurre et le laisser tiédir.", "Dans un saladier, mélanger la farine, la levure, le sucre, le sucre vanillé et le sel. Creuser un puits, y casser les œufs et commencer à mélanger au fouet.", "Verser le lait petit à petit en fouettant pour éviter les grumeaux, puis ajouter le beurre fondu. La pâte doit être lisse et napper la cuillère.", "Laisser reposer au moins 30 min (idéalement 1h) à température ambiante.", "Faire chauffer le gaufrier et le graisser légèrement au pinceau avec un peu d''huile ou de beurre fondu, seulement avant la première gaufre.", "Verser une louche de pâte au centre de chaque plaque, refermer et cuire 3 à 4 min sans ouvrir : la gaufre est prête quand la vapeur ne s''échappe presque plus et qu''elle est bien dorée.", "Déposer sur une grille (empilées, elles ramollissent) et servir avec du sucre glace, de la chantilly ou de la pâte à tartiner."]'::jsonb),
('Chouquettes', 'Des petits choux légers et creux couverts de sucre perlé, comme à la boulangerie. Environ 40 chouquettes.', 25, 25, 8, 2, 'gras', '["français", "pâtisserie", "goûter", "four"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Préchauffer le four à 180°C (chaleur statique de préférence) et couvrir deux plaques de papier cuisson.", "Dans une casserole, mettre l''eau, le lait, le beurre en morceaux, le sel et le sucre. Chauffer jusqu''à ce que le beurre soit fondu, puis porter à pleine ébullition.", "Retirer du feu et verser la farine d''un coup. Mélanger vivement à la spatule jusqu''à ce qu''il n''y ait plus de farine sèche.", "Remettre sur feu moyen et dessécher la pâte 1 à 2 min en remuant sans arrêt : elle doit former une boule qui se détache des parois et laisser une fine pellicule au fond de la casserole.", "Transférer la pâte dans un saladier et la laisser tiédir 5 min (sinon les œufs cuiraient). Ajouter 4 œufs battus en 4 ou 5 fois, en mélangeant bien entre chaque ajout.", "Vérifier la consistance avant d''ajouter le dernier œuf : la pâte est prête quand un sillon tracé du doigt se referme lentement et qu''elle tombe de la spatule en formant une pointe. Elle ne doit pas être liquide ; on n''utilise pas forcément tout l''œuf.", "À la poche à douille (ou avec deux petites cuillères), déposer des boules de 3 cm en les espaçant de 3 cm. Dorer avec le dernier œuf battu et parsemer généreusement de sucre perlé, puis incliner la plaque pour retirer l''excédent.", "Cuire 20 à 25 min sans jamais ouvrir le four pendant les 20 premières minutes, sinon les choux retombent. Ils sont cuits quand ils sont bien dorés et légers. Laisser refroidir sur une grille."]'::jsonb),
('Riz au lait', 'Un riz au lait crémeux à la vanille, cuit doucement comme chez grand-mère.', 5, 45, 6, 1, 'gras', '["français", "goûter", "dessert", "économique"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Rincer le riz rond, puis le plonger 2 min dans une casserole d''eau bouillante et l''égoutter : ça retire l''excès d''amidon et évite que le riz colle au fond.", "Dans une casserole à fond épais, porter le lait à frémissement avec la gousse de vanille fendue et grattée et la pincée de sel.", "Ajouter le riz, baisser à feu très doux et cuire à découvert 35 à 40 min, en remuant souvent (toutes les 3 à 4 min) pour que ça n''attache pas. Le lait doit à peine frémir.", "Quand le riz est tendre et que le mélange est crémeux mais encore assez liquide, ajouter le sucre et cuire encore 5 min. Le sucre ajouté au début durcirait les grains.", "Retirer la vanille et verser dans des ramequins. Le riz au lait épaissit beaucoup en refroidissant. Servir tiède ou froid, nature ou avec du caramel."]'::jsonb),
('Buddha Bowl Patate Douce & Pois Chiches', 'Un bol complet et coloré : patate douce et pois chiches rôtis, quinoa, crudités et sauce au tahini.', 20, 30, 2, 1, 'light', '["végan", "bowl", "sans gluten", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Préchauffer le four à 200°C. Éplucher la patate douce et la couper en cubes de 2 cm. Rincer les pois chiches et les sécher dans un torchon.", "Sur une plaque couverte de papier cuisson, mélanger la patate douce et les pois chiches avec l''huile, le paprika, le cumin et du sel. Rôtir 25 à 30 min en remuant à mi-cuisson : la patate douce doit être tendre et dorée, les pois chiches croustillants.", "Pendant ce temps, rincer le quinoa dans une passoire fine (cela retire son amertume), le mettre dans une casserole avec 240 ml d''eau salée, porter à ébullition, couvrir et cuire 12 à 15 min à feu doux. Laisser reposer 5 min à couvert puis égrener à la fourchette.", "Sauce : mélanger le tahini avec le jus du demi-citron, l''ail râpé et une pincée de sel. Ajouter 3 à 4 c.à.s d''eau froide petit à petit en fouettant : la sauce épaissit d''abord puis devient lisse et nappante.", "Émincer finement le chou rouge et couper l''avocat en tranches.", "Répartir le quinoa dans deux bols, disposer en sections la patate douce, les pois chiches, les épinards, le chou et l''avocat. Napper de sauce et parsemer de sésame."]'::jsonb),
('Falafels Maison', 'Des boulettes de pois chiches aux herbes, croustillantes dehors et vertes dedans, à glisser dans un pain pita.', 30, 20, 4, 2, 'protéiné', '["végan", "moyen-orient", "friture", "plat"]'::jsonb, 'public', '["food_processor", "stovetop"]'::jsonb, '["La veille, faire tremper les pois chiches secs 12 à 24h dans trois fois leur volume d''eau froide. Ne pas utiliser de pois chiches en conserve : déjà cuits, ils sont trop humides et les falafels se désagrègent à la friture.", "Égoutter les pois chiches et les sécher dans un torchon. Les mixer au robot avec l''oignon, l''ail, le persil, la coriandre, les épices, le sel et le poivre, par à-coups, en raclant les parois : la texture doit être celle d''une semoule fine, pas d''une purée.", "Couvrir et réfrigérer 1h : la pâte se raffermit et se façonne mieux.", "Ajouter le bicarbonate et mélanger. Former des boulettes de 3 à 4 cm (environ 30 g) en serrant bien, et les aplatir légèrement. Si elles ne se tiennent pas, ajouter la farine de pois chiche.", "Chauffer l''huile à 175-180°C (un morceau de pâte doit remonter aussitôt en grésillant). Frire les falafels par petites fournées 3 à 4 min, jusqu''à ce qu''ils soient bien bruns. Égoutter sur une grille.", "Sauce : mélanger le tahini avec le jus du citron, une pincée de sel et 3 à 4 c.à.s d''eau jusqu''à ce qu''elle soit lisse. Servir les falafels chauds dans les pitas avec la sauce et des crudités."]'::jsonb),
('Wok de Légumes au Tofu', 'Un sauté rapide de tofu doré et de légumes croquants, laqué d''une sauce soja-gingembre, servi avec du riz jasmin.', 20, 15, 2, 1, 'protéiné', '["végan", "asiatique", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Égoutter le tofu, l''envelopper dans un torchon et poser un poids dessus 15 min pour le presser. Le couper en cubes de 2 cm et les rouler dans la fécule.", "Rincer le riz, le mettre dans une casserole avec 1,25 fois son volume d''eau, porter à ébullition, couvrir et cuire 12 min à feu très doux, puis laisser reposer 5 min.", "Mélanger la sauce soja, le sirop d''érable, le vinaigre de riz et l''huile de sésame. Couper le brocoli en petits bouquets, la carotte en fines rondelles, le poivron en lanières, émincer les oignons nouveaux et hacher l''ail et le gingembre.", "Chauffer l''huile dans un wok à feu vif et faire dorer le tofu 6 à 8 min en le retournant, jusqu''à ce qu''il soit croustillant sur toutes les faces. Le réserver.", "Dans le wok, sauter la carotte et le brocoli 3 min avec 2 c.à.s d''eau pour qu''ils cuisent à la vapeur, puis ajouter le poivron 2 min. Ajouter l''ail, le gingembre et le blanc des oignons 30 secondes.", "Remettre le tofu, verser la sauce et remuer 1 min jusqu''à ce que tout soit laqué. Servir sur le riz, parsemé du vert des oignons et de sésame."]'::jsonb),
('Curry de Légumes au Lait de Coco', 'Un curry doux et onctueux de patate douce, chou-fleur et lentilles corail au lait de coco.', 15, 30, 3, 1, 'light', '["végan", "indien", "sans gluten", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Émincer l''oignon, hacher l''ail et râper le gingembre. Éplucher la patate douce et la couper en cubes de 2 cm, détailler le chou-fleur en petits bouquets. Rincer les lentilles.", "Chauffer l''huile dans une sauteuse et faire fondre l''oignon 5 min à feu moyen. Ajouter l''ail et le gingembre 1 min, puis la pâte de curry et remuer 1 min jusqu''à ce qu''elle embaume. Vérifier l''étiquette de la pâte pour une version végane : certaines contiennent de la pâte de crevette.", "Ajouter la patate douce, les lentilles, le lait de coco et le bouillon, porter à ébullition puis laisser mijoter 10 min à couvert.", "Ajouter le chou-fleur et poursuivre 10 à 12 min à découvert, jusqu''à ce que les légumes soient tendres et que les lentilles aient fondu en épaississant la sauce. Ajouter un peu d''eau si c''est trop épais.", "Pendant ce temps, rincer le riz et le cuire avec 1,5 fois son volume d''eau salée, 10 min à couvert à feu très doux, puis 5 min de repos.", "Ajouter les épinards au curry 1 à 2 min, puis le jus du citron vert. Saler, parsemer de coriandre et servir avec le riz."]'::jsonb),
('Risotto aux Champignons', 'Un risotto crémeux aux champignons dorés, lié au beurre et au parmesan.', 10, 30, 3, 2, 'gras', '["italien", "végétarien", "gourmand", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire chauffer le bouillon et le garder frémissant pendant toute la cuisson : du bouillon froid casserait la cuisson du riz.", "Émincer les champignons. Les faire dorer à feu vif dans une poêle avec 1 c.à.s d''huile 5 à 6 min, sans les remuer au début, puis ajouter l''ail haché 30 secondes. Saler et réserver.", "Dans une casserole à fond épais, faire fondre les échalotes hachées dans le reste de l''huile et la moitié du beurre 3 min à feu doux, sans coloration.", "Ajouter le riz et remuer 2 min, jusqu''à ce que les grains deviennent translucides sur les bords. Verser le vin et laisser s''évaporer complètement.", "Ajouter le bouillon louche par louche, en attendant que chaque louche soit presque absorbée avant la suivante et en remuant souvent. Compter 17 à 18 min : le riz doit être crémeux mais encore légèrement ferme au centre. Ajouter les champignons pour les 2 dernières minutes.", "Hors du feu, ajouter le reste du beurre froid en dés et le parmesan râpé et remuer vigoureusement 1 min pour lier (la mantecatura). Poivrer, couvrir et laisser reposer 1 min. Servir aussitôt parsemé de persil : le risotto doit s''étaler légèrement dans l''assiette."]'::jsonb),
('Bœuf Bourguignon', 'Le grand classique bourguignon : bœuf mijoté des heures dans le vin rouge avec lardons, champignons et carottes.', 30, 180, 4, 3, 'gras', '["français", "mijoté", "hiver", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper le bœuf en cubes de 5 cm et le sécher avec du papier absorbant. Couper les carottes en rondelles épaisses et émincer les oignons.", "Dans une cocotte en fonte, faire revenir les lardons 5 min à feu moyen et les réserver. Ajouter l''huile et faire dorer la viande à feu vif en plusieurs fois, 3 à 4 min par face, sans la serrer : elle doit colorer, pas bouillir. Saler, poivrer et réserver.", "Baisser le feu, faire revenir les oignons et les carottes 5 min, ajouter la farine et remuer 2 min, puis le concentré de tomate 1 min.", "Verser le vin petit à petit en grattant le fond, remettre la viande et les lardons, ajouter le bouillon, l''ail écrasé et le bouquet garni. Le liquide doit juste couvrir la viande. Porter à ébullition et laisser bouillir 2 min.", "Couvrir et laisser mijoter 2h30 à 3h à feu très doux (ou au four à 150°C), jusqu''à ce que la viande se défasse à la fourchette. Remuer de temps en temps.", "20 min avant la fin, faire dorer les champignons en quartiers dans le beurre à feu vif 5 min et les ajouter à la cocotte.", "Retirer le bouquet garni. Si la sauce est trop liquide, la faire réduire à découvert. Rectifier l''assaisonnement et servir avec des pommes de terre vapeur ou des pâtes fraîches. Il est encore meilleur réchauffé le lendemain."]'::jsonb),
('Chili con Carne', 'Un chili généreux au bœuf haché, haricots rouges et épices, mijoté jusqu''à devenir épais et fondant.', 15, 50, 4, 2, 'protéiné', '["mexicain", "épicé", "batch-cooking", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Émincer l''oignon, couper le poivron en dés et hacher l''ail.", "Chauffer l''huile dans une cocotte et faire revenir l''oignon et le poivron 5 min à feu moyen.", "Monter le feu, ajouter la viande et la faire dorer 6 à 8 min en l''émiettant, jusqu''à ce qu''elle ne soit plus rosée et commence à colorer.", "Ajouter l''ail et les épices et remuer 1 min pour les torréfier, puis le concentré de tomate 1 min. Verser les tomates et le bouillon, saler et mélanger.", "Couvrir et laisser mijoter 30 min à feu doux en remuant de temps en temps. Pendant ce temps, cuire le riz.", "Ajouter les haricots rincés et le chocolat, et cuire encore 10 min à découvert pour épaissir. Goûter et ajuster le sel et le piment. Servir avec le riz, et éventuellement une cuillère de crème et de la coriandre."]'::jsonb),
('Escalope de Poulet Milanaise', 'Une escalope de poulet aplatie et panée au parmesan, dorée à la poêle, avec un quartier de citron.', 15, 10, 2, 1, 'protéiné', '["italien", "friture", "enfants", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Placer les escalopes entre deux feuilles de film alimentaire et les aplatir au rouleau ou au fond d''une casserole jusqu''à 6 mm d''épaisseur régulière : elles cuiront uniformément. Saler et poivrer.", "Préparer trois assiettes : la farine, l''œuf battu avec une pincée de sel, la chapelure mélangée au parmesan.", "Passer chaque escalope dans la farine (tapoter pour retirer l''excédent), puis dans l''œuf, puis dans la chapelure en appuyant bien. Laisser reposer 10 min au frais : la panure accroche mieux.", "Chauffer l''huile et le beurre dans une grande poêle à feu moyen. Quand une miette de chapelure grésille aussitôt, poser les escalopes.", "Cuire 3 à 4 min par face, jusqu''à ce que la panure soit bien dorée et que la chair soit blanche à cœur, sans trace rosée (74°C). Égoutter sur du papier absorbant.", "Servir aussitôt avec des quartiers de citron, une salade de roquette ou des pâtes à la tomate."]'::jsonb),
('Brochettes d''Agneau Grillées', 'Des brochettes d''agneau marinées au citron, cumin et herbes, grillées au barbecue avec poivrons et oignon rouge.', 25, 12, 4, 2, 'protéiné', '["grillade", "méditerranéen", "été", "plat"]'::jsonb, 'public', '["grill"]'::jsonb, '["Couper l''agneau en cubes de 3 cm en retirant l''excès de gras et les nerfs.", "Mélanger l''huile, le zeste et le jus du citron, l''ail écrasé, les épices, l''origan, le sel et le poivre. Y enrober la viande, couvrir et laisser mariner au réfrigérateur au moins 2h, jusqu''à une nuit.", "Si les brochettes sont en bois, les faire tremper 30 min dans l''eau pour qu''elles ne brûlent pas. Couper les poivrons et l''oignon en morceaux de 3 cm.", "Enfiler en alternant viande et légumes, sans trop serrer. Sortir les brochettes du réfrigérateur 20 min avant la cuisson.", "Griller sur un barbecue bien chaud (braises rouges couvertes de cendre blanche) 10 à 12 min, en tournant toutes les 3 min. L''agneau se mange rosé à cœur ; prolonger de 3 à 4 min pour une viande à point.", "Laisser reposer 5 min avant de servir, avec du taboulé, une salade ou une sauce au yaourt."]'::jsonb),
('Poulet Curry Coco', 'Un curry rouge thaï au poulet et au lait de coco, parfumé au basilic thaï et au citron vert.', 15, 20, 3, 2, 'protéiné', '["thaï", "asiatique", "épicé", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Rincer le riz et le cuire avec 1,25 fois son volume d''eau, 12 min à couvert à feu très doux puis 5 min de repos.", "Couper le poulet en lanières de 1 cm, le poivron en lanières et l''oignon en quartiers fins.", "Dans une sauteuse, chauffer l''huile avec 4 c.à.s de la partie épaisse du lait de coco (le dessus de la boîte) et la pâte de curry. Cuire 2 à 3 min en remuant, jusqu''à ce que ça embaume et que l''huile se sépare légèrement. La force des pâtes varie : en mettre moins au début si on craint le piquant.", "Ajouter le poulet et le faire revenir 3 min pour l''enrober.", "Verser le reste du lait de coco, ajouter le poivron et l''oignon et laisser mijoter 8 à 10 min, jusqu''à ce que le poulet soit cuit (plus de trace rosée au centre) et les légumes encore croquants. Ne pas faire bouillir fort, le lait de coco tranche.", "Assaisonner avec le nuoc-mâm, la cassonade et le jus du demi-citron vert, goûter et ajuster. Hors du feu, ajouter les feuilles de basilic. Servir avec le riz et des quartiers de citron vert."]'::jsonb),
('Nuggets de Poulet Maison Airfryer', 'Des nuggets de vrai blanc de poulet panés au panko, croustillants sans friture, cuits à l''airfryer.', 15, 12, 3, 1, 'protéiné', '["airfryer", "enfants", "friture-sans-huile", "plat"]'::jsonb, 'public', '["airfryer"]'::jsonb, '["Couper le poulet en morceaux d''environ 3 x 4 cm et 2 cm d''épaisseur, de taille régulière pour une cuisson homogène. Saler et poivrer.", "Préparer trois assiettes : la farine, l''œuf battu, le panko mélangé au paprika et à l''ail en poudre.", "Passer chaque morceau dans la farine, puis dans l''œuf, puis dans le panko en appuyant pour bien couvrir.", "Préchauffer l''airfryer à 200°C pendant 3 min. Disposer les nuggets en une seule couche sans qu''ils se touchent (cuire en plusieurs fois si besoin) et les vaporiser ou badigeonner légèrement d''huile.", "Cuire 10 à 12 min en les retournant à mi-cuisson, jusqu''à ce qu''ils soient dorés et que la chair soit blanche à cœur (74°C).", "Servir aussitôt avec du ketchup, de la sauce barbecue ou une mayonnaise au citron."]'::jsonb),
('Ailes de Poulet Croustillantes Airfryer', 'Des ailes de poulet épicées à la peau très croustillante grâce à une pointe de levure chimique, cuites à l''airfryer.', 10, 24, 3, 1, 'protéiné', '["airfryer", "apéro", "épicé", "plat"]'::jsonb, 'public', '["airfryer"]'::jsonb, '["Si les ailes sont entières, les couper aux articulations en manchons et ailerons (jeter la pointe ou la garder pour un bouillon).", "Les sécher très soigneusement avec du papier absorbant : c''est la clé d''une peau croustillante.", "Mélanger la levure chimique, le paprika, l''ail en poudre, le sel et le poivre, et en enrober les ailes. La levure assèche la peau et la fait cloquer à la cuisson ; elle ne donne aucun goût.", "Disposer les ailes en une seule couche dans le panier de l''airfryer, sans qu''elles se chevauchent (cuire en deux fois si besoin). Cuire 12 min à 180°C.", "Retourner les ailes, monter à 200°C et cuire encore 10 à 12 min, jusqu''à ce que la peau soit dorée et craquante et que la chair près de l''os ne soit plus rosée (74°C minimum).", "Mélanger le miel et la sauce piquante, en badigeonner les ailes à la sortie de l''airfryer et servir aussitôt."]'::jsonb),
('Saumon au Four & Légumes', 'Des pavés de saumon rôtis sur un lit d''asperges et de tomates cerises, citron et aneth, le tout sur une seule plaque.', 10, 20, 2, 1, 'protéiné', '["sans gluten", "léger", "rapide", "poisson", "plat"]'::jsonb, 'public', '["oven"]'::jsonb, '["Préchauffer le four à 200°C. Sortir le saumon du réfrigérateur 10 min avant.", "Casser l''extrémité dure des asperges (elles cassent naturellement à la bonne limite). Les étaler sur une plaque avec l''ail émincé, 1 c.à.s d''huile, du sel et du poivre, et les enfourner 8 min.", "Sortir la plaque, pousser les asperges sur les côtés et poser les pavés, peau en dessous, au centre. Ajouter les tomates cerises et quelques rondelles de citron. Arroser le saumon du reste de l''huile, saler et poivrer.", "Cuire 10 à 12 min selon l''épaisseur : le saumon est cuit quand il se détache en lamelles sous la fourchette tout en restant légèrement nacré au centre. Trop cuit, il devient sec.", "Parsemer d''aneth, arroser du jus du reste du citron et servir aussitôt."]'::jsonb),
('Cabillaud en Papillote', 'Un dos de cabillaud cuit à la vapeur dans sa papillote avec courgette, tomates cerises, thym et vin blanc.', 15, 18, 2, 1, 'light', '["sans gluten", "léger", "vapeur", "poisson", "plat"]'::jsonb, 'public', '["oven"]'::jsonb, '["Préchauffer le four à 200°C. Couper la courgette en rondelles fines de 3 mm (plus épaisses, elles ne seraient pas cuites en même temps que le poisson), couper les tomates en deux et émincer l''échalote.", "Découper deux grandes feuilles de papier cuisson d''environ 40 x 40 cm. Au centre de chacune, disposer la courgette, l''échalote et les tomates, saler et poivrer.", "Poser le poisson dessus, saler, poivrer, ajouter une branche de thym et une rondelle de citron, puis arroser de vin blanc et d''huile d''olive.", "Fermer les papillotes en rabattant les bords et en les pliant plusieurs fois sur eux-mêmes pour qu''elles soient bien hermétiques. Les poser sur une plaque.", "Cuire 15 à 18 min : les papillotes gonflent. Le poisson est cuit quand sa chair devient blanche et opaque et se détache en lamelles.", "Servir les papillotes fermées et les ouvrir à table, en faisant attention à la vapeur brûlante. Accompagner de riz ou de pommes de terre vapeur."]'::jsonb),
('Crevettes Sautées à l''Ail', 'Des crevettes saisies à feu vif puis enrobées de beurre à l''ail, au persil et au piment d''Espelette, prêtes en 5 minutes.', 10, 5, 2, 1, 'protéiné', '["rapide", "sans gluten", "apéro", "fruits de mer", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Si les crevettes sont surgelées, les décongeler une nuit au réfrigérateur ou 10 min sous l''eau froide. Retirer la veine noire du dos avec la pointe d''un couteau, puis les sécher soigneusement.", "Hacher finement l''ail et le persil.", "Chauffer l''huile dans une grande poêle à feu vif. Ajouter les crevettes en une seule couche et les saisir 1 min sans les remuer, puis les retourner et cuire encore 1 min : elles doivent être roses et opaques et former un C. En forme de O, elles sont trop cuites et deviennent caoutchouteuses.", "Baisser le feu, ajouter le beurre et l''ail et remuer 1 min, sans laisser l''ail brunir (il deviendrait amer).", "Hors du feu, ajouter le persil, le piment d''Espelette, un filet de jus de citron et une pincée de sel. Servir aussitôt avec du pain pour saucer, ou sur du riz ou des pâtes."]'::jsonb),
('Maki Maison Simplifié', 'Des makis saumon, avocat et concombre roulés à la maison : riz vinaigré, feuille de nori et une natte en bambou suffisent. Environ 24 pièces.', 45, 15, 2, 3, 'light', '["japonais", "technique", "poisson", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Rincer le riz dans plusieurs eaux en le frottant, jusqu''à ce que l''eau soit claire, puis l''égoutter 15 min.", "Le mettre dans une casserole avec l''eau, porter à ébullition, couvrir et cuire 12 min à feu très doux. Retirer du feu et laisser reposer 10 min sans soulever le couvercle.", "Chauffer légèrement le vinaigre avec le sucre et le sel pour les dissoudre. Verser sur le riz chaud dans un grand plat et mélanger en le coupant à la spatule, sans l''écraser. Laisser refroidir à température ambiante, couvert d''un linge humide.", "Couper le saumon (impérativement qualité sashimi, ou congelé 7 jours à -20°C), l''avocat et le concombre épépiné en bâtonnets d''1 cm de section.", "Poser une feuille de nori, face brillante dessous, sur la natte en bambou. Avec les mains mouillées d''eau vinaigrée, étaler environ 130 g de riz en couche fine et régulière, en laissant 2 cm libres sur le bord du haut.", "Disposer une ligne de garniture sur le tiers du bas. Rouler en serrant à l''aide de la natte, d''un seul mouvement, puis mouiller le bord libre pour souder le rouleau.", "Avec un couteau bien aiguisé mouillé entre chaque coupe, couper chaque rouleau en 6 morceaux. Servir avec la sauce soja, le wasabi et le gingembre mariné."]'::jsonb),
('Pâtes au Pesto Maison', 'Des pâtes au pesto genovese frais : basilic, pignons grillés, parmesan, ail et huile d''olive, mélangé hors du feu.', 15, 12, 2, 1, 'gras', '["italien", "végétarien", "rapide", "plat"]'::jsonb, 'public', '["stovetop", "food_processor"]'::jsonb, '["Faire griller les pignons à sec dans une poêle 2 à 3 min en remuant, jusqu''à ce qu''ils soient blonds. Les laisser refroidir.", "Effeuiller le basilic (les tiges sont amères), le rincer et le sécher délicatement.", "Mixer par à-coups l''ail, les pignons et le gros sel, puis ajouter le basilic et mixer brièvement en versant l''huile d''olive en filet. Mixer par courtes impulsions : si les lames chauffent, le basilic noircit. Au mortier, piler dans le même ordre.", "Ajouter le parmesan finement râpé et mélanger à la cuillère.", "Cuire les pâtes al dente dans une grande casserole d''eau bouillante salée (10 g de sel par litre), en gardant une louche d''eau de cuisson avant de les égoutter.", "Hors du feu, mélanger les pâtes avec le pesto et 2 à 3 c.à.s d''eau de cuisson pour le rendre crémeux. Ne jamais faire chauffer le pesto : il perd sa couleur et son parfum. Servir aussitôt."]'::jsonb),
('Pâtes aux Crevettes & Tomates Cerises', 'Des linguine aux crevettes sautées, tomates cerises éclatées, ail et une pointe de piment, finies dans la poêle.', 15, 15, 2, 1, 'protéiné', '["italien", "rapide", "fruits de mer", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Porter une grande casserole d''eau à ébullition, la saler et y cuire les pâtes en comptant 1 min de moins que le temps indiqué.", "Pendant ce temps, sécher les crevettes. Chauffer 1 c.à.s d''huile dans une grande poêle à feu vif et les saisir 1 min par face, jusqu''à ce qu''elles soient roses. Les réserver.", "Dans la même poêle, ajouter le reste de l''huile, l''ail émincé et le piment et cuire 30 secondes. Ajouter les tomates coupées en deux et cuire 4 à 5 min, jusqu''à ce qu''elles éclatent et rendent leur jus. Verser le vin et laisser réduire 1 min.", "Égoutter les pâtes en gardant une louche d''eau de cuisson et les verser dans la poêle avec un peu de cette eau. Mélanger 1 à 2 min à feu vif : la sauce doit enrober les pâtes.", "Remettre les crevettes, ajouter le persil haché et le zeste du demi-citron, poivrer et servir aussitôt."]'::jsonb),
('Velouté de Potiron', 'Un velouté d''automne au potiron, onctueux grâce à une pomme de terre et un trait de crème, relevé de muscade.', 15, 30, 4, 1, 'light', '["automne", "végétarien", "batch-cooking", "soupe", "plat"]'::jsonb, 'public', '["stovetop", "blender"]'::jsonb, '["Éplucher le potiron, retirer les graines et les filaments et couper la chair en cubes de 3 cm. Éplucher la pomme de terre et la couper en cubes, émincer l''oignon.", "Dans une grande casserole, faire fondre l''oignon dans le beurre 5 min à feu moyen, sans coloration.", "Ajouter le potiron et la pomme de terre, verser le bouillon (il doit juste couvrir les légumes), porter à ébullition puis couvrir et cuire 20 à 25 min à feu doux, jusqu''à ce qu''une pointe de couteau les traverse sans résistance.", "Mixer longuement au mixeur plongeant ou au blender, jusqu''à obtenir un velouté parfaitement lisse. Attention aux projections avec un liquide bouillant : remplir le blender à moitié seulement.", "Ajouter la crème et la muscade, saler, poivrer, et ajuster l''épaisseur avec un peu de bouillon ou d''eau. Réchauffer sans faire bouillir et servir."]'::jsonb),
('Salade César Poulet', 'Une salade romaine croquante, du poulet doré, des croûtons à l''ail et une sauce César crémeuse aux anchois et au parmesan.', 20, 15, 2, 1, 'protéiné', '["salade", "gourmand", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Croûtons : couper le pain en cubes de 2 cm, les mélanger avec 2 c.à.s d''huile et la moitié de l''ail écrasé et les faire dorer à la poêle 5 min à feu moyen en remuant. Réserver sur du papier absorbant.", "Saler et poivrer les blancs de poulet. Les cuire dans la poêle avec le reste de l''huile 5 à 6 min par face à feu moyen, jusqu''à ce que la chair soit blanche à cœur (74°C). Laisser reposer 5 min puis trancher.", "Sauce : écraser les anchois à la fourchette avec le reste de l''ail, ajouter la mayonnaise, le jus de citron, la sauce Worcestershire, la moitié du parmesan râpé et du poivre. Détendre avec le lait pour qu''elle soit nappante.", "Laver et bien sécher la romaine (une salade mouillée dilue la sauce), puis la couper en morceaux.", "Mélanger la salade avec la sauce, répartir dans les assiettes, ajouter le poulet et les croûtons, et terminer par des copeaux du reste de parmesan."]'::jsonb),
('Houmous Maison', 'Un houmous très lisse et crémeux au tahini, citron et ail, à servir avec des crudités ou du pain pita.', 15, 15, 4, 1, 'light', '["apéro", "végan", "batch-cooking", "tartinade"]'::jsonb, 'public', '["stovetop", "food_processor"]'::jsonb, '["Rincer les pois chiches, les mettre dans une casserole avec le bicarbonate, couvrir d''eau et cuire 15 min à frémissement : ils deviennent très tendres et leur peau se détache, c''est le secret d''un houmous lisse. Les égoutter et les rincer à l''eau froide.", "Dans le robot, mixer le tahini avec le jus du citron, l''ail et le sel 1 min, jusqu''à ce que le mélange s''éclaircisse et épaississe.", "Ajouter les pois chiches et le cumin et mixer 2 à 3 min en raclant les parois.", "Robot en marche, ajouter l''eau glacée cuillère par cuillère, jusqu''à ce que le houmous soit très lisse et aérien. Goûter et ajuster le sel, le citron ou le cumin.", "Servir dans une assiette creuse, creuser un sillon à la cuillère, arroser d''huile d''olive et saupoudrer de paprika. Se garde 4 jours au réfrigérateur."]'::jsonb),
('Smoothie Protéiné Banane-Cacahuète', 'Un smoothie épais à la banane, au beurre de cacahuète et à la protéine en poudre, idéal après le sport.', 5, 0, 1, 1, 'protéiné', '["sans cuisson", "rapide", "sport", "boisson", "goûter"]'::jsonb, 'public', '["blender"]'::jsonb, '["Éplucher la banane et la couper en rondelles. Une banane congelée à l''avance donne un smoothie plus épais et plus frais, sans avoir besoin de glaçons.", "Verser le lait dans le blender en premier, puis la protéine en poudre, les flocons d''avoine, le beurre de cacahuète, la banane et les glaçons.", "Mixer 45 secondes à 1 min à pleine puissance, jusqu''à ce que ce soit parfaitement lisse.", "Ajouter un peu de lait si c''est trop épais, et boire aussitôt."]'::jsonb),
('Energy Balls Dattes & Amandes', 'Des bouchées énergétiques sans cuisson aux dattes, amandes et cacao, roulées dans la noix de coco. Environ 16 pièces.', 15, 0, 8, 1, 'light', '["sans cuisson", "végan", "sport", "goûter"]'::jsonb, 'public', '["food_processor"]'::jsonb, '["Si les dattes sont sèches et dures, les faire tremper 10 min dans l''eau chaude puis bien les égoutter.", "Mixer les amandes au robot 20 à 30 secondes en morceaux grossiers.", "Ajouter les dattes, le cacao et le sel et mixer 1 à 2 min, jusqu''à obtenir une pâte collante qui se tient quand on la presse entre les doigts. Si elle est trop sèche, ajouter 1 c.à.s d''eau.", "Former des boules d''environ 20 g entre les paumes et les rouler dans la noix de coco.", "Réfrigérer 30 min pour qu''elles se raffermissent. Se conservent une semaine au réfrigérateur dans une boîte fermée."]'::jsonb),
('Cookies à l''Avoine', 'Des cookies moelleux aux flocons d''avoine, à la cannelle et aux pépites de chocolat. Environ 14 cookies.', 20, 12, 7, 1, 'gras', '["végétarien", "four", "goûter"]'::jsonb, 'public', '["oven"]'::jsonb, '["Préchauffer le four à 180°C et couvrir deux plaques de papier cuisson.", "Travailler le beurre mou avec la cassonade 2 min, jusqu''à ce que le mélange soit crémeux. Ajouter l''œuf et la vanille et mélanger.", "Ajouter la farine, les flocons d''avoine, le bicarbonate, la cannelle et le sel, et mélanger juste jusqu''à ce que la pâte soit homogène. Incorporer les pépites de chocolat.", "Former des boules d''environ 40 g, les poser sur les plaques en les espaçant de 5 cm et les aplatir légèrement avec la paume : avec l''avoine, elles s''étalent moins que des cookies classiques.", "Cuire 11 à 13 min, jusqu''à ce que les bords soient dorés et le centre encore mou.", "Laisser 10 min sur la plaque, le temps qu''ils se raffermissent, puis les déplacer sur une grille."]'::jsonb),
('Burger Maison au Barbecue', 'Un burger au bœuf haché grillé au barbecue, cheddar fondu, crudités et pain toasté.', 20, 12, 4, 2, 'gras', '["bbq", "été", "gourmand", "plat"]'::jsonb, 'public', '["grill"]'::jsonb, '["Diviser la viande en 4 portions de 150 g et former des steaks de 1,5 cm d''épaisseur, un peu plus larges que les pains (ils rétrécissent). Ne pas trop travailler la viande. Creuser un petit creux au centre avec le pouce pour éviter qu''ils ne gonflent. Réfrigérer 20 min.", "Allumer le barbecue et attendre que les braises soient bien rouges et couvertes de cendre blanche. Couper la tomate et l''oignon rouge en rondelles et les cornichons en lamelles.", "Saler et poivrer les steaks des deux côtés juste avant la cuisson.", "Les poser sur la grille chaude et cuire 3 à 4 min sans les bouger, les retourner une seule fois, poser le cheddar dessus et cuire encore 3 à 4 min, couvercle fermé si possible pour faire fondre le fromage. Pour les enfants et les femmes enceintes, cuire le steak haché à cœur (70°C, plus de trace rosée).", "Ouvrir les pains, beurrer légèrement les faces coupées et les toaster 1 min sur la grille.", "Monter les burgers : pain, ketchup et moutarde, salade, steak au cheddar, tomate, oignon, cornichons, et refermer. Servir aussitôt."]'::jsonb),
('Brochettes de Bœuf Marinées BBQ', 'Des brochettes de bœuf marinées soja-miel-ail, grillées avec poivrons, courgette et oignon rouge.', 25, 10, 4, 2, 'protéiné', '["bbq", "été", "grillade", "plat"]'::jsonb, 'public', '["grill"]'::jsonb, '["Couper le bœuf en cubes de 3 cm. Mélanger la sauce soja, le miel, l''huile, l''ail écrasé, le paprika et du poivre (pas de sel : la sauce soja suffit). Y enrober la viande et laisser mariner 1 à 4h au réfrigérateur.", "Si les brochettes sont en bois, les faire tremper 30 min dans l''eau. Couper les poivrons, la courgette et l''oignon en morceaux de 3 cm.", "Enfiler en alternant viande et légumes, sans trop serrer.", "Griller sur braises chaudes mais pas flambantes, 8 à 10 min au total en tournant toutes les 2 min : le miel caramélise vite et brûlerait sur un feu trop vif. La viande est saignante à 8 min, à point à 10 min.", "Laisser reposer 5 min avant de servir, avec du riz ou une salade."]'::jsonb),
('Salade Quinoa Avocat & Feta', 'Une salade fraîche de quinoa, avocat, feta, tomates cerises et concombre, relevée de citron et d''herbes.', 20, 15, 2, 1, 'light', '["végétarien", "sans gluten", "rapide", "salade", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Rincer le quinoa dans une passoire fine sous l''eau froide pour retirer son amertume. Le mettre dans une casserole avec 240 ml d''eau salée, porter à ébullition, couvrir et cuire 12 à 15 min à feu doux, jusqu''à ce que l''eau soit absorbée. Laisser reposer 5 min à couvert.", "Égrener le quinoa à la fourchette et l''étaler dans une assiette pour qu''il refroidisse vite.", "Couper les tomates en deux, le concombre en dés, émincer très finement l''oignon rouge et ciseler les herbes. Couper l''avocat en dés et l''arroser d''un peu de jus de citron.", "Vinaigrette : mélanger le reste du jus de citron avec l''huile d''olive, du sel et du poivre.", "Mélanger le quinoa refroidi avec les légumes et la vinaigrette, ajouter l''avocat et la feta émiettée au dernier moment et parsemer d''herbes."]'::jsonb),
('Wrap Thon & Crudités', 'Un wrap frais et rapide au thon, maïs, carotte râpée et salade, pour le déjeuner ou le pique-nique.', 10, 1, 2, 1, 'protéiné', '["rapide", "pique-nique", "plat"]'::jsonb, 'public', '[]'::jsonb, '["Égoutter soigneusement le thon et le maïs : trop humides, ils détremperaient la tortilla.", "Émietter le thon et le mélanger avec la mayonnaise, un filet de jus de citron et du poivre.", "Râper la carotte, épépiner la tomate et la couper en dés, rincer et sécher la salade.", "Réchauffer les tortillas 15 à 20 secondes dans une poêle sèche (ou quelques secondes au micro-ondes) : elles deviennent souples et ne cassent pas au pliage.", "Étaler la salade sur le tiers inférieur de chaque tortilla en laissant 3 cm libres sur les côtés, ajouter le thon, le maïs, la carotte et la tomate.", "Rabattre les côtés vers le centre, puis rouler serré depuis le bas. Couper en deux en biais et servir, ou emballer dans du papier aluminium pour emporter."]'::jsonb),
('Smoothie Bowl Mangue-Banane', 'Un smoothie épais à la mangue et à la banane glacées, servi dans un bol et garni de granola, de chia et de fruits frais.', 10, 0, 1, 1, 'light', '["petit-déjeuner", "végétarien", "sans cuisson", "rapide"]'::jsonb, 'public', '["blender"]'::jsonb, '["La veille ou quelques heures avant, éplucher la banane, la couper en rondelles et la congeler à plat.", "Mettre la mangue et la banane congelées dans le blender avec la moitié du lait de coco.", "Mixer par à-coups en raclant les parois entre chaque, et n''ajouter le reste du lait de coco que si les lames tournent à vide : le smoothie doit rester épais comme une glace molle, pour se manger à la cuillère.", "Verser aussitôt dans un bol et garnir de granola, de graines de chia et de fruits frais coupés. Déguster tout de suite, avant qu''il ne fonde."]'::jsonb),
('Gougères au comté', 'Des petits choux au fromage, légers et creux, servis tièdes à l''apéritif comme en Bourgogne. Environ 35 gougères.', 25, 25, 8, 2, 'gras', '["français", "apéro", "four", "gâteau apéro"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Préchauffer le four à 190°C (chaleur statique) et couvrir deux plaques de papier cuisson.", "Dans une casserole, porter à ébullition l''eau, le lait, le beurre en morceaux et le sel, jusqu''à ce que le beurre soit fondu.", "Retirer du feu, verser la farine d''un coup et mélanger vivement à la spatule jusqu''à ce qu''il n''y ait plus de farine sèche.", "Remettre sur feu moyen et dessécher la pâte 1 à 2 min en remuant sans arrêt, jusqu''à ce qu''elle forme une boule qui se détache des parois et laisse une fine pellicule au fond.", "Transférer dans un saladier et laisser tiédir 5 min. Ajouter les œufs battus en 4 fois en mélangeant bien entre chaque ajout : la pâte est prête quand elle tombe de la spatule en formant une pointe. Incorporer 100 g de comté, du poivre et la muscade.", "Déposer des boules de 3 cm à la poche ou avec deux cuillères, en les espaçant de 3 cm, et parsemer du reste de comté.", "Cuire 20 à 25 min sans ouvrir le four pendant les 20 premières minutes, sinon elles retombent. Elles sont prêtes quand elles sont bien dorées et légères. Servir tièdes."]'::jsonb),
('Cake salé olives-jambon', 'Le cake apéro classique au jambon, olives vertes et gruyère, à couper en cubes ou en tranches.', 15, 45, 10, 1, 'gras', '["français", "apéro", "four", "gâteau apéro"]'::jsonb, 'public', '["oven"]'::jsonb, '["Préchauffer le four à 180°C. Beurrer et fariner un moule à cake de 25 cm (ou le tapisser de papier cuisson).", "Couper le jambon en petits dés et les olives en rondelles.", "Dans un saladier, fouetter les œufs avec le lait et l''huile d''olive. Ajouter la farine mélangée à la levure et mélanger juste jusqu''à ce que la pâte soit lisse.", "Incorporer le gruyère, le jambon et les olives. Poivrer et ne saler que très peu : jambon, olives et fromage sont déjà salés.", "Verser dans le moule et cuire 40 à 45 min, jusqu''à ce que le cake soit doré et qu''une lame plantée au centre ressorte sèche.", "Laisser tiédir 10 min, démouler et laisser refroidir sur une grille avant de couper en tranches ou en cubes. Il est encore meilleur le lendemain."]'::jsonb),
('Palmiers feuilletés au pesto', 'Des palmiers croustillants à la pâte feuilletée, au pesto et au parmesan, prêts en 30 minutes. Environ 24 pièces.', 15, 15, 6, 1, 'gras', '["italien", "apéro", "four", "gâteau apéro"]'::jsonb, 'public', '["oven"]'::jsonb, '["Dérouler la pâte feuilletée. Si elle est ronde, recouper les bords pour obtenir un carré.", "Étaler le pesto en couche fine sur toute la surface et parsemer de parmesan.", "Rouler deux côtés opposés de la pâte vers le centre jusqu''à ce qu''ils se rejoignent. Filmer et placer 20 à 30 min au réfrigérateur (ou 10 min au congélateur) : bien froide, la pâte se coupe nettement.", "Préchauffer le four à 200°C et couvrir une plaque de papier cuisson.", "Couper le rouleau en tranches d''1 cm et les poser à plat sur la plaque en les espaçant de 4 cm, car elles gonflent et s''étalent.", "Cuire 12 à 15 min, jusqu''à ce que les palmiers soient bien dorés. Laisser refroidir sur une grille : ils deviennent croustillants en refroidissant."]'::jsonb),
('Sablés apéritifs au parmesan', 'Des petits sablés salés au parmesan et au romarin, qui fondent en bouche. Environ 30 sablés.', 20, 15, 8, 1, 'gras', '["italien", "apéro", "four", "gâteau apéro"]'::jsonb, 'public', '["oven"]'::jsonb, '["Dans un saladier, mélanger la farine, le parmesan, le romarin finement haché et du poivre. Pas de sel : le parmesan suffit.", "Ajouter le beurre froid en dés et sabler du bout des doigts jusqu''à obtenir une texture de sable grossier.", "Ajouter le jaune d''œuf et rassembler rapidement la pâte en boule, sans la pétrir.", "Former un boudin de 3 à 4 cm de diamètre, l''envelopper de film et réfrigérer au moins 1h.", "Préchauffer le four à 180°C. Couper le boudin en rondelles de 5 mm et les poser sur une plaque couverte de papier cuisson.", "Cuire 12 à 15 min, jusqu''à ce que les bords soient blonds. Laisser refroidir sur une grille : ils durcissent en refroidissant. Conserver dans une boîte hermétique."]'::jsonb),
('Brochettes tomate-mozzarella', 'Des piques apéritives tomate cerise, mozzarella et basilic, arrosées d''huile d''olive et de crème de balsamique.', 15, 0, 6, 1, 'light', '["italien", "apéro", "sans cuisson", "végétarien"]'::jsonb, 'public', '[]'::jsonb, '["Égoutter les billes de mozzarella et les sécher sur du papier absorbant. Rincer et sécher les tomates cerises.", "Mélanger la mozzarella avec l''huile d''olive, le sel et le poivre et laisser mariner 15 min.", "Sur chaque pique, enfiler une tomate, une feuille de basilic pliée en deux, puis une bille de mozzarella.", "Disposer sur un plat et arroser de quelques gouttes de crème de balsamique juste avant de servir, pour que le basilic reste frais."]'::jsonb),
('Tapenade', 'La tartinade provençale d''olives noires, câpres et anchois, à étaler sur des toasts.', 10, 0, 6, 1, 'gras', '["provençal", "apéro", "sans cuisson", "tartinade"]'::jsonb, 'public', '["food_processor"]'::jsonb, '["Égoutter les olives et les câpres. Éplucher l''ail et retirer le germe s''il y en a un.", "Mettre les olives, les câpres, les anchois, l''ail, le thym et le jus de citron dans le robot.", "Mixer par à-coups en ajoutant l''huile d''olive en filet, jusqu''à obtenir une pâte encore légèrement grumeleuse : trop mixée, elle devient une purée sans texture.", "Poivrer (inutile de saler, olives et anchois le sont déjà). Servir sur des toasts ou avec des crudités. Se garde une semaine au réfrigérateur, recouverte d''un filet d''huile."]'::jsonb),
('Tzatziki', 'La sauce grecque au yaourt, concombre, ail et aneth, fraîche et parfaite en dip avec du pain pita.', 15, 0, 6, 1, 'light', '["grec", "apéro", "sans cuisson", "végétarien", "tartinade"]'::jsonb, 'public', '[]'::jsonb, '["Râper le concombre avec la peau, le mélanger avec le sel et le laisser dégorger 15 min dans une passoire.", "Presser fortement le concombre dans un torchon propre pour en extraire le maximum d''eau : sinon le tzatziki devient liquide.", "Mélanger le yaourt avec le concombre, l''ail râpé, l''huile d''olive, le jus de citron et l''aneth ciselé. Poivrer et goûter pour le sel.", "Réfrigérer au moins 30 min pour que les saveurs se mélangent. Servir frais avec un filet d''huile d''olive, des pitas ou des crudités."]'::jsonb),
('Rillettes de thon', 'Une tartinade express de thon, fromage frais, citron et échalote, à servir sur des toasts ou des blinis.', 10, 0, 6, 1, 'protéiné', '["français", "apéro", "sans cuisson", "rapide", "tartinade"]'::jsonb, 'public', '[]'::jsonb, '["Égoutter soigneusement le thon et l''émietter à la fourchette.", "Hacher très finement l''échalote et ciseler la ciboulette.", "Mélanger le thon avec le fromage frais, le jus du demi-citron, l''échalote et la ciboulette, en écrasant jusqu''à obtenir une texture de rillettes. Assaisonner de piment d''Espelette et de poivre.", "Réfrigérer 30 min et servir frais sur des toasts, des blinis ou des bâtonnets de légumes."]'::jsonb),
('Mojito', 'Le cocktail cubain au rhum blanc, citron vert, menthe fraîche et eau gazeuse. L''abus d''alcool est dangereux pour la santé, à consommer avec modération.', 5, 0, 1, 1, 'light', '["cubain", "apéro", "boisson", "cocktail", "alcool"]'::jsonb, 'public', '[]'::jsonb, '["Couper le demi-citron vert en 4 quartiers et les mettre dans un grand verre (type highball) avec le sucre.", "Écraser au pilon 10 secondes pour extraire le jus et dissoudre le sucre.", "Ajouter les feuilles de menthe et les presser doucement 3 ou 4 fois, sans les déchiqueter : broyées, elles libèrent de l''amertume.", "Remplir le verre de glace pilée, verser le rhum et mélanger de bas en haut avec une cuillère.", "Compléter avec l''eau gazeuse, remuer une dernière fois délicatement et décorer d''une branche de menthe."]'::jsonb),
('Virgin mojito', 'La version sans alcool du mojito : citron vert, menthe, sucre de canne et eau gazeuse.', 5, 0, 1, 1, 'light', '["apéro", "boisson", "cocktail", "sans alcool"]'::jsonb, 'public', '[]'::jsonb, '["Couper le demi-citron vert en 4 quartiers et les mettre dans un grand verre avec le sucre.", "Écraser au pilon 10 secondes pour extraire le jus et dissoudre le sucre.", "Ajouter la menthe et la presser doucement 3 ou 4 fois, sans la déchiqueter.", "Remplir de glace pilée, compléter avec l''eau gazeuse (ou de la limonade pour une version plus sucrée) et mélanger de bas en haut. Décorer d''une branche de menthe."]'::jsonb),
('Spritz', 'L''apéritif vénitien : prosecco, Aperol et eau gazeuse sur glace, avec une tranche d''orange (la règle du 3-2-1). L''abus d''alcool est dangereux pour la santé, à consommer avec modération.', 3, 0, 1, 1, 'light', '["italien", "apéro", "boisson", "cocktail", "alcool"]'::jsonb, 'public', '[]'::jsonb, '["Remplir un grand verre à vin de glaçons : un verre bien rempli dilue moins le cocktail.", "Verser d''abord le prosecco bien frais, puis l''Aperol, puis l''eau gazeuse (proportions 3-2-1).", "Mélanger une seule fois délicatement pour ne pas casser les bulles, et ajouter la tranche d''orange."]'::jsonb),
('Sangria', 'La sangria espagnole au vin rouge et aux fruits, macérée au frais avant d''être allongée d''eau gazeuse. L''abus d''alcool est dangereux pour la santé, à consommer avec modération.', 15, 0, 6, 1, 'light', '["espagnol", "apéro", "boisson", "cocktail", "alcool"]'::jsonb, 'public', '[]'::jsonb, '["Laver l''orange et le citron, les couper en fines rondelles. Couper la pomme en petits dés.", "Dans un grand pichet, mélanger les fruits avec le sucre et le brandy et laisser reposer 10 min.", "Verser le vin, ajouter le bâton de cannelle et mélanger jusqu''à ce que le sucre soit dissous.", "Couvrir et laisser macérer au réfrigérateur au moins 2h, jusqu''à 12h. Au-delà, l''écorce des agrumes rend la sangria amère.", "Au moment de servir, ajouter l''eau gazeuse bien froide et des glaçons, et servir avec quelques morceaux de fruits dans chaque verre."]'::jsonb),
('Piña colada', 'Le cocktail portoricain au rhum blanc, crème de coco et jus d''ananas, mixé avec de la glace. L''abus d''alcool est dangereux pour la santé, à consommer avec modération.', 5, 0, 1, 1, 'gras', '["portoricain", "apéro", "boisson", "cocktail", "alcool"]'::jsonb, 'public', '["blender"]'::jsonb, '["Mettre le rhum, la crème de coco, le jus d''ananas et les glaçons dans le blender.", "Mixer 15 à 20 secondes, jusqu''à ce que le mélange soit lisse et mousseux.", "Verser dans un grand verre bien frais et décorer d''une tranche d''ananas. Sans blender, secouer vigoureusement 15 secondes dans un shaker rempli de glaçons, puis filtrer sur de la glace pilée."]'::jsonb),
('Margarita', 'Le cocktail mexicain à la tequila, au triple sec et au citron vert, servi dans un verre au bord givré de sel. L''abus d''alcool est dangereux pour la santé, à consommer avec modération.', 5, 0, 1, 1, 'light', '["mexicain", "apéro", "boisson", "cocktail", "alcool"]'::jsonb, 'public', '[]'::jsonb, '["Placer le verre (type coupe) 10 min au congélateur.", "Frotter le bord du verre avec un quartier de citron vert, puis le tremper dans une assiette de sel fin pour le givrer.", "Mettre la tequila, le triple sec et le jus de citron vert dans un shaker (ou un bocal bien fermé) rempli de glaçons.", "Secouer énergiquement 10 à 15 secondes, jusqu''à ce que le shaker soit glacé.", "Filtrer dans le verre givré et servir aussitôt, avec un quartier de citron vert."]'::jsonb),
('Kir', 'L''apéritif bourguignon : vin blanc aligoté bien frais relevé de crème de cassis. L''abus d''alcool est dangereux pour la santé, à consommer avec modération.', 2, 0, 1, 1, 'light', '["français", "apéro", "boisson", "alcool"]'::jsonb, 'public', '[]'::jsonb, '["Mettre le vin blanc au réfrigérateur au moins 2h à l''avance : il doit être servi à 8-10°C.", "Verser la crème de cassis au fond d''un verre à vin.", "Compléter avec le vin blanc bien frais : il se mélange tout seul en versant, inutile de remuer. Servir aussitôt."]'::jsonb),
('Spaghetti bolognaise', 'La sauce à la viande mijotée longuement avec tomate, carotte et céleri, servie sur des spaghetti.', 20, 90, 4, 1, 'gras', '["italien", "pâtes", "famille", "mijoté", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Hacher finement l''oignon, la carotte, le céleri et l''ail.", "Chauffer l''huile dans une cocotte et faire suer les légumes 8 à 10 min à feu moyen, jusqu''à ce qu''ils soient tendres et commencent à dorer.", "Monter le feu, ajouter la viande et l''émietter à la cuillère. La laisser dorer 5 à 6 min sans trop remuer : la coloration donne du goût à la sauce.", "Ajouter le concentré de tomate et remuer 1 min, puis verser le vin et laisser réduire de moitié en grattant le fond.", "Ajouter les tomates, le lait, le laurier, du sel et du poivre. Couvrir en laissant un espace et laisser mijoter 1h à 1h15 à feu très doux, en remuant de temps en temps. Ajouter un peu d''eau si la sauce attache. Elle doit être épaisse et brillante.", "Cuire les spaghetti dans une grande casserole d''eau bouillante salée (10 g de sel par litre) selon le temps du paquet, les égoutter en gardant une louche d''eau de cuisson.", "Retirer le laurier, mélanger les pâtes avec la sauce et un peu d''eau de cuisson pour lier. Servir avec le parmesan râpé."]'::jsonb),
('Spaghetti aglio, olio e peperoncino', 'Le plat de pâtes le plus simple d''Italie : ail doré dans l''huile d''olive, piment et persil.', 5, 12, 4, 1, 'light', '["italien", "pâtes", "rapide", "économique", "végan", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Porter une grande casserole d''eau à ébullition, la saler (10 g de sel par litre) et y cuire les spaghetti 1 min de moins que le temps indiqué.", "Pendant ce temps, couper l''ail en fines lamelles et hacher le persil.", "Dans une grande poêle, chauffer l''huile avec l''ail à feu doux 3 à 4 min : l''ail doit juste blondir. S''il brunit, il devient amer et il faut recommencer. Ajouter le piment hors du feu.", "Égoutter les pâtes en gardant un verre d''eau de cuisson. Les verser dans la poêle avec 4 c.à.s d''eau de cuisson.", "Faire sauter 1 min à feu vif en remuant : l''eau et l''huile forment une sauce légère qui enrobe les pâtes. Ajouter le persil et servir aussitôt."]'::jsonb),
('Spaghetti alle vongole', 'Spaghetti aux palourdes, vin blanc, ail et persil, comme sur la côte napolitaine.', 20, 15, 4, 2, 'light', '["italien", "pâtes", "fruits de mer", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire tremper les palourdes 1h dans de l''eau froide salée (35 g de sel par litre) pour qu''elles rejettent leur sable, puis les rincer. Jeter celles qui sont cassées ou restent ouvertes quand on les tapote.", "Cuire les spaghetti dans une grande casserole d''eau bouillante salée, 2 min de moins que le temps indiqué.", "Pendant ce temps, dans une grande sauteuse, chauffer l''huile avec l''ail écrasé et le piment 1 à 2 min à feu moyen. Ajouter les palourdes et le vin, couvrir et cuire 3 à 5 min à feu vif en secouant, jusqu''à ce qu''elles s''ouvrent. Jeter celles restées fermées.", "Retirer l''ail. Égoutter les pâtes en gardant un peu d''eau de cuisson et les verser dans la sauteuse avec le jus des palourdes.", "Terminer la cuisson 2 min à feu vif en remuant, jusqu''à ce que le jus nappe les pâtes. Ajouter le persil haché et un filet d''huile d''olive, servir aussitôt."]'::jsonb),
('Bucatini all''amatriciana', 'Une sauce tomate au guanciale croustillant et au pecorino, spécialité d''Amatrice.', 10, 25, 4, 1, 'gras', '["italien", "pâtes", "classique", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper le guanciale en lardons épais (on peut le remplacer par de la pancetta ou de la poitrine fumée).", "Le faire rissoler à sec dans une sauteuse à feu moyen 6 à 8 min, jusqu''à ce qu''il soit doré et que sa graisse ait fondu. Déglacer au vin blanc et laisser s''évaporer.", "Retirer la moitié des lardons pour la fin. Ajouter les tomates écrasées à la main et le piment, saler légèrement et laisser mijoter 15 min.", "Cuire les bucatini dans une grande casserole d''eau bouillante salée selon le temps du paquet, les égoutter en gardant un peu d''eau de cuisson.", "Mélanger les pâtes à la sauce 1 min sur le feu, avec un peu d''eau de cuisson si besoin. Hors du feu, ajouter la moitié du pecorino râpé. Servir avec le reste du pecorino et les lardons réservés."]'::jsonb),
('Spaghetti alla puttanesca', 'Une sauce tomate relevée aux olives, câpres et anchois, prête le temps de cuire les pâtes.', 10, 20, 4, 1, 'light', '["italien", "pâtes", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Dans une sauteuse, chauffer l''huile à feu doux avec l''ail haché, les anchois et le piment 2 à 3 min, en écrasant les anchois : ils fondent dans l''huile.", "Ajouter les tomates écrasées, porter à frémissement et laisser mijoter 10 min.", "Ajouter les olives coupées en deux et les câpres rincées, poursuivre 5 min. Goûter avant de saler : anchois, olives et câpres sont déjà salés.", "Cuire les spaghetti dans une grande casserole d''eau bouillante salée, les égoutter en gardant un peu d''eau de cuisson.", "Mélanger les pâtes avec la sauce 1 min sur le feu, en ajoutant un peu d''eau de cuisson si besoin. Parsemer de persil et servir."]'::jsonb),
('Spaghetti cacio e pepe', 'Trois ingrédients seulement : pecorino, poivre noir et eau de cuisson émulsionnés en une sauce crémeuse.', 5, 12, 2, 2, 'gras', '["italien", "pâtes", "rapide", "végétarien", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Râper très finement le pecorino. Concasser le poivre au mortier ou au moulin réglé gros.", "Cuire les spaghetti dans peu d''eau (environ 2 litres) peu salée, car le pecorino l''est déjà : l''eau sera plus riche en amidon, ce qui aide la sauce à tenir.", "Dans une grande poêle, torréfier le poivre à sec 1 min à feu moyen, puis ajouter une louche d''eau de cuisson.", "Dans un bol, mélanger le pecorino avec 3 à 4 c.à.s d''eau de cuisson tiède (pas bouillante) pour obtenir une pâte lisse.", "Égoutter les pâtes 1 min avant la fin de leur cuisson et les mettre dans la poêle avec le poivre. Remuer 1 min, puis couper le feu et attendre 30 secondes.", "Ajouter la pâte de pecorino hors du feu en mélangeant vivement, avec un peu d''eau de cuisson si besoin, jusqu''à ce qu''une sauce crémeuse enrobe les pâtes. Trop chaud, le fromage ferait des grumeaux. Servir aussitôt."]'::jsonb),
('Spaghetti aux boulettes de viande', 'Des boulettes moelleuses de bœuf et porc mijotées dans une sauce tomate, sur des spaghetti.', 30, 40, 4, 2, 'gras', '["italien", "américain", "pâtes", "famille", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Émietter la mie de pain dans le lait et laisser gonfler 5 min.", "Dans un saladier, mélanger les viandes, la mie de pain essorée, l''œuf, la moitié du parmesan râpé, 1 gousse d''ail râpée, le persil, 1 c.à.c de sel et du poivre, sans trop pétrir. Former des boulettes de 4 cm avec les mains mouillées.", "Dans une sauteuse, dorer les boulettes dans 2 c.à.s d''huile 6 à 8 min en les retournant. Les réserver.", "Dans la même sauteuse, faire fondre l''oignon haché dans le reste d''huile 5 min, ajouter le reste de l''ail 1 min, puis la passata et quelques feuilles de basilic. Saler et porter à frémissement.", "Remettre les boulettes dans la sauce, couvrir et laisser mijoter 20 à 25 min à feu doux : elles doivent être cuites à cœur (70 °C).", "Cuire les spaghetti dans une grande casserole d''eau bouillante salée et les égoutter. Servir avec les boulettes, la sauce, le reste de parmesan et du basilic."]'::jsonb),
('Penne all''arrabbiata', 'Des penne dans une sauce tomate à l''ail franchement relevée de piment.', 5, 25, 4, 1, 'light', '["italien", "pâtes", "épicé", "végan", "économique", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Chauffer l''huile dans une sauteuse avec l''ail écrasé et le piment 2 min à feu doux, sans laisser brunir l''ail.", "Ajouter les tomates écrasées à la main, saler et laisser mijoter 20 min à feu moyen, jusqu''à ce que la sauce épaississe. Retirer l''ail.", "Cuire les penne dans une grande casserole d''eau bouillante salée 1 min de moins que le temps indiqué.", "Les égoutter, les verser dans la sauce et mélanger 1 min sur le feu. Ajuster le piment selon les goûts, parsemer de persil et servir."]'::jsonb),
('Penne alla vodka', 'Une sauce tomate crémeuse et douce, arrondie par une touche de vodka qui fait ressortir le goût de la tomate.', 10, 25, 4, 1, 'gras', '["italien", "américain", "pâtes", "végétarien", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire fondre le beurre dans une sauteuse et y faire suer l''échalote et l''ail hachés 3 min à feu doux.", "Ajouter le concentré de tomate et le piment et remuer 3 à 4 min, jusqu''à ce que le concentré fonce légèrement et attache un peu au fond.", "Verser la vodka (hors de la flamme si on cuit au gaz) et laisser réduire 1 min en grattant le fond. L''alcool s''évapore à la cuisson.", "Ajouter la passata et laisser mijoter 10 min, puis la crème. Saler et garder au chaud à feu très doux.", "Cuire les penne dans une grande casserole d''eau bouillante salée et les égoutter en gardant un peu d''eau de cuisson.", "Mélanger les pâtes à la sauce avec le parmesan râpé et un peu d''eau de cuisson jusqu''à ce que la sauce soit onctueuse. Servir avec du basilic."]'::jsonb),
('Penne au saumon et à la crème', 'Un plat de pâtes rapide au saumon, crème, citron et aneth.', 10, 15, 4, 1, 'gras', '["pâtes", "poisson", "rapide", "famille", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Retirer la peau du saumon et le couper en cubes de 2 cm.", "Cuire les penne dans une grande casserole d''eau bouillante salée selon le temps du paquet.", "Pendant ce temps, faire fondre l''échalote hachée dans le beurre 2 min, verser le vin blanc et laisser réduire de moitié.", "Ajouter la crème, le zeste du demi-citron, du sel et du poivre, porter à frémissement puis ajouter le saumon. Cuire 3 à 4 min à feu doux : le saumon doit rester juste nacré au centre.", "Égoutter les pâtes, les mélanger délicatement à la sauce avec l''aneth et un filet de jus de citron. Servir aussitôt."]'::jsonb),
('Tagliatelles au saumon fumé', 'Des tagliatelles enrobées d''une crème citronnée au saumon fumé, prêtes en 15 minutes.', 10, 10, 4, 1, 'gras', '["pâtes", "poisson", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper le saumon fumé en lanières et ciseler la ciboulette.", "Cuire les tagliatelles dans une grande casserole d''eau bouillante salée et les égoutter en gardant un peu d''eau de cuisson.", "Dans la casserole encore chaude, hors du feu, mélanger la crème, le zeste du citron, un filet de son jus et du poivre. Ne saler qu''à peine : le saumon fumé est salé.", "Ajouter les pâtes et un peu d''eau de cuisson, remuer pour bien les enrober, puis ajouter le saumon et la ciboulette au dernier moment : il ne doit pas cuire. Servir aussitôt."]'::jsonb),
('Tagliatelles aux champignons et à la crème', 'Des tagliatelles nappées d''une crème aux champignons dorés, à l''ail et au persil.', 10, 20, 4, 1, 'gras', '["pâtes", "végétarien", "champignons", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Nettoyer les champignons avec un papier humide et les émincer.", "Chauffer l''huile et la moitié du beurre dans une grande poêle à feu vif. Y saisir les champignons en une seule couche (en deux fois si besoin) 6 à 8 min, sans remuer au début, jusqu''à ce qu''ils soient bien dorés. Saler en fin de cuisson.", "Baisser le feu, ajouter le reste du beurre, les échalotes et l''ail hachés 2 min. Verser le vin et laisser réduire presque à sec, puis ajouter la crème et laisser épaissir 3 min.", "Cuire les tagliatelles dans une grande casserole d''eau bouillante salée et les égoutter en gardant un peu d''eau de cuisson.", "Mélanger les pâtes à la sauce avec le parmesan râpé et un peu d''eau de cuisson. Poivrer, parsemer de persil et servir."]'::jsonb),
('Fettuccine Alfredo', 'Des fettuccine enrobées de beurre et de parmesan fondus en une sauce soyeuse, dans leur version romaine d''origine.', 5, 12, 4, 1, 'gras', '["italien", "pâtes", "rapide", "végétarien", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Râper finement le parmesan et couper le beurre en dés pour qu''il ramollisse.", "Cuire les fettuccine dans une grande casserole d''eau bouillante salée selon le temps du paquet. Garder deux louches d''eau de cuisson avant d''égoutter.", "Dans une grande poêle à feu doux, faire fondre le beurre avec une demi-louche d''eau de cuisson.", "Ajouter les pâtes, puis le parmesan en pluie en remuant sans cesse, avec de l''eau de cuisson petit à petit, jusqu''à obtenir une sauce lisse et brillante qui nappe les pâtes. Poivrer et servir aussitôt."]'::jsonb),
('Pasta alla Norma', 'Des pâtes à la sauce tomate et aux aubergines frites, couronnées de ricotta, la spécialité de Catane.', 20, 35, 4, 2, 'gras', '["italien", "pâtes", "végétarien", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper les aubergines en cubes de 2 cm, les saler et les laisser dégorger 30 min dans une passoire, puis les sécher dans un torchon.", "Chauffer 6 c.à.s d''huile dans une grande poêle et y faire dorer les aubergines en deux fois, 8 à 10 min, jusqu''à ce qu''elles soient fondantes et bien colorées. Les égoutter sur du papier absorbant.", "Dans une sauteuse, chauffer le reste d''huile avec l''ail écrasé 1 min, ajouter les tomates écrasées et quelques feuilles de basilic, saler et mijoter 20 min.", "Cuire les pâtes dans une grande casserole d''eau bouillante salée et les égoutter.", "Mélanger les pâtes à la sauce, puis ajouter les deux tiers des aubergines. Servir avec le reste des aubergines, de la ricotta émiettée et du basilic frais. En Sicile, on utilise de la ricotta salée affinée, râpée."]'::jsonb),
('Rigatoni alla gricia', 'L''ancêtre de la carbonara et de l''amatriciana : guanciale croustillant, pecorino et poivre.', 5, 20, 4, 2, 'gras', '["italien", "pâtes", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper le guanciale en bâtonnets. Le faire fondre à sec dans une grande poêle à feu moyen 8 à 10 min, jusqu''à ce qu''il soit doré et croustillant. Couper le feu en gardant la graisse.", "Cuire les rigatoni dans de l''eau bouillante peu salée (le pecorino et le guanciale le sont), 2 min de moins que le temps indiqué.", "Transférer les pâtes dans la poêle avec deux louches d''eau de cuisson et terminer leur cuisson 2 min à feu vif en remuant : l''amidon lie la graisse et l''eau.", "Hors du feu, ajouter le pecorino râpé et le poivre concassé en remuant vivement, avec un peu d''eau de cuisson si besoin, jusqu''à ce qu''une sauce crémeuse se forme. Servir aussitôt."]'::jsonb),
('Orecchiette aux brocolis', 'Des orecchiette cuites avec des brocolis qui fondent en une sauce verte à l''ail, aux anchois et au piment, façon Pouilles.', 10, 20, 4, 1, 'light', '["italien", "pâtes", "légumes", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Détailler le brocoli en petits bouquets et éplucher puis couper la tige en dés.", "Faire dorer la chapelure à sec dans une poêle 2 à 3 min et la réserver.", "Porter une grande casserole d''eau salée à ébullition. Y cuire le brocoli 5 min, puis ajouter les orecchiette et cuire ensemble selon le temps du paquet.", "Pendant ce temps, dans une grande sauteuse, chauffer l''huile à feu doux avec l''ail haché, les anchois et le piment 3 min, en écrasant les anchois.", "Égoutter pâtes et brocoli en gardant une louche d''eau de cuisson. Les verser dans la sauteuse et remuer 2 min à feu vif en écrasant une partie du brocoli, avec un peu d''eau de cuisson, pour qu''il forme une sauce.", "Servir avec la chapelure dorée et le pecorino râpé. Version végétarienne : sans anchois, avec un peu plus de pecorino."]'::jsonb),
('Farfalle au poulet et aux épinards', 'Des farfalle au poulet doré, épinards et sauce crème à l''ail et au parmesan.', 10, 20, 4, 1, 'protéiné', '["pâtes", "poulet", "famille", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper le poulet en morceaux, saler et poivrer. Le faire dorer dans l''huile 6 à 7 min à feu moyen-vif, jusqu''à ce qu''il soit cuit à cœur (74 °C). Réserver.", "Cuire les farfalle dans une grande casserole d''eau bouillante salée et les égoutter en gardant un peu d''eau de cuisson.", "Dans la même poêle, faire revenir l''ail haché 30 secondes, ajouter la crème et les tomates séchées en lanières, laisser frémir 2 min.", "Ajouter les épinards et remuer jusqu''à ce qu''ils tombent, puis le parmesan râpé.", "Remettre le poulet, ajouter les pâtes et un peu d''eau de cuisson pour lier. Poivrer et servir."]'::jsonb),
('Macaroni and cheese', 'Le classique américain : des macaronis dans une sauce au cheddar, gratinés au four.', 15, 30, 4, 1, 'gras', '["américain", "pâtes", "four", "enfants", "végétarien", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Préchauffer le four à 200 °C. Cuire les macaronis dans de l''eau bouillante salée 2 min de moins que le temps indiqué et les égoutter.", "Dans une casserole, faire fondre 30 g de beurre, ajouter la farine et remuer 1 min. Verser le lait petit à petit en fouettant, puis cuire 5 min en remuant jusqu''à ce que la sauce épaississe.", "Hors du feu, ajouter les trois quarts du cheddar râpé, la moutarde, la muscade, du sel et du poivre, et remuer jusqu''à ce que le fromage fonde.", "Mélanger les pâtes à la sauce et verser dans un plat beurré. Parsemer du reste de cheddar, de l''emmental, de la chapelure et du reste de beurre en petits morceaux.", "Enfourner 15 à 20 min, jusqu''à ce que le dessus soit doré et bouillonnant. Laisser reposer 5 min avant de servir."]'::jsonb),
('Gratin de macaronis au jambon', 'Des macaronis au jambon nappés de béchamel et gratinés à l''emmental.', 15, 35, 4, 1, 'gras', '["français", "pâtes", "four", "famille", "enfants", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Préchauffer le four à 200 °C. Cuire les macaronis dans de l''eau bouillante salée 2 min de moins que le temps indiqué, les égoutter.", "Béchamel : faire fondre le beurre, ajouter la farine et remuer 1 min, puis verser le lait petit à petit en fouettant. Cuire 5 min en remuant jusqu''à épaississement. Saler, poivrer, ajouter la muscade et la moitié de l''emmental.", "Couper le jambon en dés et le mélanger avec les pâtes et la béchamel.", "Verser dans un plat beurré, couvrir du reste d''emmental et enfourner 20 à 25 min, jusqu''à ce que le dessus soit bien gratiné."]'::jsonb),
('Coquillettes au jambon et au fromage', 'Le plat réconfortant des soirs pressés : coquillettes au beurre, dés de jambon et emmental fondu.', 5, 12, 4, 1, 'gras', '["français", "pâtes", "rapide", "enfants", "économique", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Cuire les coquillettes dans une grande casserole d''eau bouillante salée selon le temps du paquet.", "Pendant ce temps, couper le jambon en petits dés.", "Égoutter les pâtes en gardant un fond d''eau de cuisson et les remettre dans la casserole à feu doux.", "Ajouter le beurre, la crème, le jambon et l''emmental, et remuer 1 à 2 min jusqu''à ce que le fromage fonde et fasse des fils. Poivrer et servir aussitôt."]'::jsonb),
('Lasagnes aux épinards et à la ricotta', 'Des lasagnes végétariennes aux épinards, ricotta et sauce tomate, gratinées à la mozzarella.', 30, 45, 6, 2, 'gras', '["italien", "pâtes", "four", "végétarien", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Sauce : faire fondre l''oignon haché dans l''huile 5 min, ajouter l''ail 1 min, puis la passata et quelques feuilles de basilic. Saler et mijoter 15 min.", "Faire tomber les épinards lavés dans une grande poêle 3 min, les laisser tiédir, les presser fortement pour retirer l''eau puis les hacher.", "Mélanger la ricotta avec les épinards, l''œuf, la moitié du parmesan, la muscade, du sel et du poivre.", "Préchauffer le four à 180 °C. Dans un plat, étaler une louche de sauce, puis alterner des couches de feuilles de lasagne, de mélange ricotta-épinards et de sauce, en terminant par une couche de feuilles et de sauce. Si les feuilles demandent une précuisson (voir le paquet), les blanchir 2 min avant.", "Couvrir de mozzarella en tranches et du reste de parmesan. Cuire 40 à 45 min, jusqu''à ce que le dessus soit doré et qu''un couteau traverse les pâtes sans résistance.", "Laisser reposer 10 min avant de couper : les parts se tiennent mieux."]'::jsonb),
('Cannelloni ricotta-épinards', 'Des tubes de pâtes farcis à la ricotta et aux épinards, cuits sous une sauce tomate et une béchamel.', 35, 35, 4, 2, 'gras', '["italien", "pâtes", "four", "végétarien", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Faire tomber les épinards 3 min dans une poêle, les presser pour retirer l''eau et les hacher. Les mélanger avec la ricotta, l''œuf, la moitié du parmesan, la muscade, du sel et du poivre.", "Sauce tomate : chauffer l''huile avec l''ail écrasé 1 min, ajouter la passata, saler et mijoter 10 min.", "Béchamel : faire fondre le beurre, ajouter la farine 1 min, puis le lait en fouettant et cuire 5 min jusqu''à épaississement. Saler et poivrer.", "Préchauffer le four à 190 °C. Remplir les cannelloni crus de farce à l''aide d''une poche ou d''une petite cuillère.", "Étaler la sauce tomate dans un plat, y ranger les cannelloni côte à côte, les napper de béchamel en les couvrant entièrement (les pâtes crues ont besoin d''humidité pour cuire) et parsemer du reste de parmesan.", "Cuire 30 à 35 min, jusqu''à ce que le dessus soit doré et les pâtes tendres."]'::jsonb),
('Conchiglioni farcis', 'De grandes coquilles farcies au bœuf et à la ricotta, gratinées dans une sauce tomate.', 30, 40, 4, 2, 'gras', '["italien", "pâtes", "four", "famille", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Cuire les conchiglioni dans une grande casserole d''eau bouillante salée 3 min de moins que le temps indiqué, les égoutter et les étaler sur un plateau huilé pour qu''ils ne collent pas.", "Faire fondre l''oignon haché dans l''huile 5 min, ajouter l''ail puis la viande et la faire dorer 6 à 8 min en l''émiettant. Ajouter un tiers de la passata, saler, poivrer et cuire 5 min. Laisser tiédir.", "Mélanger la viande avec la ricotta et la moitié du parmesan.", "Préchauffer le four à 190 °C. Étaler le reste de passata assaisonnée dans un plat. Farcir chaque coquille d''une cuillerée de farce et les ranger dans le plat.", "Couvrir de mozzarella en morceaux et du reste de parmesan. Cuire 20 à 25 min, jusqu''à ce que ce soit gratiné. Servir avec du basilic."]'::jsonb),
('Pâtes au thon et à la tomate', 'Un plat de placard rapide : sauce tomate au thon, olives et câpres.', 5, 20, 4, 1, 'protéiné', '["pâtes", "poisson", "rapide", "économique", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire fondre l''oignon haché dans l''huile 5 min, ajouter l''ail 1 min.", "Ajouter les tomates et l''origan, saler légèrement et laisser mijoter 10 min.", "Ajouter le thon égoutté et émietté, les olives et les câpres, et réchauffer 3 min.", "Cuire les pâtes dans une grande casserole d''eau bouillante salée, les égoutter en gardant un peu d''eau de cuisson et les mélanger à la sauce. Poivrer, parsemer de persil et servir."]'::jsonb),
('Pâtes au chorizo et aux poivrons', 'Des pâtes dans une sauce tomate aux poivrons, parfumée par le paprika du chorizo.', 10, 25, 4, 1, 'gras', '["pâtes", "espagnol", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper le chorizo en rondelles puis en quartiers, les poivrons en lanières et émincer l''oignon.", "Faire revenir le chorizo à sec dans une sauteuse 3 min : il rend une huile rouge parfumée. Ajouter l''huile, l''oignon et les poivrons et cuire 8 min à feu moyen.", "Ajouter l''ail haché, puis les tomates, et laisser mijoter 10 min. Ajouter la crème, saler peu et poivrer.", "Cuire les pâtes dans une grande casserole d''eau bouillante salée, les égoutter et les mélanger à la sauce."]'::jsonb),
('One pot pasta tomate-basilic', 'Tout cuit dans la même casserole : les pâtes absorbent un bouillon tomaté qui devient la sauce.', 10, 15, 4, 1, 'light', '["pâtes", "rapide", "végétarien", "économique", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper les tomates cerises en deux, émincer finement l''oignon et l''ail.", "Mettre dans une grande sauteuse les spaghetti crus, les tomates, l''oignon, l''ail, la moitié du basilic, l''huile et le bouillon chaud. Les pâtes doivent être presque couvertes.", "Porter à ébullition et cuire à découvert 10 à 12 min à feu moyen-vif, en remuant souvent avec une pince pour que les pâtes n''attachent pas, jusqu''à ce qu''elles soient cuites et que le liquide ait réduit en sauce.", "Goûter avant de saler (le bouillon l''est). Ajouter le parmesan râpé et le reste de basilic, poivrer et servir."]'::jsonb),
('Pasta e fagioli', 'Une soupe épaisse italienne de petites pâtes et de haricots, réconfortante et économique.', 15, 35, 4, 1, 'protéiné', '["italien", "pâtes", "soupe", "économique", "hiver", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Hacher l''oignon, la carotte, le céleri et l''ail. Les faire suer dans l''huile avec le romarin 8 min à feu moyen.", "Ajouter le concentré de tomate 1 min, puis les haricots rincés et le bouillon. Porter à ébullition et mijoter 15 min.", "Retirer le romarin. Écraser environ un tiers des haricots au presse-purée directement dans la casserole : la soupe devient crémeuse.", "Ajouter les pâtes et cuire selon le temps du paquet en remuant souvent, avec un peu d''eau si la soupe devient trop épaisse.", "Saler, poivrer et servir avec un filet d''huile d''olive et du parmesan râpé."]'::jsonb),
('Minestrone', 'La soupe italienne de légumes et de petites pâtes, épaisse et généreuse.', 20, 40, 6, 1, 'light', '["italien", "pâtes", "soupe", "légumes", "végétarien", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper l''oignon, les carottes, le céleri, la courgette et les pommes de terre en petits dés, les haricots verts en tronçons et émincer le chou.", "Faire suer l''oignon, les carottes et le céleri dans l''huile 8 min, ajouter l''ail 1 min.", "Ajouter les pommes de terre, les tomates et le bouillon, porter à ébullition et cuire 15 min à feu moyen.", "Ajouter la courgette, les haricots verts, le chou et les haricots blancs rincés, cuire 10 min.", "Ajouter les pâtes et cuire selon le temps du paquet. Saler, poivrer et servir avec du parmesan râpé et un filet d''huile d''olive."]'::jsonb),
('Salade de pâtes méditerranéenne', 'Une salade de pâtes fraîche aux tomates, concombre, olives, feta et basilic, idéale pour les pique-niques.', 20, 12, 4, 1, 'light', '["pâtes", "salade", "été", "végétarien", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Cuire les pâtes dans une grande casserole d''eau bouillante salée selon le temps du paquet, les égoutter et les rincer à l''eau froide pour stopper la cuisson. Les mélanger avec 1 c.à.s d''huile.", "Couper les tomates en deux, le concombre et le poivron en dés, émincer très finement l''oignon rouge.", "Vinaigrette : fouetter le reste d''huile avec le vinaigre, l''origan, du sel et du poivre.", "Mélanger les pâtes, les légumes, les olives et la vinaigrette. Ajouter la feta émiettée et le basilic juste avant de servir. Se garde 2 jours au frais."]'::jsonb),
('Pâtes primavera', 'Des pâtes aux légumes de printemps sautés, citron et parmesan.', 15, 15, 4, 1, 'light', '["italien", "pâtes", "légumes", "végétarien", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper les asperges en tronçons (en retirant la base dure), la courgette en demi-rondelles et les tomates en deux.", "Cuire les pâtes dans une grande casserole d''eau bouillante salée. 3 min avant la fin, ajouter les petits pois. Égoutter en gardant un peu d''eau de cuisson.", "Pendant ce temps, faire sauter les asperges et la courgette dans l''huile 5 min à feu vif, ajouter l''ail haché et les tomates 2 min.", "Ajouter les pâtes, les petits pois, le beurre, le zeste et un peu de jus de citron, le parmesan râpé et un peu d''eau de cuisson. Remuer jusqu''à ce que tout soit lié, poivrer et servir avec du basilic."]'::jsonb),
('Pâtes aux quatre fromages', 'Des pâtes nappées d''une sauce fondante au gorgonzola, à l''emmental, à la mozzarella et au parmesan.', 5, 15, 4, 1, 'gras', '["italien", "pâtes", "rapide", "végétarien", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Cuire les pâtes dans une grande casserole d''eau bouillante salée et les égoutter en gardant un peu d''eau de cuisson.", "Pendant ce temps, chauffer la crème à feu doux dans une grande casserole, y faire fondre le gorgonzola en morceaux, puis l''emmental râpé en remuant.", "Ajouter la mozzarella coupée en dés et la moitié du parmesan, remuer jusqu''à ce que la sauce soit lisse. Poivrer et ajouter la muscade.", "Mélanger les pâtes à la sauce avec un peu d''eau de cuisson. Servir avec le reste de parmesan."]'::jsonb),
('Pâtes au gorgonzola et aux noix', 'Une sauce crémeuse au gorgonzola relevée de noix grillées.', 5, 15, 4, 1, 'gras', '["italien", "pâtes", "rapide", "végétarien", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire griller les noix à sec dans une poêle 3 min, puis les concasser grossièrement.", "Cuire les pâtes dans une grande casserole d''eau bouillante salée et les égoutter en gardant un peu d''eau de cuisson.", "Dans une casserole, faire fondre à feu doux le gorgonzola dans la crème avec le beurre, en remuant, sans faire bouillir.", "Mélanger les pâtes avec la sauce et un peu d''eau de cuisson, poivrer et servir parsemé de noix."]'::jsonb),
('Linguine aux fruits de mer', 'Des linguine aux moules, crevettes et calamars dans une sauce tomate légère à l''ail et au vin blanc.', 25, 20, 4, 2, 'protéiné', '["italien", "pâtes", "fruits de mer", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Gratter et rincer les moules en jetant celles qui sont cassées. Décortiquer les crevettes en gardant la queue et couper les calamars en anneaux.", "Dans une sauteuse, chauffer 2 c.à.s d''huile avec 1 gousse d''ail écrasée, ajouter les moules et le vin, couvrir et cuire 3 à 4 min jusqu''à ce qu''elles s''ouvrent. Les retirer, filtrer et garder le jus. Jeter celles restées fermées.", "Cuire les linguine dans une grande casserole d''eau bouillante salée, 2 min de moins que le temps indiqué.", "Dans la sauteuse, chauffer le reste d''huile avec le reste d''ail haché et le piment 1 min, ajouter les tomates coupées en deux 3 min, puis les calamars et les crevettes 2 à 3 min, jusqu''à ce que les crevettes soient roses.", "Ajouter les pâtes égouttées et le jus des moules, finir la cuisson 2 min à feu vif en remuant. Remettre les moules, parsemer de persil et servir aussitôt."]'::jsonb),
('Linguine al limone', 'Des linguine au citron, beurre et parmesan : frais, simple et prêt en 15 minutes.', 5, 12, 4, 1, 'gras', '["italien", "pâtes", "rapide", "végétarien", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Prélever le zeste des citrons (sans la partie blanche, amère) et presser le jus d''un citron.", "Cuire les linguine dans une grande casserole d''eau bouillante salée, les égoutter en gardant une louche d''eau de cuisson.", "Dans une grande poêle à feu doux, faire fondre le beurre avec la crème et le zeste.", "Ajouter les pâtes, le parmesan râpé, 2 c.à.s de jus de citron et un peu d''eau de cuisson, et remuer jusqu''à ce que la sauce enrobe les pâtes. Goûter, ajouter du jus de citron si besoin, poivrer et servir."]'::jsonb),
('Pastitsio', 'Le gratin grec de pâtes à la viande épicée à la cannelle, sous une épaisse béchamel.', 30, 50, 6, 2, 'gras', '["grec", "pâtes", "four", "famille", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Sauce à la viande : faire fondre l''oignon haché dans l''huile 5 min, ajouter l''ail puis la viande et la faire dorer en l''émiettant. Ajouter le concentré, le vin, les tomates, la cannelle, du sel et du poivre, et mijoter 20 min jusqu''à ce que la sauce soit épaisse.", "Cuire les pâtes 2 min de moins que le temps indiqué, les égoutter et les mélanger avec un tiers du parmesan.", "Béchamel : faire fondre le beurre, ajouter la farine 1 min, verser le lait en fouettant et cuire 5 à 6 min jusqu''à ce qu''elle soit épaisse. Hors du feu, ajouter la muscade, un tiers du parmesan, puis les œufs battus en fouettant vivement.", "Préchauffer le four à 180 °C. Dans un plat beurré, étaler la moitié des pâtes, puis toute la sauce à la viande, puis le reste des pâtes. Couvrir de béchamel et du reste de parmesan.", "Cuire 40 à 45 min, jusqu''à ce que le dessus soit bien doré. Laisser reposer 15 min avant de couper des parts nettes."]'::jsonb),
('Pad thaï aux crevettes', 'Les nouilles de riz sautées thaïlandaises à l''œuf, aux crevettes, aux cacahuètes et au citron vert.', 25, 10, 2, 2, 'protéiné', '["thaï", "asiatique", "pâtes", "fruits de mer", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire tremper les nouilles 20 à 30 min dans de l''eau tiède : elles doivent être souples mais encore fermes, elles finiront de cuire dans le wok. Les égoutter.", "Sauce : mélanger la pâte de tamarin, la sauce nuoc-mâm, le sucre et 2 c.à.s d''eau jusqu''à ce que le sucre fonde.", "Chauffer 2 c.à.s d''huile dans un wok à feu vif, sauter l''ail et l''échalote hachés 30 secondes, puis les crevettes 2 min jusqu''à ce qu''elles rosissent.", "Pousser le tout sur le côté, casser les œufs dans le wok et les brouiller 30 secondes.", "Ajouter les nouilles, le reste d''huile et la sauce, et sauter 2 à 3 min en remuant sans cesse, jusqu''à ce que les nouilles soient tendres et aient absorbé la sauce. Ajouter un peu d''eau si elles attachent.", "Ajouter les pousses de soja et les oignons nouveaux 30 secondes. Servir avec les cacahuètes concassées, la coriandre, le piment et des quartiers de citron vert."]'::jsonb),
('Nouilles sautées au poulet', 'Des nouilles aux œufs sautées au wok avec poulet et légumes, dans une sauce soja-huître.', 20, 12, 2, 1, 'protéiné', '["chinois", "asiatique", "pâtes", "poulet", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper le poulet en fines lamelles et le mélanger avec la fécule et 1 c.à.s de sauce soja.", "Cuire les nouilles selon le paquet (souvent 3 à 4 min), les égoutter, les rincer à l''eau froide et les mélanger avec quelques gouttes d''huile.", "Mélanger le reste de sauce soja, la sauce d''huître, le sucre et 2 c.à.s d''eau.", "Chauffer l''huile dans un wok à feu vif, saisir le poulet 3 à 4 min jusqu''à ce qu''il soit cuit à cœur. Réserver.", "Sauter l''ail, le gingembre et la carotte en julienne 2 min, puis le chou émincé 2 min.", "Ajouter les nouilles, le poulet et la sauce, et sauter 2 min à feu vif jusqu''à ce que tout soit enrobé. Ajouter les oignons nouveaux et l''huile de sésame, servir."]'::jsonb),
('Yakisoba', 'Les nouilles sautées japonaises au porc et au chou, laquées d''une sauce sucrée-salée.', 15, 12, 2, 1, 'gras', '["japonais", "asiatique", "pâtes", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Sauce : mélanger la sauce Worcestershire, le ketchup, la sauce soja, la sauce d''huître et le sucre.", "Cuire les nouilles selon le paquet, les égoutter et les rincer à l''eau froide.", "Couper la poitrine de porc en fines lamelles, le chou en carrés, la carotte en julienne et l''oignon en lamelles.", "Dans une grande poêle ou un wok à feu vif, faire dorer le porc dans l''huile 3 min. Ajouter l''oignon et la carotte 2 min, puis le chou 2 min : il doit rester un peu croquant.", "Ajouter les nouilles et la sauce, sauter 2 à 3 min jusqu''à ce qu''elles soient bien enrobées et légèrement grillées par endroits. Servir avec le gingembre mariné."]'::jsonb),
('Nouilles udon sautées au bœuf', 'D''épaisses nouilles udon sautées au bœuf, aux champignons et aux oignons nouveaux.', 15, 10, 2, 1, 'protéiné', '["japonais", "asiatique", "pâtes", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Plonger les udon 1 à 2 min dans l''eau bouillante pour les détacher (ou selon le paquet), puis les égoutter.", "Mélanger la sauce soja, le mirin et le sucre.", "Chauffer l''huile dans un wok à feu vif et saisir le bœuf 1 à 2 min. Le réserver.", "Sauter les champignons émincés et l''ail 2 min, puis le blanc des oignons nouveaux.", "Ajouter les udon, le bœuf et la sauce, sauter 2 min jusqu''à ce que les nouilles soient brillantes. Servir avec le vert des oignons et le sésame."]'::jsonb),
('Soupe de nouilles au poulet', 'Un bouillon de poulet aux légumes et aux vermicelles, doux et réconfortant.', 15, 40, 4, 1, 'light', '["pâtes", "soupe", "poulet", "hiver", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper les carottes en rondelles, le céleri et l''oignon en petits dés.", "Faire suer les légumes dans l''huile 5 min dans une grande casserole, ajouter l''ail 1 min.", "Ajouter les cuisses de poulet, le bouillon, le thym et le laurier. Porter à frémissement et cuire 30 min à couvert, jusqu''à ce que le poulet se détache de l''os.", "Retirer le poulet, l''effilocher en jetant la peau et les os, puis le remettre dans la soupe.", "Ajouter les vermicelles et cuire 3 à 5 min selon le paquet. Retirer le thym et le laurier, saler, poivrer et servir avec le persil."]'::jsonb),
('Gnocchis à la sorrentina', 'Des gnocchis gratinés au four dans une sauce tomate au basilic, avec de la mozzarella fondante.', 10, 25, 4, 1, 'gras', '["italien", "four", "végétarien", "famille", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Préchauffer le four à 220 °C (position gril si possible en fin de cuisson).", "Chauffer l''huile avec l''ail écrasé 1 min, ajouter la passata et quelques feuilles de basilic, saler et mijoter 10 min.", "Cuire les gnocchis dans une grande casserole d''eau bouillante salée : ils sont prêts dès qu''ils remontent à la surface (1 à 2 min). Les égoutter avec une écumoire.", "Mélanger les gnocchis à la sauce, verser dans un plat, couvrir de mozzarella en morceaux et de parmesan râpé.", "Enfourner 10 à 12 min, jusqu''à ce que la mozzarella soit fondue et dorée par endroits. Servir avec du basilic frais."]'::jsonb),
('Tortellini à la crème et au jambon', 'Des tortellini frais dans une crème au jambon et aux petits pois, prêts en 10 minutes.', 5, 10, 4, 1, 'gras', '["italien", "pâtes", "rapide", "enfants", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper le jambon en lanières.", "Cuire les tortellini et les petits pois ensemble dans une grande casserole d''eau bouillante salée selon le temps du paquet (2 à 4 min pour des pâtes fraîches).", "Pendant ce temps, faire fondre le beurre dans une poêle, ajouter le jambon 1 min, puis la crème et la muscade, et laisser frémir 2 min.", "Égoutter les tortellini et les petits pois, les mélanger à la sauce avec le parmesan râpé. Poivrer et servir."]'::jsonb),
('Lasagnes au saumon et aux épinards', 'Des lasagnes au saumon, épinards et béchamel légèrement citronnée.', 30, 40, 6, 2, 'gras', '["pâtes", "poisson", "four", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Retirer la peau du saumon et le couper en cubes. Faire tomber les épinards 3 min à la poêle et bien les presser pour retirer l''eau.", "Béchamel : faire fondre le beurre, ajouter la farine 1 min, verser le lait en fouettant et cuire 5 à 6 min jusqu''à épaississement. Ajouter le zeste du citron, la muscade, l''aneth, du sel et du poivre.", "Préchauffer le four à 180 °C. Dans un plat, étaler un peu de béchamel, puis alterner feuilles de lasagne, saumon, épinards et béchamel, en terminant par des feuilles et une bonne couche de béchamel.", "Parsemer d''emmental et cuire 35 à 40 min, jusqu''à ce que le dessus soit doré et les pâtes tendres. Laisser reposer 10 min avant de servir."]'::jsonb),
('Bolognaise végétarienne aux lentilles', 'Une sauce bolognaise sans viande aux lentilles et aux légumes, riche en protéines.', 15, 40, 4, 1, 'protéiné', '["italien", "pâtes", "végan", "économique", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Rincer les lentilles. Hacher finement l''oignon, la carotte, le céleri, l''ail et les champignons.", "Faire suer les légumes dans l''huile 10 min à feu moyen, jusqu''à ce que les champignons aient rendu leur eau et commencent à dorer.", "Ajouter le concentré de tomate 1 min, puis les lentilles, les tomates, le bouillon, l''origan et la sauce soja (elle apporte du goût à la place de la viande).", "Couvrir et mijoter 30 à 35 min, jusqu''à ce que les lentilles soient tendres, en ajoutant un peu d''eau si besoin. Saler et poivrer.", "Cuire les spaghetti dans une grande casserole d''eau bouillante salée, les égoutter et servir avec la sauce."]'::jsonb),
('Pâtes à la courgette, citron et feta', 'Des pâtes aux courgettes fondantes, relevées de citron, de menthe et de feta.', 10, 15, 4, 1, 'light', '["pâtes", "légumes", "été", "végétarien", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Râper les courgettes à gros trous ou les couper en fines demi-rondelles.", "Cuire les pâtes dans une grande casserole d''eau bouillante salée et les égoutter en gardant un peu d''eau de cuisson.", "Pendant ce temps, faire revenir les courgettes dans l''huile avec l''ail haché et le piment 8 à 10 min à feu moyen, jusqu''à ce qu''elles soient fondantes et légèrement dorées. Saler.", "Ajouter les pâtes, le zeste et le jus du citron et un peu d''eau de cuisson, bien mélanger. Servir avec la feta émiettée, la menthe ciselée et du poivre."]'::jsonb),
('Steak frites sauce au poivre', 'Un steak saisi, nappé d''une sauce crémeuse au poivre et au cognac, avec des frites maison.', 20, 35, 2, 2, 'gras', '["français", "viande", "bistrot", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Sortir les steaks du réfrigérateur 30 min avant. Éplucher les pommes de terre, les couper en bâtonnets de 1 cm, les rincer et les sécher soigneusement.", "Première cuisson des frites : 6 à 7 min dans l''huile à 150 °C, elles doivent être cuites mais pâles. Les égoutter.", "Concasser grossièrement le poivre. Saler les steaks, les presser sur une face dans le poivre.", "Chauffer une poêle très chaude avec un filet d''huile et saisir les steaks 2 à 3 min par face pour une cuisson saignante (52 °C à cœur), 3 à 4 min pour à point (57 °C). Les laisser reposer sous une feuille d''aluminium.", "Dans la même poêle à feu moyen, faire fondre le beurre et l''échalote hachée 1 min. Verser le cognac (hors de la flamme) et gratter le fond, puis ajouter le fond de veau délayé dans 50 ml d''eau et la crème. Laisser réduire 3 min jusqu''à ce que la sauce nappe la cuillère.", "Seconde cuisson des frites : 2 à 3 min dans l''huile à 180 °C jusqu''à ce qu''elles soient dorées et croustillantes. Saler et servir avec les steaks nappés de sauce."]'::jsonb),
('Bœuf Stroganoff', 'De fines lanières de bœuf et des champignons dans une sauce à la crème aigre et au paprika.', 15, 20, 4, 2, 'gras', '["russe", "viande", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper la viande en lanières de 1 cm d''épaisseur dans le sens contraire des fibres. Émincer l''oignon et les champignons.", "Cuire le riz selon le paquet.", "Dans une grande poêle très chaude, saisir la viande en deux fois dans l''huile 1 à 2 min : elle doit dorer mais rester rosée. La réserver avec son jus.", "Dans la poêle, faire fondre le beurre, ajouter l''oignon 4 min, puis les champignons 5 min jusqu''à ce qu''ils dorent. Ajouter le paprika et la farine et remuer 1 min.", "Verser le bouillon et la moutarde, laisser épaissir 2 min, puis ajouter la crème hors ébullition.", "Remettre la viande et son jus juste pour la réchauffer 1 min (au-delà elle durcit). Saler, poivrer, parsemer de persil et servir avec le riz."]'::jsonb),
('Carbonade flamande', 'Du bœuf mijoté dans la bière brune avec des oignons, du pain d''épices et de la moutarde.', 25, 180, 6, 2, 'gras', '["belge", "viande", "mijoté", "hiver", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper la viande en gros cubes de 5 cm et la sécher avec du papier absorbant. Émincer les oignons.", "Dans une cocotte, faire dorer la viande en plusieurs fois dans la moitié du beurre à feu vif, 5 min par fournée. Saler, poivrer et réserver.", "Faire fondre les oignons dans le reste du beurre 10 à 15 min à feu moyen, jusqu''à ce qu''ils soient bien dorés. Ajouter la farine et remuer 1 min.", "Remettre la viande, verser la bière, ajouter la cassonade, le vinaigre, le thym et le laurier.", "Tartiner les tranches de pain d''épices de moutarde et les poser sur le dessus, face moutarde vers le bas.", "Couvrir et laisser mijoter 2h30 à 3h à feu très doux, en remuant de temps en temps : le pain d''épices fond et épaissit la sauce, la viande doit se défaire à la fourchette. Servir avec des frites ou des pommes vapeur."]'::jsonb),
('Hachis parmentier', 'Du bœuf haché mijoté aux oignons sous une purée maison dorée au four.', 25, 45, 6, 1, 'gras', '["français", "viande", "four", "famille", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Éplucher les pommes de terre, les couper en morceaux et les cuire 20 à 25 min dans de l''eau froide salée portée à ébullition, jusqu''à ce qu''un couteau les traverse sans résistance.", "Pendant ce temps, faire fondre les oignons hachés dans l''huile 8 min, ajouter l''ail puis la viande et la faire dorer 8 min en l''émiettant. Ajouter le concentré de tomate et le persil, saler et poivrer.", "Égoutter les pommes de terre et les écraser au presse-purée avec le beurre et le lait chaud. Saler, poivrer, ajouter la muscade.", "Préchauffer le four à 200 °C. Étaler la viande dans un plat, couvrir de purée, lisser à la fourchette et parsemer d''emmental.", "Enfourner 20 min, jusqu''à ce que le dessus soit bien doré."]'::jsonb),
('Bœuf aux oignons', 'Un sauté de bœuf à la chinoise, tendre et laqué, avec des oignons fondants.', 15, 10, 3, 1, 'protéiné', '["chinois", "asiatique", "viande", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper le bœuf en fines lamelles contre les fibres et le mélanger avec 1 c.à.s de sauce soja et la fécule. Laisser reposer 10 min.", "Cuire le riz selon le paquet.", "Mélanger le reste de sauce soja, la sauce d''huître, le sucre et 3 c.à.s d''eau.", "Chauffer l''huile dans un wok à feu très vif et saisir le bœuf en une seule couche 1 min, puis le retourner 30 secondes. Le réserver.", "Sauter les oignons coupés en lamelles 3 min, ajouter l''ail et le gingembre 30 secondes.", "Remettre le bœuf, verser la sauce et remuer 1 min jusqu''à ce qu''elle nappe. Parsemer d''oignons nouveaux et servir avec le riz."]'::jsonb),
('Tartare de bœuf', 'Du bœuf cru haché au couteau, assaisonné de câpres, cornichons, échalote et jaune d''œuf.', 20, 0, 2, 2, 'protéiné', '["français", "viande", "sans cuisson", "bistrot", "plat"]'::jsonb, 'public', '[]'::jsonb, '["Utiliser une viande très fraîche achetée le jour même, et des œufs extra-frais. Le tartare est déconseillé aux femmes enceintes, aux jeunes enfants et aux personnes fragiles.", "Garder la viande au réfrigérateur jusqu''au dernier moment. La couper en petits dés de 3 à 4 mm au couteau bien aiguisé (on peut aussi demander au boucher de la hacher).", "Hacher finement l''échalote, les cornichons, les câpres et le persil.", "Dans un saladier froid, mélanger la moutarde, le ketchup, la sauce Worcestershire, la sauce piquante et l''huile, puis la viande et les condiments. Saler et poivrer.", "Dresser en deux galettes à l''aide d''un emporte-pièce, creuser un petit puits et y déposer un jaune d''œuf. Servir aussitôt, avec des frites ou une salade."]'::jsonb),
('Rôti de bœuf au four', 'Un rôti saisi puis cuit au four, rosé à cœur, avec son jus.', 10, 40, 6, 2, 'protéiné', '["français", "viande", "four", "famille", "plat"]'::jsonb, 'public', '["oven"]'::jsonb, '["Sortir le rôti du réfrigérateur 1h avant pour qu''il cuise uniformément. Préchauffer le four à 220 °C.", "Frotter le rôti d''huile, saler et poivrer. Le saisir sur toutes les faces dans une cocotte ou un plat allant sur le feu, 1 à 2 min par face.", "Ajouter le beurre, l''ail en chemise et le thym, et enfourner. Compter environ 15 min par 500 g pour une cuisson saignante (52 °C à cœur), 18 min pour rosée (57 °C). Arroser deux fois pendant la cuisson.", "Sortir le rôti, l''envelopper de papier aluminium et le laisser reposer 15 min : les jus se répartissent et la viande reste juteuse.", "Déglacer le plat avec 100 ml d''eau chaude en grattant les sucs pour faire le jus. Trancher le rôti finement et servir avec le jus."]'::jsonb),
('Daube provençale', 'Du bœuf mariné puis mijoté au vin rouge avec des olives, de l''orange et des herbes de Provence.', 30, 210, 6, 2, 'gras', '["provençal", "français", "viande", "mijoté", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["La veille, mettre la viande en cubes dans un saladier avec le vin, un oignon émincé, les carottes en rondelles, l''ail écrasé, un zeste d''orange, le bouquet garni et les clous de girofle. Couvrir et laisser mariner 12 à 24h au réfrigérateur.", "Égoutter la viande en gardant la marinade et les légumes. Sécher les morceaux avec du papier absorbant.", "Dans une cocotte, faire dorer les lardons dans l''huile, puis la viande en plusieurs fois à feu vif. Ajouter le second oignon émincé et les légumes de la marinade 5 min.", "Saupoudrer de farine et remuer 1 min, puis verser la marinade et les tomates. Porter à ébullition en grattant le fond.", "Couvrir et laisser mijoter 3h à feu très doux (ou au four à 150 °C), jusqu''à ce que la viande soit fondante.", "Ajouter les olives 15 min avant la fin. Retirer le bouquet garni, rectifier l''assaisonnement et servir avec des pâtes ou des pommes de terre. Encore meilleure réchauffée le lendemain."]'::jsonb),
('Bœuf lok lak', 'Des dés de bœuf sautés et laqués à la cambodgienne, servis avec une sauce au citron vert et au poivre.', 20, 10, 4, 1, 'protéiné', '["cambodgien", "asiatique", "viande", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper le bœuf en cubes de 2 cm. Le faire mariner 15 min avec la sauce soja, la sauce d''huître, le sucre et l''ail haché.", "Cuire le riz selon le paquet.", "Sauce : mélanger le jus des citrons verts avec le poivre concassé et une pincée de sel.", "Dresser des feuilles de laitue, des rondelles de tomate et d''oignon rouge sur les assiettes.", "Chauffer l''huile dans un wok à feu très vif et saisir le bœuf en deux fois 2 à 3 min, jusqu''à ce qu''il soit caramélisé dehors et rosé dedans.", "Servir le bœuf sur la salade avec le riz et la sauce au citron vert à part, pour y tremper chaque bouchée."]'::jsonb),
('Goulash hongrois', 'Un ragoût de bœuf aux oignons et au paprika, avec poivrons et pommes de terre.', 25, 150, 6, 2, 'gras', '["hongrois", "viande", "mijoté", "hiver", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper la viande en cubes de 4 cm, émincer les oignons.", "Dans une cocotte, faire dorer la viande en plusieurs fois dans l''huile. Réserver.", "Faire fondre les oignons 10 min à feu moyen jusqu''à ce qu''ils soient dorés, ajouter l''ail et le cumin 1 min.", "Hors du feu, ajouter les paprikas (le paprika brûle et devient amer à feu trop vif), puis le concentré de tomate. Remettre la viande, verser le bouillon, saler et poivrer.", "Couvrir et mijoter 1h30 à feu doux.", "Ajouter les poivrons en lanières et les pommes de terre en cubes, cuire encore 40 min à découvert, jusqu''à ce que les pommes de terre soient tendres et la sauce épaissie. Servir avec une cuillerée de crème fraîche."]'::jsonb),
('Bavette à l''échalote', 'Une bavette saisie, nappée d''échalotes fondues au vin rouge, le classique des bistrots.', 10, 15, 2, 1, 'protéiné', '["français", "viande", "bistrot", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Sortir la viande 30 min avant. Émincer finement les échalotes.", "Chauffer l''huile dans une poêle très chaude et saisir les bavettes 2 min par face pour une cuisson saignante : la bavette devient dure si elle est trop cuite. Saler, poivrer et laisser reposer sous une feuille d''aluminium.", "Dans la même poêle à feu moyen, faire fondre les échalotes dans 20 g de beurre 3 à 4 min.", "Verser le vin et le vinaigre, gratter le fond et laisser réduire presque à sec. Hors du feu, ajouter le reste du beurre en remuant.", "Trancher les bavettes contre les fibres, napper d''échalotes, parsemer de persil et servir avec des frites."]'::jsonb),
('Keftas de bœuf à la marocaine', 'Des brochettes de viande hachée aux herbes et au cumin, grillées, avec une sauce yaourt.', 20, 10, 4, 1, 'protéiné', '["marocain", "viande", "grillade", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Râper l''oignon et le presser pour retirer son jus. Hacher finement le persil et la coriandre.", "Mélanger la viande avec l''oignon, les herbes, les épices et le sel. Pétrir 1 à 2 min pour que la farce se tienne, puis réfrigérer 30 min.", "Former des boudins allongés autour de brochettes (en bois trempées 30 min dans l''eau), ou des petites saucisses.", "Sauce : mélanger le yaourt, la menthe ciselée, le jus du demi-citron et une pincée de sel.", "Cuire les keftas sur une plancha ou une poêle-gril huilée très chaude 8 à 10 min en les retournant, jusqu''à ce qu''elles soient cuites à cœur (70 °C). Servir avec les pitas et la sauce."]'::jsonb),
('Escalopes de veau à la normande', 'Des escalopes de veau dorées, nappées d''une sauce crème aux champignons et au cidre.', 10, 20, 4, 1, 'gras', '["français", "viande", "normand", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Aplatir légèrement les escalopes, les saler, les poivrer et les fariner légèrement en tapotant l''excédent.", "Chauffer l''huile et la moitié du beurre dans une grande poêle et dorer les escalopes 2 min par face à feu vif. Les réserver au chaud.", "Dans la même poêle, faire revenir l''échalote hachée et les champignons émincés dans le reste du beurre 5 min.", "Verser le cidre, gratter le fond et laisser réduire de moitié, puis ajouter la crème et laisser épaissir 3 min.", "Remettre les escalopes et leur jus 1 min dans la sauce, parsemer de persil et servir avec du riz ou des tagliatelles."]'::jsonb),
('Osso buco à la milanaise', 'Des jarrets de veau braisés au vin blanc et à la tomate, parfumés d''une gremolata au citron.', 25, 120, 4, 2, 'gras', '["italien", "viande", "mijoté", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Entailler la membrane autour des tranches de jarret à 2 ou 3 endroits pour qu''elles ne se recroquevillent pas. Saler, poivrer et fariner.", "Dans une cocotte, dorer la viande dans l''huile 4 min par face. La réserver.", "Ajouter le beurre, l''oignon, la carotte et le céleri en petits dés et 2 gousses d''ail hachées, faire suer 8 min.", "Verser le vin et laisser réduire de moitié en grattant le fond, puis ajouter les tomates et le bouillon. Remettre la viande en une seule couche.", "Couvrir et laisser mijoter 1h30 à 2h à feu très doux, en retournant la viande à mi-cuisson, jusqu''à ce qu''elle se détache de l''os.", "Gremolata : hacher ensemble le zeste du citron, le persil et la dernière gousse d''ail. En parsemer l''osso buco au moment de servir, avec un risotto au safran ou des pâtes."]'::jsonb),
('Veau Marengo', 'Un sauté de veau mijoté à la tomate, au vin blanc et aux champignons.', 20, 90, 6, 2, 'protéiné', '["français", "viande", "mijoté", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire dorer la viande en plusieurs fois dans 2 c.à.s d''huile dans une cocotte. Réserver.", "Faire fondre les oignons émincés 5 min, ajouter l''ail, puis la farine et remuer 1 min.", "Remettre la viande, verser le vin, ajouter les tomates, le concentré, le bouquet garni, du sel et du poivre. Compléter avec un peu d''eau pour presque couvrir la viande.", "Couvrir et mijoter 1h15 à feu doux.", "Faire dorer les champignons émincés dans le reste d''huile 5 min et les ajouter à la cocotte. Poursuivre 15 min à découvert pour épaissir la sauce.", "Retirer le bouquet garni, parsemer de persil et servir avec du riz ou des pâtes."]'::jsonb),
('Paupiettes de veau', 'Des paupiettes dorées puis mijotées avec carottes, champignons et vin blanc.', 15, 50, 4, 1, 'gras', '["français", "viande", "mijoté", "famille", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Dans une cocotte, dorer les paupiettes dans le beurre et l''huile 6 à 8 min sur toutes les faces. Les réserver.", "Faire fondre l''oignon émincé 3 min, ajouter les carottes en rondelles et les champignons en quartiers 3 min.", "Verser le vin, gratter le fond, puis ajouter le bouillon, le thym et le laurier. Remettre les paupiettes.", "Couvrir et mijoter 40 min à feu doux, en les retournant à mi-cuisson.", "Retirer les ficelles, ajouter la crème à la sauce, saler, poivrer et servir avec de la purée ou du riz."]'::jsonb),
('Saltimbocca alla romana', 'De fines escalopes de veau au jambon cru et à la sauge, poêlées et déglacées au vin blanc.', 10, 10, 4, 1, 'protéiné', '["italien", "viande", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper le veau en 8 petites escalopes et les aplatir finement entre deux feuilles de papier cuisson. Poser sur chacune une tranche de jambon et une feuille de sauge, et les fixer avec un cure-dent.", "Fariner légèrement le côté sans jambon. Poivrer (pas de sel : le jambon est salé).", "Chauffer l''huile et la moitié du beurre dans une grande poêle et cuire les saltimbocca 2 min côté jambon, puis 1 à 2 min de l''autre côté. Les réserver au chaud.", "Verser le vin dans la poêle, gratter le fond et laisser réduire 1 min, puis ajouter le reste du beurre hors du feu. Napper les saltimbocca et servir aussitôt."]'::jsonb),
('Rôti de veau aux carottes', 'Un rôti de veau cocotte, fondant, cuit doucement avec des carottes et des oignons.', 15, 80, 6, 1, 'protéiné', '["français", "viande", "famille", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Saler et poivrer le rôti. Le faire dorer sur toutes les faces dans le beurre et l''huile dans une cocotte, 8 à 10 min.", "Ajouter les oignons coupés en quartiers, les carottes en rondelles épaisses, l''ail en chemise, le thym et le laurier. Verser le vin et 100 ml d''eau.", "Couvrir et cuire 1h10 à feu doux, en retournant le rôti et en arrosant toutes les 20 min. Le veau est cuit à 65-68 °C à cœur : il reste rosé et juteux.", "Laisser reposer le rôti 10 min sous une feuille d''aluminium, le trancher et servir avec les carottes et le jus."]'::jsonb),
('Tendrons de veau aux petits pois', 'Des tendrons de veau mijotés jusqu''à être fondants, avec des petits pois et des carottes.', 15, 90, 4, 1, 'gras', '["français", "viande", "mijoté", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire dorer les tendrons dans l''huile et le beurre dans une cocotte, 3 min par face. Saler, poivrer et réserver.", "Faire fondre les oignons émincés 5 min, ajouter les carottes en rondelles, puis la farine et remuer 1 min.", "Remettre la viande, verser le vin et le bouillon, ajouter le bouquet garni. Couvrir et mijoter 1h15 à feu doux.", "Ajouter les petits pois et poursuivre 15 min. Retirer le bouquet garni et servir."]'::jsonb),
('Foie de veau à la vénitienne', 'De fines tranches de foie de veau saisies avec des oignons fondants et un trait de vinaigre.', 15, 25, 4, 2, 'protéiné', '["italien", "viande", "abats", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Émincer très finement les oignons. Les faire fondre dans l''huile et la moitié du beurre 20 min à feu doux, à couvert les 10 premières minutes, jusqu''à ce qu''ils soient tendres et dorés. Saler.", "Couper le foie en lanières de 1 cm.", "Pousser les oignons, monter le feu, ajouter le reste du beurre et saisir le foie 1 à 2 min en remuant : il doit rester rosé à l''intérieur, sinon il devient caoutchouteux.", "Ajouter le vinaigre, mélanger avec les oignons 30 secondes, saler, poivrer et parsemer de persil. Servir aussitôt, avec de la polenta ou de la purée."]'::jsonb),
('Rôti de porc au four', 'Un rôti de porc doré au four avec ail, thym et pommes de terre fondantes.', 15, 75, 6, 1, 'protéiné', '["français", "viande", "four", "famille", "plat"]'::jsonb, 'public', '["oven"]'::jsonb, '["Sortir le rôti 30 min avant. Préchauffer le four à 190 °C.", "Badigeonner le rôti de moutarde, saler et poivrer. Le saisir dans un plat allant sur le feu avec 1 c.à.s d''huile, 2 min par face.", "Éplucher les pommes de terre, les couper en quartiers, couper les oignons en quartiers. Les mélanger avec le reste d''huile, l''ail en chemise, le thym et du sel, et les disposer autour du rôti.", "Enfourner 1h à 1h15 (environ 30 min par 500 g), en arrosant et en remuant les pommes de terre toutes les 20 min. Le porc est cuit à 68-70 °C à cœur : il reste juteux.", "Laisser reposer 10 min sous une feuille d''aluminium avant de trancher. Servir avec les pommes de terre et le jus du plat."]'::jsonb),
('Filet mignon de porc à la moutarde', 'Un filet mignon doré, en médaillons, dans une sauce crème à la moutarde à l''ancienne.', 10, 25, 4, 1, 'gras', '["français", "viande", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Retirer la fine membrane blanche du filet mignon et le couper en médaillons de 2 cm. Saler et poivrer.", "Dorer les médaillons dans le beurre et l''huile à feu vif, 2 à 3 min par face. Les réserver.", "Faire fondre l''échalote hachée 1 min, verser le vin et gratter le fond, laisser réduire de moitié.", "Ajouter la crème et les moutardes, laisser épaissir 3 min à feu doux.", "Remettre les médaillons et leur jus 3 à 4 min dans la sauce, jusqu''à ce qu''ils soient cuits à cœur (65 °C, légèrement rosés). Servir avec des tagliatelles ou du riz."]'::jsonb),
('Travers de porc caramélisés', 'Des travers de porc marinés au miel et à la sauce soja, cuits doucement au four jusqu''à être laqués.', 15, 105, 4, 1, 'gras', '["viande", "four", "barbecue", "famille", "plat"]'::jsonb, 'public', '["oven"]'::jsonb, '["Mélanger le miel, la sauce soja, le ketchup, l''ail et le gingembre râpés, le paprika, le vinaigre et du poivre.", "Couper les travers en portions de 3 ou 4 os, les enrober de la moitié de la marinade et laisser mariner au moins 1h au réfrigérateur (idéalement une nuit).", "Préchauffer le four à 160 °C. Disposer les travers dans un plat, verser 100 ml d''eau au fond, couvrir de papier aluminium et cuire 1h15 : la viande devient tendre.", "Retirer l''aluminium, monter le four à 200 °C, badigeonner du reste de marinade et cuire encore 20 à 30 min en badigeonnant deux fois, jusqu''à ce que les travers soient laqués et caramélisés. Surveiller la fin : le miel brûle vite."]'::jsonb),
('Porc au caramel', 'Le plat vietnamien de porc mijoté dans un caramel à la sauce nuoc-mâm, sucré-salé et fondant.', 15, 60, 4, 2, 'gras', '["vietnamien", "asiatique", "viande", "mijoté", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper le porc en cubes de 3 cm. Cuire les œufs 9 min dans l''eau bouillante, les refroidir et les écaler.", "Dans une cocotte, faire fondre le sucre à sec avec 2 c.à.s d''eau à feu moyen, sans remuer, jusqu''à obtenir un caramel ambré foncé. Hors du feu, ajouter prudemment 4 c.à.s d''eau (ça éclabousse), puis le nuoc-mâm.", "Ajouter l''huile, les échalotes et l''ail émincés 1 min, puis la viande, et la retourner pour l''enrober de caramel.", "Verser l''eau de coco (ou de l''eau), ajouter le poivre, couvrir et mijoter 45 min à feu doux.", "Ajouter les œufs durs et poursuivre 15 min à découvert, en les retournant, jusqu''à ce que la sauce soit sirupeuse et brune. Servir avec le riz et les oignons nouveaux."]'::jsonb),
('Porc aigre-doux', 'Des morceaux de porc croustillants sautés avec ananas et poivrons dans une sauce aigre-douce.', 25, 20, 4, 2, 'gras', '["chinois", "asiatique", "viande", "friture", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper le porc en cubes de 2,5 cm, les mélanger avec l''œuf battu et une pincée de sel, puis les rouler dans 5 c.à.s de fécule.", "Sauce : mélanger le ketchup, le vinaigre, le sucre, la sauce soja, 100 ml d''eau et le reste de fécule.", "Chauffer l''huile à 175 °C et frire le porc en plusieurs fois 4 à 5 min, jusqu''à ce qu''il soit doré et cuit. Égoutter sur du papier absorbant.", "Dans un wok avec 1 c.à.s d''huile de friture, sauter les poivrons et l''oignon en morceaux 3 min à feu vif, puis l''ananas en dés 1 min.", "Verser la sauce et remuer jusqu''à ce qu''elle épaississe et devienne brillante. Ajouter le porc, enrober rapidement pour qu''il reste croustillant et servir avec le riz."]'::jsonb),
('Côtes de porc sauce charcutière', 'Des côtes de porc poêlées avec une sauce à l''échalote, au vin blanc, à la moutarde et aux cornichons.', 10, 20, 4, 1, 'gras', '["français", "viande", "bistrot", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Entailler le gras des côtes tous les 2 cm pour qu''elles restent plates. Saler et poivrer.", "Les cuire dans l''huile chaude 4 à 5 min par face à feu moyen-vif, jusqu''à 65-68 °C à cœur. Les réserver au chaud.", "Dans la poêle, faire fondre l''échalote hachée dans le beurre 2 min, verser le vin et gratter le fond, laisser réduire de moitié.", "Ajouter le fond de veau délayé dans 100 ml d''eau et laisser réduire 3 min. Hors du feu, ajouter la moutarde et les cornichons en rondelles.", "Napper les côtes de sauce et servir avec une purée."]'::jsonb),
('Petit salé aux lentilles', 'Du porc demi-sel et des saucisses mijotés avec des lentilles vertes, carottes et oignons.', 20, 120, 6, 1, 'protéiné', '["français", "viande", "mijoté", "hiver", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Dessaler le petit salé : le mettre dans une grande casserole d''eau froide, porter à ébullition 5 min, puis jeter l''eau.", "Remettre la viande dans la cocotte, couvrir d''eau froide, ajouter l''oignon piqué des clous de girofle, l''ail et le bouquet garni. Porter à frémissement et cuire 1h à feu doux.", "Ajouter les lentilles rincées, les carottes en rondelles et la saucisse piquée. Il faut environ deux fois le volume des lentilles en liquide : ajouter de l''eau si besoin.", "Cuire encore 40 à 45 min, jusqu''à ce que les lentilles soient tendres. Ne pas saler avant la fin : la viande est salée.", "Retirer le bouquet garni et l''oignon, couper la viande et la saucisse en morceaux, poivrer et servir avec les lentilles et un peu de moutarde."]'::jsonb),
('Rougail saucisse', 'Le plat réunionnais de saucisses mijotées dans une sauce tomate aux oignons, gingembre et piment.', 15, 45, 4, 1, 'gras', '["réunionnais", "viande", "épicé", "mijoté", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Piquer les saucisses et les faire blanchir 5 min dans l''eau bouillante pour retirer une partie du gras et du sel. Les égoutter et les couper en tronçons.", "Les faire dorer dans l''huile dans une cocotte 8 à 10 min.", "Ajouter les oignons émincés 5 min, puis l''ail et le gingembre pilés ensemble, le curcuma, le piment et le thym, 1 min.", "Ajouter les tomates coupées en petits dés, saler légèrement, couvrir et laisser mijoter 25 min, puis 5 min à découvert pour que la sauce épaississe.", "Servir avec le riz blanc. À la Réunion, on l''accompagne de grains (haricots rouges ou lentilles) et d''un rougail tomate pimenté."]'::jsonb),
('Saucisses de Toulouse, purée et oignons', 'Des saucisses dorées à la poêle avec une purée maison et une compotée d''oignons au vin rouge.', 15, 40, 4, 1, 'gras', '["français", "viande", "bistrot", "famille", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Cuire les pommes de terre épluchées et coupées dans de l''eau froide salée portée à ébullition, 20 à 25 min.", "Pendant ce temps, faire fondre les oignons émincés dans 20 g de beurre 15 min à feu doux avec le sucre, jusqu''à ce qu''ils soient dorés. Verser le vin et le fond de veau délayé dans 100 ml d''eau, laisser réduire jusqu''à ce que ce soit sirupeux.", "Cuire les saucisses dans une poêle à feu moyen 15 à 20 min en les retournant, sans les piquer pour qu''elles restent juteuses, jusqu''à ce qu''elles soient dorées et cuites à cœur (70 °C).", "Écraser les pommes de terre avec le reste du beurre et le lait chaud, saler et poivrer.", "Servir les saucisses sur la purée, nappées d''oignons."]'::jsonb),
('Porc effiloché', 'De l''épaule de porc frottée aux épices et cuite très longtemps, effilochée et nappée de sauce barbecue.', 20, 300, 8, 2, 'gras', '["américain", "viande", "barbecue", "four", "plat"]'::jsonb, 'public', '["oven"]'::jsonb, '["Mélanger la cassonade, les épices, le sel et le poivre, et en frotter toute l''épaule. Idéalement, laisser reposer une nuit au réfrigérateur.", "Préchauffer le four à 150 °C. Mettre la viande dans une cocotte avec le vinaigre et 150 ml d''eau, couvrir et cuire 4h30 à 5h, jusqu''à ce que la viande se défasse à la fourchette (90 à 95 °C à cœur).", "Coleslaw : râper le chou et les carottes, les mélanger avec la mayonnaise, 1 c.à.s de vinaigre, du sel et du poivre.", "Sortir la viande, retirer l''os et le gras, puis l''effilocher avec deux fourchettes. La mélanger avec la moitié de la sauce barbecue et quelques cuillerées de jus de cuisson dégraissé.", "Servir dans les pains toastés avec le coleslaw et le reste de sauce."]'::jsonb),
('Tonkatsu', 'Une côtelette de porc panée au panko, frite et croustillante, servie avec du chou émincé et une sauce tonkatsu.', 20, 15, 4, 2, 'gras', '["japonais", "asiatique", "viande", "friture", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Cuire le riz selon le paquet. Émincer le chou très finement et le garder dans de l''eau glacée pour qu''il soit croquant.", "Sauce : mélanger la sauce Worcestershire, le ketchup, la sauce soja et le sucre.", "Entailler le gras des escalopes, les aplatir légèrement, saler et poivrer. Les passer dans la farine, puis dans les œufs battus, puis dans le panko en appuyant.", "Chauffer l''huile à 170 °C et frire les escalopes 5 à 6 min en les retournant, jusqu''à ce qu''elles soient dorées et cuites à cœur. Les égoutter debout sur une grille pour qu''elles restent croustillantes.", "Trancher en bandes, servir avec le chou égoutté, le riz et la sauce."]'::jsonb),
('Jarret de porc à la bière', 'Des jarrets de porc braisés à la bière avec oignons et carottes, puis dorés au four.', 15, 150, 4, 2, 'gras', '["alsacien", "viande", "mijoté", "hiver", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Mettre les jarrets dans une cocotte avec les oignons en quartiers, les carottes en tronçons, l''ail, le laurier et le cumin. Verser la bière et de l''eau à hauteur, saler légèrement.", "Couvrir et cuire 2h à feu doux, jusqu''à ce que la viande soit très tendre.", "Préchauffer le four à 220 °C. Égoutter les jarrets et les mettre dans un plat avec les légumes.", "Mélanger la moutarde et le miel, en badigeonner la peau des jarrets et enfourner 20 à 30 min, jusqu''à ce qu''elle soit dorée et croustillante.", "Servir avec les légumes, un peu de jus de cuisson réduit et des pommes de terre."]'::jsonb),
('Gigot d''agneau rôti', 'Un gigot piqué d''ail, rôti au four avec thym et romarin, rosé et juteux.', 15, 75, 8, 2, 'protéiné', '["français", "viande", "four", "fête", "plat"]'::jsonb, 'public', '["oven"]'::jsonb, '["Sortir le gigot 1h avant. Préchauffer le four à 210 °C.", "Faire une dizaine de petites incisions dans la viande et y glisser l''ail coupé en éclats et des brins de romarin.", "Frotter le gigot d''huile, saler et poivrer. Le mettre dans un plat avec le thym, le beurre en morceaux et 100 ml d''eau.", "Rôtir 15 min, puis baisser à 180 °C et cuire environ 15 min par 500 g pour une viande rosée (60 °C à cœur), en arrosant toutes les 15 min.", "Laisser reposer 15 à 20 min sous une feuille d''aluminium, porte du four entrouverte : c''est ce repos qui rend le gigot juteux. Déglacer le plat avec un peu d''eau pour le jus et découper en tranches. Servir avec des flageolets ou un gratin."]'::jsonb),
('Navarin d''agneau aux légumes nouveaux', 'Un ragoût d''agneau mijoté avec navets, carottes, petits pois et pommes de terre nouvelles.', 25, 105, 6, 2, 'gras', '["français", "viande", "mijoté", "printemps", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper l''agneau en cubes de 4 cm en retirant l''excès de gras. Saler et poivrer.", "Faire dorer la viande en plusieurs fois dans l''huile dans une cocotte. Retirer l''excès de graisse, ajouter les oignons émincés 5 min, puis l''ail.", "Saupoudrer de farine et remuer 1 min, ajouter le concentré, verser le vin et le bouillon, ajouter le bouquet garni. Couvrir et mijoter 1h à feu doux.", "Ajouter les navets et les carottes en morceaux et les pommes de terre, poursuivre 30 min.", "Ajouter les petits pois 10 min avant la fin. Retirer le bouquet garni, rectifier l''assaisonnement et servir."]'::jsonb),
('Tajine d''agneau aux pruneaux', 'De l''agneau mijoté aux épices douces, pruneaux et amandes grillées, sucré-salé.', 20, 120, 6, 2, 'gras', '["marocain", "viande", "mijoté", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper la viande en gros morceaux. Dans une cocotte ou un tajine, la faire revenir dans l''huile avec les oignons râpés, les épices, du sel et du poivre, 5 min.", "Couvrir d''eau à hauteur, porter à frémissement, couvrir et laisser mijoter 1h30 à feu doux, jusqu''à ce que la viande soit tendre.", "Faire tremper les pruneaux 15 min dans de l''eau chaude, puis les ajouter avec le miel et une pincée de cannelle. Cuire encore 20 à 30 min à découvert, jusqu''à ce que la sauce soit sirupeuse.", "Faire dorer les amandes et le sésame à sec dans une poêle.", "Servir le tajine parsemé d''amandes, de sésame et de coriandre, avec de la semoule ou du pain."]'::jsonb),
('Épaule d''agneau confite 7 heures', 'Une épaule cuite très lentement jusqu''à se défaire à la cuillère, avec ail et herbes.', 15, 420, 6, 1, 'gras', '["français", "viande", "four", "mijoté", "fête", "plat"]'::jsonb, 'public', '["oven"]'::jsonb, '["Préchauffer le four à 120 °C.", "Frotter l''épaule d''huile, saler et poivrer. La dorer sur toutes les faces dans une grande cocotte, 10 min.", "Ajouter les oignons en quartiers, les têtes d''ail coupées en deux, le thym et le romarin. Verser le vin et 200 ml d''eau.", "Couvrir hermétiquement (on peut sceller le couvercle avec une pâte farine-eau) et enfourner 7h. Vérifier une ou deux fois qu''il reste du liquide au fond.", "La viande se détache de l''os à la cuillère. La servir dans la cocotte avec l''ail confit à écraser sur la viande et le jus de cuisson dégraissé."]'::jsonb),
('Curry d''agneau', 'Un curry indien d''agneau mijoté au yaourt et aux épices, dans l''esprit du rogan josh.', 20, 100, 4, 2, 'gras', '["indien", "viande", "épicé", "mijoté", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper l''agneau en cubes de 3 cm.", "Dans une cocotte, chauffer l''huile avec la cannelle, la cardamome écrasée et les clous de girofle 1 min, jusqu''à ce qu''ils embaument.", "Ajouter les oignons hachés et les cuire 10 min à feu moyen jusqu''à ce qu''ils soient bien dorés, puis l''ail et le gingembre râpés 1 min.", "Ajouter la viande et la faire colorer 5 min, puis les épices en poudre 1 min et du sel.", "Hors du feu, ajouter le yaourt une cuillerée à la fois en remuant (pour qu''il ne tranche pas), puis les tomates et 200 ml d''eau. Couvrir et mijoter 1h15 à 1h30 à feu doux, jusqu''à ce que la viande soit tendre.", "Cuire le riz selon le paquet. Servir le curry parsemé de coriandre."]'::jsonb),
('Côtelettes d''agneau grillées au romarin', 'Des côtelettes marinées à l''ail et au romarin, saisies en quelques minutes.', 10, 8, 4, 1, 'protéiné', '["méditerranéen", "viande", "grillade", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Mélanger l''huile, l''ail écrasé, les aiguilles de romarin hachées et le zeste du demi-citron. En enrober les côtelettes et laisser mariner 30 min à température ambiante.", "Chauffer une poêle-gril ou une plancha à feu vif. Cuire les côtelettes 2 à 3 min par face pour une viande rosée.", "Laisser reposer 3 min, parsemer de fleur de sel et de poivre, arroser d''un trait de jus de citron et servir."]'::jsonb),
('Couscous royal', 'Le couscous aux trois viandes (agneau, poulet, merguez), légumes et bouillon parfumé.', 40, 120, 8, 3, 'gras', '["maghrébin", "viande", "fête", "mijoté", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Dans un grand faitout, faire dorer l''agneau en morceaux et le poulet dans 2 c.à.s d''huile. Ajouter les oignons émincés 5 min, le concentré de tomate et les épices 1 min.", "Couvrir de 3 litres d''eau, saler, poivrer, ajouter la moitié de la coriandre en bouquet. Porter à ébullition et mijoter 45 min à couvert.", "Ajouter les carottes et les navets en gros tronçons, cuire 30 min, puis les courgettes et les pois chiches rincés, encore 20 min.", "Semoule : la mettre dans un grand plat avec le reste d''huile et une pincée de sel, verser le même volume d''eau bouillante, couvrir 5 min, puis égrener à la fourchette avec le beurre. On peut aussi la cuire à la vapeur au-dessus du bouillon.", "Griller les merguez à la poêle ou au gril 8 à 10 min.", "Servir la semoule avec les viandes, les légumes et le bouillon à part. Délayer la harissa dans une louche de bouillon pour ceux qui aiment piquant."]'::jsonb),
('Souris d''agneau braisées', 'Des souris d''agneau braisées au vin rouge avec ail et romarin jusqu''à être fondantes.', 15, 150, 4, 2, 'gras', '["français", "viande", "mijoté", "fête", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Préchauffer le four à 160 °C. Saler et poivrer les souris, les dorer sur toutes les faces dans l''huile dans une cocotte, 8 à 10 min. Réserver.", "Faire revenir les oignons et les carottes en morceaux 5 min, ajouter l''ail en chemise et le concentré 1 min.", "Verser le vin, gratter le fond et porter à ébullition 2 min, puis ajouter le bouillon et les herbes. Remettre les souris.", "Couvrir et enfourner 2h à 2h30, en retournant la viande à mi-cuisson, jusqu''à ce qu''elle se détache de l''os.", "Retirer les souris et faire réduire la sauce sur le feu 10 min jusqu''à ce qu''elle nappe. Servir avec une purée ou de la polenta."]'::jsonb),
('Poulet tikka masala', 'Des morceaux de poulet marinés au yaourt et grillés, dans une sauce tomate crémeuse aux épices.', 25, 35, 4, 2, 'gras', '["indien", "poulet", "épicé", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Couper le poulet en gros cubes. Le mélanger avec le yaourt, le jus du demi-citron, 1 c.à.c de garam masala, 1 c.à.c de paprika, du sel, et laisser mariner au moins 1h au réfrigérateur.", "Préchauffer le four en position gril à 250 °C. Étaler le poulet sur une plaque et le griller 10 à 12 min en le retournant, jusqu''à ce qu''il soit doré par endroits (il finira de cuire dans la sauce).", "Dans une sauteuse, faire fondre l''oignon haché dans l''huile et le beurre 8 min, ajouter l''ail et le gingembre râpés 1 min, puis le reste des épices 1 min.", "Ajouter les tomates et mijoter 10 min, puis mixer la sauce si on la veut lisse. Ajouter la crème.", "Ajouter le poulet et mijoter 8 à 10 min, jusqu''à ce qu''il soit cuit à cœur (74 °C). Cuire le riz selon le paquet et servir parsemé de coriandre."]'::jsonb),
('Butter chicken', 'Le poulet au beurre indien : une sauce tomate très douce, beurrée et crémeuse, parfumée au fenugrec.', 20, 35, 4, 2, 'gras', '["indien", "poulet", "famille", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper le poulet en morceaux et le faire mariner 30 min avec le yaourt, 1 c.à.c de garam masala, 1 c.à.c de paprika et du sel.", "Dans une sauteuse, faire dorer le poulet dans 20 g de beurre 6 à 8 min. Le réserver.", "Faire fondre 20 g de beurre, ajouter l''oignon haché 8 min, puis l''ail et le gingembre 1 min, le reste des épices et le concentré 1 min.", "Ajouter la passata et le sucre, mijoter 10 min, puis mixer pour une sauce lisse.", "Remettre le poulet, ajouter le fenugrec émietté entre les doigts, et mijoter 10 min jusqu''à ce qu''il soit cuit à cœur. Ajouter la crème et le reste du beurre hors du feu. Servir avec le riz ou des naans."]'::jsonb),
('Poulet yassa', 'Le plat sénégalais de poulet mariné au citron, cuit avec une montagne d''oignons fondants à la moutarde.', 25, 60, 4, 2, 'protéiné', '["sénégalais", "africain", "poulet", "mijoté", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Émincer les oignons. Dans un saladier, mélanger le poulet, les oignons, le jus des citrons, la moutarde, l''ail écrasé, 2 c.à.s d''huile, du sel, du poivre et le piment. Laisser mariner au moins 2h au réfrigérateur, idéalement une nuit.", "Égoutter le poulet (garder les oignons et la marinade) et le faire dorer dans le reste d''huile dans une cocotte, 5 min par face. Réserver.", "Mettre les oignons égouttés dans la cocotte et les faire fondre 15 à 20 min à feu moyen, jusqu''à ce qu''ils soient tendres et dorés.", "Ajouter la marinade, le bouillon cube émietté, le laurier et 200 ml d''eau. Remettre le poulet.", "Couvrir et mijoter 35 à 40 min, jusqu''à ce que le poulet soit cuit à cœur et les oignons confits. Servir avec le riz."]'::jsonb),
('Poulet à la crème et aux champignons', 'Des morceaux de poulet dorés puis mijotés dans une sauce crème aux champignons et au vin blanc.', 15, 40, 4, 1, 'gras', '["français", "poulet", "famille", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Saler et poivrer les cuisses. Les dorer côté peau dans l''huile et 10 g de beurre 8 min, puis 3 min de l''autre côté. Réserver.", "Retirer l''excès de graisse, faire fondre le reste du beurre, ajouter les échalotes hachées et les champignons en quartiers 5 min.", "Verser le vin, gratter le fond, laisser réduire de moitié, puis ajouter le bouillon et le thym. Remettre le poulet, peau vers le haut.", "Couvrir et mijoter 25 min à feu doux, jusqu''à ce que le poulet soit cuit à cœur (74 °C).", "Retirer le poulet, ajouter la crème et laisser épaissir la sauce 3 min. Napper le poulet, parsemer de persil et servir avec du riz ou des pâtes."]'::jsonb),
('Poulet au citron (piccata)', 'De fines escalopes de poulet poêlées, dans une sauce beurre-citron aux câpres.', 10, 15, 4, 1, 'protéiné', '["italien", "poulet", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper les blancs en deux dans l''épaisseur et les aplatir à 1 cm. Saler, poivrer et fariner légèrement.", "Dorer les escalopes dans l''huile et 10 g de beurre 3 min par face, jusqu''à ce qu''elles soient cuites à cœur. Réserver au chaud.", "Dans la poêle, faire revenir l''ail haché 30 secondes, verser le vin et gratter le fond, puis le bouillon et le jus du citron. Laisser réduire de moitié.", "Hors du feu, ajouter les câpres et le reste du beurre en remuant jusqu''à ce que la sauce soit brillante.", "Napper le poulet de sauce, parsemer de persil et servir avec des pâtes ou des légumes verts."]'::jsonb),
('Poulet teriyaki', 'Des hauts de cuisse de poulet poêlés et laqués d''une sauce teriyaki maison sucrée-salée.', 10, 20, 4, 1, 'protéiné', '["japonais", "asiatique", "poulet", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Cuire le riz selon le paquet. Mélanger la sauce soja, le mirin, le saké, le sucre et le gingembre râpé.", "Cuire les hauts de cuisse côté peau dans l''huile à feu moyen 8 min, jusqu''à ce que la peau soit dorée et croustillante, puis les retourner 5 min.", "Retirer l''excès de graisse de la poêle avec du papier absorbant.", "Verser la sauce et laisser bouillonner 3 à 4 min en retournant le poulet, jusqu''à ce qu''elle devienne sirupeuse et le laque. Le poulet doit être cuit à cœur (74 °C).", "Trancher le poulet, napper du reste de sauce, parsemer de sésame et d''oignons nouveaux et servir avec le riz."]'::jsonb),
('Poulet du général Tao', 'Des morceaux de poulet frits et croustillants enrobés d''une sauce sucrée, piquante et collante.', 25, 20, 4, 2, 'gras', '["chinois", "américain", "poulet", "friture", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper le poulet en morceaux de 3 cm. Le mélanger avec l''œuf et une pincée de sel, puis l''enrober de 5 c.à.s de fécule.", "Sauce : mélanger la sauce soja, le vinaigre, le sucre, la sauce hoisin, 100 ml d''eau et le reste de fécule.", "Frire le poulet dans l''huile à 170 °C en plusieurs fois 5 à 6 min, jusqu''à ce qu''il soit doré et cuit. Égoutter.", "Dans un wok avec 1 c.à.s d''huile, faire revenir l''ail, le gingembre et le piment 30 secondes. Verser la sauce et remuer jusqu''à ce qu''elle épaississe et devienne brillante.", "Ajouter le poulet, enrober rapidement, parsemer de sésame et d''oignons nouveaux et servir avec le riz."]'::jsonb),
('Mafé de poulet', 'Le ragoût ouest-africain de poulet dans une sauce onctueuse à la pâte d''arachide et à la tomate.', 20, 60, 4, 2, 'gras', '["africain", "sénégalais", "poulet", "mijoté", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Dorer les cuisses de poulet dans l''huile dans une cocotte 5 min par face. Réserver.", "Faire fondre les oignons hachés 5 min, ajouter l''ail et le gingembre 1 min, puis le concentré de tomate 1 min et les tomates.", "Délayer le beurre de cacahuète dans le bouillon chaud et verser dans la cocotte. Ajouter le poulet, le piment et saler.", "Couvrir et mijoter 20 min, puis ajouter les carottes en rondelles et la patate douce en cubes. Poursuivre 30 min à feu doux en remuant de temps en temps (la sauce attache facilement), jusqu''à ce que les légumes soient tendres et que l''huile remonte à la surface.", "Servir avec le riz blanc."]'::jsonb),
('Fajitas de poulet et sauce maison', 'Des lanières de poulet et de poivrons sautées aux épices, roulées dans des tortillas avec une sauce maison au yaourt, citron vert et ail.', 20, 15, 4, 1, 'protéiné', '["mexicain", "tex-mex", "poulet", "rapide", "étudiant", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Sauce maison : mélanger le yaourt avec le jus d''un demi citron vert, l''ail râpé, un peu de coriandre ciselée et une pincée de sel. Garder au frais.", "Couper le poulet en lanières. Le mélanger avec 1 c.à.s d''huile, les épices, le jus de l''autre demi citron vert et du sel. Laisser mariner 15 min.", "Couper les poivrons et l''oignon en lanières, émincer la salade.", "Dans une grande poêle très chaude, saisir le poulet 5 à 6 min jusqu''à ce qu''il soit doré et cuit à cœur. Le réserver.", "Dans la même poêle avec le reste d''huile, sauter les poivrons et l''oignon 5 min à feu vif : ils doivent rester un peu croquants. Remettre le poulet.", "Chauffer les tortillas 20 secondes par face dans une poêle sèche. Garnir de salade, de poulet aux légumes et de sauce maison, parsemer de coriandre et rouler."]'::jsonb),
('Poulet tandoori', 'Des cuisses de poulet marinées au yaourt et aux épices tandoori, rôties au four.', 15, 40, 4, 1, 'protéiné', '["indien", "poulet", "four", "plat"]'::jsonb, 'public', '["oven"]'::jsonb, '["Retirer la peau des cuisses et les entailler profondément 3 fois pour que la marinade pénètre.", "Mélanger le yaourt, le jus du citron, l''ail et le gingembre râpés, les épices, l''huile et le sel. En enrober le poulet et laisser mariner 4h à une nuit au réfrigérateur.", "Préchauffer le four à 220 °C. Disposer les cuisses sur une grille au-dessus d''une plaque.", "Rôtir 35 à 40 min, jusqu''à ce que le poulet soit bien coloré et cuit à cœur (74 °C près de l''os). Passer 2 min sous le gril pour noircir légèrement les bords.", "Servir avec le riz, l''oignon rouge en fines rondelles et des quartiers de citron."]'::jsonb),
('Cuisses de poulet rôties au four', 'Des cuisses de poulet à la peau croustillante, rôties sur un lit de pommes de terre et d''oignons.', 10, 50, 4, 1, 'gras', '["français", "poulet", "four", "famille", "économique", "plat"]'::jsonb, 'public', '["oven"]'::jsonb, '["Préchauffer le four à 210 °C.", "Couper les pommes de terre en quartiers et les oignons en huit. Les mélanger dans un grand plat avec 2 c.à.s d''huile, l''ail en chemise, du sel et du poivre.", "Sécher la peau des cuisses avec du papier absorbant (elle croustillera mieux), les frotter avec le reste d''huile, le paprika, les herbes, du sel et du poivre.", "Poser les cuisses sur les pommes de terre, peau vers le haut, et rôtir 45 à 50 min, jusqu''à ce que la peau soit dorée et que le jus qui s''écoule en piquant près de l''os soit clair (74 °C)."]'::jsonb),
('Poulet aux quarante gousses d''ail', 'Un poulet cuit en cocotte avec des gousses d''ail entières qui deviennent douces et confites.', 15, 90, 4, 1, 'gras', '["provençal", "français", "poulet", "four", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Préchauffer le four à 190 °C. Séparer les gousses d''ail sans les éplucher.", "Saler et poivrer le poulet dedans et dehors, glisser quelques herbes à l''intérieur.", "Dans une cocotte, dorer le poulet dans l''huile sur toutes les faces 10 min. Ajouter l''ail, le reste des herbes et le vin.", "Couvrir et enfourner 1h15, puis retirer le couvercle et cuire encore 15 min pour dorer la peau. Le poulet est cuit quand le jus de la cuisse est clair (74 °C).", "Servir le poulet avec l''ail confit, à écraser sur des tranches de baguette grillée."]'::jsonb),
('Tajine de poulet aux citrons confits', 'Le tajine marocain de poulet au safran et au gingembre, avec citrons confits et olives vertes.', 20, 60, 4, 2, 'protéiné', '["marocain", "poulet", "mijoté", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Mélanger le poulet avec l''huile, l''ail écrasé, les épices, un peu de sel (les citrons confits sont salés) et du poivre. Laisser mariner 1h si possible.", "Dans un tajine ou une cocotte, faire revenir le poulet avec les oignons râpés 8 min en le retournant.", "Ajouter 250 ml d''eau et la moitié des herbes hachées, couvrir et mijoter 40 min à feu doux.", "Ajouter les citrons confits coupés en quartiers (sans la chair si on la trouve trop amère) et les olives rincées. Poursuivre 15 min à découvert pour que la sauce réduise.", "Parsemer du reste des herbes et servir avec du pain ou de la semoule."]'::jsonb),
('Curry vert thaï au poulet', 'Un curry thaï parfumé au lait de coco, basilic et citron vert, avec du poulet et des légumes.', 15, 20, 4, 1, 'gras', '["thaï", "asiatique", "poulet", "épicé", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper le poulet en fines lamelles, l''aubergine en cubes et les haricots en tronçons.", "Cuire le riz selon le paquet.", "Dans une sauteuse, chauffer l''huile avec 4 c.à.s de la crème épaisse du dessus du lait de coco, ajouter la pâte de curry et remuer 2 min jusqu''à ce qu''elle embaume.", "Ajouter le poulet et l''enrober 2 min, puis le reste du lait de coco, 100 ml d''eau, les feuilles de kaffir, le nuoc-mâm et le sucre.", "Ajouter l''aubergine et les haricots et mijoter 10 min, jusqu''à ce que les légumes soient tendres et le poulet cuit.", "Hors du feu, ajouter le basilic et un filet de jus de citron vert. Goûter et ajuster avec du nuoc-mâm. Servir avec le riz."]'::jsonb),
('Escalopes de dinde à la crème', 'Des escalopes de dinde dorées, nappées d''une sauce crème aux champignons et à l''estragon.', 10, 20, 4, 1, 'protéiné', '["français", "volaille", "rapide", "famille", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Saler et poivrer les escalopes. Les dorer dans le beurre et l''huile 3 min par face, jusqu''à ce qu''elles soient cuites à cœur. Réserver au chaud.", "Dans la poêle, faire revenir l''échalote hachée et les champignons émincés 5 min.", "Verser le vin et laisser réduire, puis ajouter la crème et l''estragon et laisser épaissir 2 à 3 min.", "Remettre les escalopes 1 min dans la sauce et servir avec du riz ou des pâtes."]'::jsonb),
('Sauté de dinde au curry', 'Des morceaux de dinde mijotés dans une sauce curry douce au lait de coco et aux pommes.', 15, 30, 4, 1, 'protéiné', '["volaille", "indien", "famille", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire dorer la dinde en morceaux dans l''huile 5 min. Réserver.", "Faire fondre l''oignon haché 5 min, ajouter l''ail et le curry 1 min.", "Ajouter la pomme en petits dés, le lait de coco et le bouillon, saler, puis remettre la dinde.", "Mijoter 20 min à feu doux, jusqu''à ce que la dinde soit tendre et la sauce nappante.", "Cuire le riz selon le paquet et servir avec la coriandre."]'::jsonb),
('Rôti de dinde aux champignons', 'Un rôti de dinde cuit en cocotte avec des champignons et un jus au vin blanc.', 15, 70, 6, 1, 'light', '["français", "volaille", "famille", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Saler et poivrer le rôti, le dorer sur toutes les faces dans l''huile et le beurre dans une cocotte, 10 min.", "Ajouter les oignons émincés 3 min, verser le vin et le bouillon, ajouter le thym.", "Couvrir et cuire 45 min à feu doux en retournant le rôti à mi-cuisson.", "Ajouter les champignons en quartiers et poursuivre 15 min à couvert. La dinde est cuite à 72-74 °C à cœur.", "Laisser reposer 10 min avant de trancher et servir avec les champignons et le jus."]'::jsonb),
('Magret de canard au miel', 'Un magret saisi côté peau, rosé à cœur, nappé d''une sauce au miel et au vinaigre balsamique.', 10, 20, 4, 2, 'gras', '["français", "canard", "viande", "fête", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Sortir les magrets 30 min avant. Quadriller la peau en losanges avec un couteau bien aiguisé, sans entailler la chair.", "Poser les magrets côté peau dans une poêle froide, puis chauffer à feu moyen. Cuire 8 à 10 min en retirant régulièrement la graisse fondue, jusqu''à ce que la peau soit dorée et croustillante.", "Retourner et cuire 3 à 4 min côté chair pour une cuisson rosée (54-56 °C à cœur). Laisser reposer 5 min sous une feuille d''aluminium.", "Vider la graisse de la poêle (la garder pour des pommes de terre sautées). Ajouter le miel, le vinaigre, le fond de veau et 50 ml d''eau, et laisser réduire 2 min jusqu''à ce que ce soit sirupeux.", "Trancher les magrets, napper de sauce, parsemer de fleur de sel et de poivre et servir."]'::jsonb),
('Confit de canard et pommes sarladaises', 'Des cuisses de canard confites réchauffées jusqu''à être croustillantes, avec des pommes de terre sautées à la graisse de canard, ail et persil.', 15, 40, 4, 1, 'gras', '["français", "sud-ouest", "canard", "viande", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Préchauffer le four à 200 °C. Retirer les cuisses de leur graisse (la garder) et les poser côté peau dans un plat.", "Éplucher les pommes de terre et les couper en rondelles de 5 mm. Les rincer et les sécher dans un torchon.", "Enfourner les cuisses 20 à 25 min, jusqu''à ce que la peau soit croustillante et la chair bien chaude.", "Pendant ce temps, chauffer 3 c.à.s de graisse de canard dans une grande poêle et y cuire les pommes de terre 20 à 25 min à feu moyen, en les retournant de temps en temps, jusqu''à ce qu''elles soient dorées et tendres. Saler et poivrer.", "Hacher l''ail et le persil ensemble, les ajouter aux pommes de terre 2 min avant la fin. Servir avec les cuisses."]'::jsonb),
('Canard à l''orange', 'Des cuisses de canard rôties nappées d''une sauce aigre-douce à l''orange.', 20, 80, 4, 2, 'gras', '["français", "canard", "viande", "fête", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Préchauffer le four à 180 °C. Piquer la peau des cuisses, saler et poivrer.", "Les dorer côté peau dans une poêle 8 min pour faire fondre la graisse, puis les mettre dans un plat et enfourner 1h à 1h10, jusqu''à ce qu''elles soient tendres et bien dorées.", "Prélever le zeste de 2 oranges en fines lanières et le blanchir 1 min à l''eau bouillante. Presser le jus de 3 oranges et peler la dernière à vif en quartiers.", "Dans une casserole, faire un caramel blond avec le sucre et 2 c.à.s d''eau, puis ajouter le vinaigre hors du feu (attention aux projections) : c''est la gastrique.", "Ajouter le jus d''orange, le fond de veau délayé dans 100 ml d''eau et la liqueur, et laisser réduire 10 min jusqu''à ce que la sauce nappe. Ajouter les zestes et le beurre hors du feu.", "Servir les cuisses nappées de sauce avec les quartiers d''orange."]'::jsonb),
('Parmentier de canard', 'Du confit de canard effiloché sous une purée maison dorée, le hachis parmentier du Sud-Ouest.', 25, 45, 6, 1, 'gras', '["français", "sud-ouest", "canard", "four", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Cuire les pommes de terre épluchées dans de l''eau froide salée portée à ébullition, 20 à 25 min.", "Réchauffer les cuisses de canard dans leur graisse à feu doux, retirer la peau et les os et effilocher la chair.", "Faire fondre les échalotes hachées dans 1 c.à.s de graisse de canard 5 min, ajouter la chair et le persil, poivrer.", "Écraser les pommes de terre avec le beurre et le lait chaud, saler, poivrer et ajouter la muscade.", "Préchauffer le four à 200 °C. Étaler le canard dans un plat, couvrir de purée, parsemer de chapelure et de quelques noisettes de graisse de canard. Enfourner 20 min jusqu''à ce que le dessus soit doré."]'::jsonb),
('Lapin à la moutarde', 'Le lapin mijoté à la moutarde et au vin blanc, nappé d''une sauce crémeuse.', 20, 60, 4, 2, 'protéiné', '["français", "viande", "lapin", "mijoté", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire découper le lapin en morceaux par le boucher (ou acheter des cuisses). Saler, poivrer et badigeonner les morceaux de 3 c.à.s de moutarde.", "Dans une cocotte, les faire dorer dans le beurre et l''huile 3 min par face. Réserver.", "Faire revenir les lardons et les échalotes émincées 5 min.", "Remettre le lapin, verser le vin, ajouter le thym et le laurier. Couvrir et mijoter 45 min à feu doux en retournant les morceaux à mi-cuisson.", "Retirer le lapin. Ajouter la crème et le reste de moutarde à la sauce et laisser épaissir 3 min sans faire bouillir fort. Remettre le lapin, napper et servir avec des tagliatelles ou des pommes vapeur."]'::jsonb),
('Lapin chasseur', 'Le lapin mijoté à la tomate, aux champignons et au vin blanc, parfumé à l''estragon.', 20, 70, 4, 2, 'protéiné', '["français", "viande", "lapin", "mijoté", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Saler et poivrer le lapin, le dorer dans l''huile dans une cocotte 4 min par face. Réserver.", "Faire revenir les échalotes et l''ail hachés avec les champignons en quartiers dans le beurre 5 min.", "Saupoudrer de farine, remuer 1 min, verser le vin et gratter le fond, puis ajouter les tomates et le bouillon.", "Remettre le lapin, couvrir et mijoter 50 min à 1h à feu doux, jusqu''à ce que la chair se détache facilement.", "Ajouter l''estragon et le persil hachés, rectifier l''assaisonnement et servir."]'::jsonb),
('Lapin aux pruneaux', 'Un lapin mijoté à la bière ou au vin avec des pruneaux fondants, sucré-salé.', 20, 70, 4, 2, 'protéiné', '["français", "viande", "lapin", "mijoté", "hiver", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire tremper les pruneaux dans de l''eau tiède 20 min.", "Saler, poivrer les morceaux de lapin et les faire dorer dans le beurre dans une cocotte. Réserver.", "Faire revenir les lardons et les oignons émincés 5 min, saupoudrer de farine et remuer 1 min.", "Verser la bière et le bouillon, ajouter le thym, le laurier et la cassonade. Remettre le lapin, couvrir et mijoter 40 min.", "Ajouter les pruneaux égouttés et poursuivre 20 min à couvert, puis 10 min à découvert pour réduire la sauce. Servir avec une purée."]'::jsonb),
('Pintade aux choux', 'Une pintade cuite en cocotte sur un lit de chou vert, de lardons et de carottes.', 25, 90, 4, 2, 'gras', '["français", "volaille", "mijoté", "hiver", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Retirer les feuilles abîmées du chou, le couper en huit et le blanchir 8 min dans l''eau bouillante salée. L''égoutter.", "Saler et poivrer la pintade dedans et dehors. La dorer sur toutes les faces dans le beurre dans une grande cocotte, 10 min. Réserver.", "Faire revenir les lardons, l''oignon émincé et les carottes en rondelles 5 min.", "Ajouter le chou, le genièvre, le thym et le laurier, poser la pintade dessus et verser le bouillon.", "Couvrir et cuire 1h15 à feu doux, jusqu''à ce que le jus de la cuisse soit clair (74 °C). Découper la pintade et la servir sur le chou."]'::jsonb),
('Cailles aux raisins', 'Des cailles rôties à la cocotte, avec des grains de raisin et un jus au cognac.', 15, 30, 4, 2, 'gras', '["français", "volaille", "fête", "automne", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Saler et poivrer les cailles dedans et dehors, glisser un brin de thym dans chacune.", "Dans une cocotte, les faire dorer dans le beurre à feu moyen 8 à 10 min sur toutes les faces.", "Ajouter les échalotes émincées, verser le cognac (hors de la flamme) et gratter le fond, puis le bouillon.", "Couvrir et cuire 15 min à feu doux.", "Ajouter les grains de raisin et poursuivre 5 min à découvert, en arrosant les cailles de jus. Servir avec une purée de céleri ou des pommes sautées."]'::jsonb),
('Poule au pot', 'La poule farcie cuite dans un bouillon avec des légumes, le plat du dimanche d''Henri IV.', 40, 180, 6, 2, 'gras', '["français", "volaille", "mijoté", "hiver", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Farce : faire tremper la mie de pain dans le lait, l''essorer et la mélanger avec la chair à saucisse, le jambon haché, l''œuf, l''ail et le persil hachés et du poivre. En farcir la poule et coudre ou fermer l''ouverture avec des cure-dents.", "Mettre la poule dans un grand faitout, couvrir d''eau froide, ajouter l''oignon piqué des clous de girofle, le bouquet garni, le gros sel et le poivre. Porter à ébullition en écumant.", "Laisser frémir 2h à couvert, à petits bouillons.", "Ajouter les carottes, les navets, les poireaux ficelés et le céleri, et poursuivre 1h, jusqu''à ce que la poule soit très tendre.", "Servir le bouillon en entrée, puis la poule découpée avec sa farce en tranches et les légumes, accompagnés de cornichons et de moutarde."]'::jsonb),
('Oie rôtie aux marrons', 'Une oie rôtie lentement pour que sa peau devienne croustillante, avec des marrons et des pommes.', 30, 210, 8, 3, 'gras', '["français", "volaille", "fête", "noël", "four", "plat"]'::jsonb, 'public', '["oven"]'::jsonb, '["Préchauffer le four à 180 °C. Piquer la peau de l''oie partout avec une fourchette (sans atteindre la chair) pour que la graisse s''écoule.", "Saler et poivrer l''intérieur, y mettre 2 pommes en quartiers, un oignon et le thym. Saler et poivrer l''extérieur.", "Poser l''oie sur une grille au-dessus d''un grand plat et enfourner. Compter environ 45 min par kilo (3h à 3h30 pour une oie de 4 kg).", "Toutes les 45 min, retirer la graisse accumulée dans le plat (la garder : elle est idéale pour les pommes de terre).", "30 min avant la fin, disposer autour les marrons, les pommes et l''oignon restants en quartiers, arrosés d''un peu de graisse. L''oie est cuite quand le jus de la cuisse est clair (74 °C).", "Laisser reposer 20 min sous une feuille d''aluminium avant de découper."]'::jsonb),
('Civet de chevreuil', 'Du chevreuil mariné au vin rouge puis mijoté avec lardons, champignons et petits oignons.', 30, 150, 6, 3, 'gras', '["français", "gibier", "viande", "mijoté", "automne", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["La veille, faire mariner la viande avec le vin, les carottes en rondelles, un oignon émincé, l''ail écrasé, le genièvre et le bouquet garni, 12 à 24h au réfrigérateur.", "Égoutter la viande en gardant la marinade et ses légumes, et la sécher avec du papier absorbant.", "Dans une cocotte, faire dorer les lardons, puis la viande en plusieurs fois dans l''huile. Ajouter le second oignon et les légumes de la marinade 5 min.", "Saupoudrer de farine et remuer 1 min, verser le cognac puis la marinade. Porter à ébullition en grattant le fond.", "Couvrir et mijoter 2h à feu très doux, jusqu''à ce que la viande soit tendre.", "Faire dorer les champignons et les oignons grelots à la poêle et les ajouter 20 min avant la fin. Terminer par le chocolat, qui arrondit la sauce. Retirer le bouquet garni et servir avec des pâtes fraîches ou une purée de céleri."]'::jsonb),
('Sauté de sanglier au vin rouge', 'Des morceaux de sanglier mijotés longuement au vin rouge avec des airelles ou de la confiture de groseilles.', 25, 150, 6, 3, 'gras', '["français", "gibier", "viande", "mijoté", "automne", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["La veille, mettre la viande à mariner dans le vin avec les oignons et les carottes émincés, l''ail, le genièvre, le thym et le laurier.", "Égoutter et sécher la viande, filtrer la marinade en gardant les légumes.", "Faire dorer la viande en plusieurs fois dans l''huile dans une cocotte, puis les légumes de la marinade 5 min.", "Saupoudrer de farine, ajouter le concentré et remuer 1 min, puis verser la marinade. Couvrir et mijoter 2h à 2h30 à feu doux : le sanglier doit être cuit à cœur et très tendre.", "Ajouter la gelée de groseilles, laisser réduire la sauce 10 min à découvert, rectifier l''assaisonnement et servir avec des spätzle, des pâtes ou une purée de marrons."]'::jsonb),
('Rognons de veau à la moutarde', 'Des rognons de veau saisis rapidement, dans une sauce crème à la moutarde et au cognac.', 15, 10, 2, 2, 'protéiné', '["français", "viande", "abats", "bistrot", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Retirer la graisse et les parties blanches au centre des rognons, puis les couper en morceaux de 2 cm.", "Chauffer 20 g de beurre dans une poêle à feu vif et saisir les rognons 2 à 3 min : ils doivent rester rosés, sinon ils durcissent. Les égoutter dans une passoire (ils rendent un jus amer qu''on jette).", "Dans la poêle, faire fondre l''échalote hachée dans le reste du beurre 1 min. Verser le cognac (hors de la flamme), puis la crème et les moutardes, et laisser épaissir 2 min.", "Remettre les rognons 1 min dans la sauce pour les réchauffer, saler, poivrer, parsemer de persil et servir avec du riz ou des pommes sautées."]'::jsonb),
('Boudin noir aux pommes', 'Du boudin noir poêlé servi avec des quartiers de pommes caramélisés au beurre.', 10, 20, 4, 1, 'gras', '["français", "viande", "rapide", "hiver", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Cuire les pommes de terre épluchées dans de l''eau salée 20 min et les écraser avec 20 g de beurre et le lait chaud. Saler, poivrer.", "Éplucher les pommes, les couper en quartiers et retirer le cœur. Les dorer dans 20 g de beurre avec le sucre et la cannelle 10 min à feu moyen, jusqu''à ce qu''elles soient caramélisées et tendres.", "Piquer légèrement le boudin et le cuire dans une poêle à feu doux 8 à 10 min en le retournant délicatement : trop chaud, il éclate.", "Servir le boudin avec les pommes et la purée."]'::jsonb),
('Andouillette sauce moutarde', 'Une andouillette dorée à la poêle, nappée d''une sauce crème à la moutarde, avec des frites.', 10, 25, 2, 1, 'gras', '["français", "viande", "bistrot", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Cuire les frites au four selon le paquet.", "Entailler légèrement la peau des andouillettes en biais et les cuire à feu moyen dans l''huile 15 à 20 min en les retournant, jusqu''à ce qu''elles soient bien dorées et chaudes à cœur (70 °C).", "Les réserver au chaud. Dans la poêle, faire revenir l''échalote hachée 1 min, verser le vin et laisser réduire de moitié.", "Ajouter la crème et la moutarde, laisser épaissir 2 min, poivrer et napper les andouillettes. Servir avec les frites."]'::jsonb),
('Croziflette', 'La cousine savoyarde de la tartiflette, avec des crozets (petites pâtes de sarrasin), lardons et reblochon.', 15, 35, 4, 1, 'gras', '["savoyard", "montagne", "pâtes", "four", "hiver", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Cuire les crozets dans une grande casserole d''eau bouillante salée 15 à 20 min (ils sont longs à cuire), puis les égoutter.", "Faire dorer les lardons à sec 5 min, ajouter les oignons émincés et cuire 8 min jusqu''à ce qu''ils soient fondants. Déglacer au vin blanc.", "Préchauffer le four à 200 °C. Mélanger les crozets, les lardons, les oignons et la crème, poivrer et verser dans un plat.", "Couper le reblochon en deux dans l''épaisseur et le poser dessus, croûte vers le haut.", "Enfourner 15 à 20 min, jusqu''à ce que le fromage soit fondu et doré. Servir avec une salade verte."]'::jsonb),
('Riz cantonais maison', 'Le riz sauté aux œufs, jambon et petits pois, idéal pour finir un reste de riz de la veille.', 10, 12, 2, 1, 'gras', '["chinois", "étudiant", "économique", "rapide", "anti-gaspi", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Cuire le riz selon le paquet, l''étaler sur une assiette et le laisser refroidir (ou utiliser un reste de riz de la veille, gardé au frais : il sera moins collant).", "Battre les œufs avec une pincée de sel. Les cuire en omelette fine dans 1 c.à.s d''huile, les couper en lanières et réserver.", "Dans la même poêle bien chaude, chauffer le reste d''huile, ajouter les petits pois 2 min, puis le riz, et le faire sauter 3 min à feu vif en l''égrenant.", "Ajouter le jambon en dés, l''omelette, la sauce soja et les oignons nouveaux émincés, sauter encore 1 min et servir."]'::jsonb),
('Tortilla de patatas', 'L''omelette espagnole épaisse aux pommes de terre et aux oignons, bonne chaude ou froide.', 10, 30, 4, 2, 'gras', '["espagnol", "étudiant", "économique", "végétarien", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Éplucher les pommes de terre, les couper en fines lamelles et émincer l''oignon.", "Dans une poêle de 24 cm, cuire les pommes de terre et l''oignon dans l''huile à feu moyen-doux 15 à 20 min, en remuant de temps en temps : ils doivent être tendres, sans trop dorer. Saler et égoutter l''huile (la garder).", "Battre les œufs avec une pincée de sel dans un saladier, y mélanger les pommes de terre et laisser reposer 5 min.", "Remettre 1 c.à.s d''huile dans la poêle, verser le mélange et cuire 5 à 6 min à feu doux, jusqu''à ce que les bords soient pris.", "Poser une grande assiette sur la poêle, retourner la tortilla d''un geste, puis la faire glisser dans la poêle pour cuire l''autre face 3 à 4 min. Servir chaud ou froid."]'::jsonb),
('Dahl de lentilles corail', 'Un curry de lentilles corail fondantes au lait de coco, économique et nourrissant.', 10, 25, 4, 1, 'protéiné', '["indien", "étudiant", "économique", "végan", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Rincer les lentilles dans une passoire jusqu''à ce que l''eau soit claire.", "Faire fondre l''oignon haché dans l''huile 5 min, ajouter l''ail, le gingembre et les épices 1 min.", "Ajouter les lentilles, les tomates, le lait de coco et 500 ml d''eau. Porter à ébullition et cuire 20 min à feu doux en remuant souvent : les lentilles se défont et épaississent le plat. Ajouter de l''eau si c''est trop épais. Saler.", "Cuire le riz selon le paquet et servir le dahl dessus."]'::jsonb),
('Chili sin carne', 'Un chili végétarien aux haricots rouges, maïs et poivron, relevé de cumin et de paprika.', 10, 30, 4, 1, 'protéiné', '["tex-mex", "étudiant", "économique", "végan", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire fondre l''oignon haché et le poivron en dés dans l''huile 8 min.", "Ajouter l''ail et les épices 1 min, puis les tomates. Laisser mijoter 10 min.", "Ajouter les haricots et le maïs rincés et égouttés, saler et poursuivre 10 min, jusqu''à ce que ce soit épais.", "Cuire le riz selon le paquet et servir avec le chili. Se garde 3 jours au frais et se congèle très bien."]'::jsonb),
('Soupe de lentilles corail', 'Une soupe veloutée de lentilles corail et carotte au cumin, prête en 25 minutes.', 10, 25, 4, 1, 'protéiné', '["étudiant", "économique", "soupe", "végan", "hiver", "plat"]'::jsonb, 'public', '["stovetop", "blender"]'::jsonb, '["Faire revenir l''oignon et les carottes en petits morceaux dans l''huile 5 min, ajouter le cumin 1 min.", "Ajouter les lentilles rincées, 1,2 L d''eau et le bouillon cube. Porter à ébullition et cuire 20 min, jusqu''à ce que les lentilles soient fondues.", "Mixer, ajouter le jus du demi-citron, rectifier le sel et servir. Ajouter de l''eau si la soupe est trop épaisse."]'::jsonb),
('Rösti de pommes de terre', 'Des galettes de pommes de terre râpées, dorées et croustillantes, avec un œuf au plat.', 15, 20, 2, 1, 'gras', '["suisse", "étudiant", "économique", "végétarien", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Éplucher et râper les pommes de terre et l''oignon à gros trous. Les presser fortement dans un torchon pour retirer le maximum d''eau : c''est ce qui les rend croustillantes. Saler et poivrer.", "Chauffer 2 c.à.s d''huile dans une poêle, former 4 galettes de 1 cm d''épaisseur et les cuire 6 à 7 min par face à feu moyen, jusqu''à ce qu''elles soient bien dorées.", "Cuire les œufs au plat dans le beurre et le reste d''huile, et servir sur les röstis."]'::jsonb),
('Pommes de terre sautées aux lardons', 'Des pommes de terre dorées à la poêle avec lardons et oignons, le plat réconfort pas cher.', 10, 25, 2, 1, 'gras', '["français", "étudiant", "économique", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper les pommes de terre en cubes de 2 cm (on peut garder la peau si elles sont lavées). Les précuire 5 min dans l''eau bouillante salée et bien les égoutter : elles dorent plus vite.", "Faire revenir les lardons à sec dans une grande poêle 4 min, puis les réserver.", "Ajouter l''huile et les pommes de terre dans la graisse des lardons et les faire dorer 12 à 15 min à feu moyen en les retournant de temps en temps.", "Ajouter l''oignon émincé et les lardons 5 min. Poivrer, saler peu (les lardons sont salés), parsemer de persil et servir."]'::jsonb),
('Nouilles instantanées améliorées', 'Un paquet de nouilles transformé en vrai repas avec un œuf, des légumes et un peu de sauce soja.', 5, 8, 1, 1, 'gras', '["asiatique", "étudiant", "économique", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Porter 400 ml d''eau à ébullition. Ajouter la carotte en julienne et le chou émincé 2 min.", "Ajouter les nouilles et la moitié du sachet d''assaisonnement (il est très salé), cuire selon le paquet, souvent 3 min.", "Casser l''œuf dans la casserole 1 min avant la fin, sans remuer, pour qu''il poche dans le bouillon.", "Verser dans un bol, ajouter la sauce soja, l''huile de sésame et l''oignon nouveau émincé."]'::jsonb),
('Quesadillas fromage et haricots', 'Des tortillas croustillantes garnies de haricots rouges épicés et de fromage fondu.', 10, 10, 2, 1, 'gras', '["mexicain", "étudiant", "économique", "rapide", "végétarien", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Égoutter les haricots, les écraser grossièrement à la fourchette avec le cumin, le paprika et une pincée de sel.", "Étaler la purée de haricots sur 2 tortillas, parsemer de maïs et de fromage, couvrir avec les 2 autres tortillas.", "Cuire dans une poêle sèche à feu moyen 3 min par face, en appuyant, jusqu''à ce que la tortilla soit dorée et le fromage fondu.", "Couper en quartiers et servir avec la salsa."]'::jsonb),
('Soupe poireaux-pommes de terre', 'Le velouté de poireaux et pommes de terre, simple, doux et très économique.', 10, 30, 4, 1, 'light', '["français", "étudiant", "économique", "soupe", "végétarien", "hiver", "plat"]'::jsonb, 'public', '["stovetop", "blender"]'::jsonb, '["Couper les poireaux en rondelles (en retirant le vert le plus foncé) et bien les rincer. Éplucher et couper les pommes de terre en cubes.", "Faire fondre l''oignon et les poireaux dans le beurre 5 min sans colorer.", "Ajouter les pommes de terre, 1 L d''eau et le bouillon cube. Cuire 25 min à feu moyen.", "Mixer avec la crème, saler, poivrer et servir."]'::jsonb),
('Pizza pita', 'Des mini-pizzas sur pain pita, prêtes en 15 minutes au four, à garnir avec ce qui reste au frigo.', 5, 10, 2, 1, 'gras', '["italien", "étudiant", "économique", "rapide", "four", "plat"]'::jsonb, 'public', '["oven"]'::jsonb, '["Préchauffer le four à 220 °C.", "Mélanger le concentré, les tomates et l''origan, et étaler cette sauce sur les pains pita.", "Garnir de jambon en morceaux, de champignons émincés et de mozzarella, arroser d''un filet d''huile.", "Cuire 8 à 10 min, jusqu''à ce que le fromage fonde et que les bords soient croustillants."]'::jsonb),
('Salade de riz au thon', 'Une salade de riz fraîche au thon, tomates, maïs et œufs durs, parfaite en boîte à emporter.', 15, 12, 3, 1, 'protéiné', '["étudiant", "économique", "salade", "été", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Cuire le riz selon le paquet, le rincer à l''eau froide et bien l''égoutter.", "Cuire les œufs 9 min dans l''eau bouillante, les refroidir, les écaler et les couper en quartiers.", "Vinaigrette : mélanger la moutarde, le vinaigre, l''huile, du sel et du poivre.", "Mélanger le riz, le thon émietté, les tomates en dés, le maïs, les cornichons en rondelles et la vinaigrette. Ajouter les œufs. Se garde 2 jours au frais."]'::jsonb),
('Gnocchis poêlés au beurre et à la sauge', 'Des gnocchis dorés directement à la poêle, sans les cuire à l''eau, avec beurre, sauge et parmesan.', 2, 10, 2, 1, 'gras', '["italien", "étudiant", "économique", "rapide", "végétarien", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Chauffer l''huile dans une grande poêle à feu moyen-vif et y mettre les gnocchis crus en une seule couche.", "Les laisser dorer 3 à 4 min sans les toucher, puis les retourner et poursuivre 3 à 4 min : ils deviennent croustillants dehors et moelleux dedans.", "Ajouter le beurre et la sauge, remuer 1 min jusqu''à ce que le beurre mousse et sente la noisette.", "Servir avec le parmesan râpé et du poivre."]'::jsonb),
('Curry d''œufs', 'Des œufs durs mijotés dans une sauce curry tomate-coco, un plat complet pour presque rien.', 10, 25, 3, 1, 'protéiné', '["indien", "étudiant", "économique", "végétarien", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Cuire les œufs 9 min dans l''eau bouillante, les refroidir et les écaler. Les entailler légèrement pour qu''ils prennent le goût de la sauce.", "Faire fondre l''oignon haché dans l''huile 6 min, ajouter l''ail, le gingembre et le curry 1 min.", "Ajouter les tomates et le lait de coco, saler et mijoter 10 min.", "Ajouter les œufs et laisser mijoter 5 min en les arrosant de sauce. Cuire le riz selon le paquet et servir ensemble."]'::jsonb),
('Frittata aux légumes', 'Une omelette épaisse aux courgettes, poivron et fromage, cuite à la poêle puis au four.', 10, 20, 3, 1, 'protéiné', '["italien", "étudiant", "économique", "végétarien", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Préchauffer le four à 200 °C. Couper la courgette et le poivron en petits dés, émincer l''oignon.", "Les faire revenir dans l''huile dans une poêle allant au four, 8 min à feu moyen.", "Battre les œufs avec le lait, le fromage, du sel et du poivre, verser sur les légumes et cuire 3 min à feu doux sans remuer, jusqu''à ce que les bords prennent.", "Enfourner 8 à 10 min, jusqu''à ce que le centre soit pris. Servir chaud ou froid, en parts."]'::jsonb),
('Galettes de sarrasin jambon-œuf-fromage', 'La galette complète bretonne : jambon, emmental et œuf au milieu.', 10, 20, 4, 2, 'gras', '["breton", "français", "étudiant", "économique", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Pâte : mélanger la farine et le sel, ajouter 1 œuf, puis l''eau petit à petit en fouettant jusqu''à obtenir une pâte lisse et fluide. Idéalement, la laisser reposer 1h.", "Chauffer une grande poêle beurrée à feu moyen-vif, verser une louche de pâte en inclinant la poêle pour couvrir le fond. Cuire 2 min.", "Retourner la galette, parsemer d''emmental, poser une tranche de jambon et casser un œuf au centre.", "Couvrir 2 à 3 min, jusqu''à ce que le blanc soit pris, puis replier les bords vers le centre en carré. Servir aussitôt."]'::jsonb),
('Semoule aux légumes et pois chiches', 'Un couscous express végétarien : semoule, légumes rôtis à la poêle, pois chiches et épices.', 10, 20, 3, 1, 'light', '["maghrébin", "étudiant", "économique", "végan", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper les carottes en fines rondelles, la courgette en dés et émincer l''oignon.", "Les faire revenir dans 2 c.à.s d''huile avec les épices 10 min, ajouter les pois chiches rincés et 150 ml d''eau avec la moitié du bouillon cube, cuire 5 min.", "Semoule : la mettre dans un saladier avec le reste d''huile et les raisins secs, verser 250 ml d''eau bouillante avec l''autre moitié du bouillon, couvrir 5 min puis égrener à la fourchette.", "Servir la semoule avec les légumes et leur jus."]'::jsonb),
('Pâtes à la saucisse et à la tomate', 'Des pâtes dans une sauce tomate à la chair de saucisse émiettée, rapide et généreuse.', 5, 20, 4, 1, 'gras', '["italien", "étudiant", "économique", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Retirer la peau des chipolatas et émietter la chair dans une poêle chaude. La faire dorer 5 min à feu moyen.", "Ajouter l''oignon haché 3 min, puis l''ail, les tomates et l''origan. Saler et mijoter 10 min.", "Cuire les pâtes dans une grande casserole d''eau bouillante salée, les égoutter et les mélanger à la sauce. Servir avec le fromage râpé."]'::jsonb),
('Pain perdu salé', 'Du pain rassis trempé dans des œufs battus, poêlé et garni de jambon et fromage : l''anti-gaspi du soir.', 5, 10, 2, 1, 'gras', '["français", "étudiant", "économique", "anti-gaspi", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Battre les œufs avec le lait, du sel et du poivre.", "Tremper les tranches de pain dans ce mélange quelques secondes de chaque côté.", "Les dorer dans le beurre à feu moyen 2 à 3 min, les retourner, poser une demi-tranche de jambon et du fromage sur chacune.", "Couvrir 2 min pour faire fondre le fromage et servir avec une salade."]'::jsonb),
('Hot-dogs maison', 'Des saucisses de Strasbourg dans des pains briochés, avec oignons caramélisés, moutarde et ketchup.', 5, 15, 4, 1, 'gras', '["américain", "étudiant", "économique", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire fondre les oignons émincés dans l''huile avec la pincée de sucre 10 à 12 min à feu moyen, jusqu''à ce qu''ils soient dorés.", "Pocher les saucisses 5 min dans de l''eau frémissante, sans faire bouillir (elles éclateraient).", "Ouvrir les pains et les passer 1 à 2 min au four ou au grille-pain.", "Garnir chaque pain d''une saucisse, d''oignons, de fromage, de moutarde et de ketchup."]'::jsonb),
('Pâtes au beurre, ail et parmesan', 'Le plat de dépannage par excellence : des pâtes, du beurre à l''ail et du parmesan.', 2, 12, 2, 1, 'gras', '["étudiant", "économique", "rapide", "végétarien", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Cuire les pâtes dans une grande casserole d''eau bouillante salée, garder une louche d''eau de cuisson avant d''égoutter.", "Dans la casserole vide, faire fondre le beurre avec l''ail haché 1 min à feu doux.", "Ajouter les pâtes, le parmesan et un peu d''eau de cuisson, remuer jusqu''à ce que ce soit crémeux. Poivrer et parsemer de persil."]'::jsonb),
('Gratin de chou-fleur', 'Du chou-fleur sous une béchamel gratinée à l''emmental, économique et réconfortant.', 15, 35, 4, 1, 'gras', '["français", "étudiant", "économique", "four", "végétarien", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Préchauffer le four à 200 °C. Couper le chou-fleur en bouquets et les cuire 8 min dans l''eau bouillante salée. Bien les égoutter.", "Béchamel : faire fondre le beurre, ajouter la farine 1 min, verser le lait en fouettant et cuire 5 min jusqu''à épaississement. Saler, poivrer, ajouter la muscade et la moitié du fromage.", "Mettre le chou-fleur dans un plat, napper de béchamel et parsemer du reste de fromage.", "Gratiner 20 min, jusqu''à ce que le dessus soit doré."]'::jsonb),
('Velouté de carottes au cumin', 'Une soupe de carottes veloutée, douce et légèrement épicée, parmi les moins chères qui soient.', 10, 25, 4, 1, 'light', '["étudiant", "économique", "soupe", "végétarien", "hiver", "plat"]'::jsonb, 'public', '["stovetop", "blender"]'::jsonb, '["Éplucher et couper les carottes en rondelles, la pomme de terre en cubes et émincer l''oignon.", "Faire revenir l''oignon dans l''huile 3 min, ajouter le cumin 1 min.", "Ajouter les légumes, 1 L d''eau et le bouillon cube, cuire 20 à 25 min jusqu''à ce que les carottes soient tendres.", "Mixer avec la crème, saler, poivrer et servir."]'::jsonb),
('Pâtes au pesto rouge', 'Des pâtes au pesto de tomates séchées, relevées de mozzarella fondante et de basilic.', 5, 10, 4, 1, 'gras', '["italien", "étudiant", "économique", "rapide", "pâtes", "végétarien", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Cuire les pâtes dans une grande casserole d''eau bouillante salée, garder un peu d''eau de cuisson avant d''égoutter.", "Mélanger les pâtes hors du feu avec le pesto rouge et 2 à 3 c.à.s d''eau de cuisson.", "Ajouter la mozzarella en petits dés, qui fond légèrement au contact des pâtes chaudes, et le basilic. Servir."]'::jsonb),
('Pâtes au poulet, crème et curry', 'Des pâtes au poulet dans une sauce crème au curry douce, un classique des soirs de semaine.', 10, 15, 4, 1, 'protéiné', '["étudiant", "économique", "rapide", "pâtes", "poulet", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper le poulet en petits morceaux et émincer l''oignon.", "Cuire les pâtes dans une grande casserole d''eau bouillante salée.", "Faire dorer le poulet et l''oignon dans l''huile 6 à 7 min, jusqu''à ce que le poulet soit cuit à cœur. Ajouter le curry 1 min.", "Ajouter la crème, saler, poivrer, laisser épaissir 2 min et mélanger avec les pâtes égouttées."]'::jsonb),
('Steak haché et coquillettes au beurre', 'Le duo de base de l''étudiant : un steak haché bien saisi et des coquillettes au beurre et au fromage.', 2, 12, 2, 1, 'protéiné', '["étudiant", "économique", "rapide", "pâtes", "viande", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Cuire les coquillettes dans une casserole d''eau bouillante salée selon le paquet.", "Chauffer l''huile dans une poêle bien chaude et cuire les 2 steaks hachés (100 g chacun) 2 à 3 min par face. Pour la viande hachée, la cuisson à cœur (70 °C, plus de rose au centre) est recommandée, surtout pour les enfants et les personnes fragiles.", "Égoutter les pâtes et les mélanger avec le beurre et le fromage. Saler et poivrer les steaks et servir avec le ketchup."]'::jsonb),
('Riz sauté à la dinde et aux légumes', 'Un riz sauté à la dinde, aux poivrons et aux oignons, relevé de sauce soja.', 10, 15, 4, 1, 'protéiné', '["étudiant", "économique", "volaille", "asiatique", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Cuire le riz selon le paquet (ou utiliser un reste de riz).", "Couper la dinde en petits morceaux, le poivron et la carotte en petits dés, émincer l''oignon.", "Dans un wok ou une grande poêle très chaude, faire dorer la dinde dans l''huile 5 min. Ajouter les légumes et l''ail 4 min.", "Ajouter le riz et la sauce soja, faire sauter 3 min à feu vif et servir."]'::jsonb),
('Sauté de porc à la moutarde et pâtes', 'Des morceaux d''échine de porc dans une sauce crème-moutarde, avec des pâtes.', 10, 25, 4, 1, 'gras', '["français", "étudiant", "économique", "viande", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper le porc en cubes de 2 cm et émincer l''oignon.", "Faire dorer le porc dans l''huile 6 min, ajouter l''oignon 4 min, puis 100 ml d''eau. Couvrir et cuire 10 min à feu doux.", "Ajouter la crème et la moutarde, laisser épaissir 3 min. Saler et poivrer.", "Cuire les pâtes dans une grande casserole d''eau bouillante salée et servir avec le porc et sa sauce."]'::jsonb),
('Quiche aux légumes', 'Une quiche aux courgettes, poivron et emmental, bonne chaude ou froide pour le lendemain.', 15, 35, 6, 1, 'gras', '["français", "étudiant", "économique", "four", "végétarien", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Préchauffer le four à 190 °C. Étaler la pâte dans un moule avec son papier et la piquer à la fourchette.", "Couper la courgette et le poivron en petits dés, émincer l''oignon. Les faire revenir dans l''huile 8 min pour qu''ils rendent leur eau (sinon la quiche est détrempée).", "Battre les œufs avec la crème, le lait, la muscade, du sel et du poivre.", "Répartir les légumes sur la pâte, verser l''appareil et parsemer d''emmental.", "Cuire 30 à 35 min, jusqu''à ce que la quiche soit dorée et que le centre ne tremble plus."]'::jsonb),
('Quiche thon-tomate-moutarde', 'Une quiche au thon et aux tomates avec une fine couche de moutarde sur la pâte.', 10, 35, 6, 1, 'protéiné', '["français", "étudiant", "économique", "four", "poisson", "plat"]'::jsonb, 'public', '["oven"]'::jsonb, '["Préchauffer le four à 190 °C. Étaler la pâte dans un moule, la piquer et la tartiner de moutarde.", "Répartir le thon égoutté et émietté, puis les tomates en rondelles.", "Battre les œufs avec la crème, les herbes, du sel et du poivre, verser sur la garniture et parsemer d''emmental.", "Cuire 30 à 35 min, jusqu''à ce que la quiche soit dorée et prise au centre."]'::jsonb),
('Quiche poireaux-lardons', 'Une quiche aux poireaux fondus et aux lardons, entre quiche lorraine et flamiche.', 15, 40, 6, 1, 'gras', '["français", "étudiant", "économique", "four", "plat"]'::jsonb, 'public', '["stovetop", "oven"]'::jsonb, '["Préchauffer le four à 190 °C. Étaler la pâte dans un moule et la piquer.", "Émincer les poireaux et bien les rincer. Faire dorer les lardons à sec 3 min, ajouter le beurre et les poireaux et les faire fondre 10 min à feu doux.", "Battre les œufs avec la crème, le lait, la muscade et du poivre (pas de sel : les lardons le sont).", "Étaler la fondue de poireaux sur la pâte, verser l''appareil, parsemer d''emmental et cuire 30 à 35 min."]'::jsonb),
('Quiche jambon-fromage', 'La quiche simple au jambon et à l''emmental, qu''on prépare en 10 minutes.', 10, 35, 6, 1, 'gras', '["français", "étudiant", "économique", "four", "plat"]'::jsonb, 'public', '["oven"]'::jsonb, '["Préchauffer le four à 190 °C. Étaler la pâte dans un moule et la piquer.", "Couper le jambon en dés et le répartir sur la pâte avec la moitié de l''emmental.", "Battre les œufs avec la crème, le lait, la muscade, une pincée de sel et du poivre. Verser sur la garniture et parsemer du reste d''emmental.", "Cuire 30 à 35 min, jusqu''à ce que la quiche soit bien dorée."]'::jsonb),
('Galette tomate, gruyère, œuf et salade', 'La galette de sarrasin garnie de gruyère, d''un œuf, de tomates fraîches et de salade.', 15, 20, 4, 2, 'gras', '["breton", "français", "étudiant", "économique", "végétarien", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Pâte : mélanger la farine de sarrasin et le sel, ajouter 1 œuf, puis l''eau petit à petit en fouettant jusqu''à obtenir une pâte lisse et fluide. Idéalement, la laisser reposer 1h (elle se garde 2 jours au frais).", "Chauffer une grande poêle beurrée à feu moyen-vif, verser une louche de pâte en inclinant la poêle pour couvrir le fond. Cuire 2 min, puis retourner la galette.", "Parsemer de gruyère et casser un œuf au centre. Couvrir 2 à 3 min, jusqu''à ce que le blanc soit pris, puis replier les bords en carré.", "Servir avec les tomates en rondelles et la salade assaisonnées d''huile d''olive, de sel et de poivre, posées sur la galette ou à côté. Refaire une galette nature par personne avec le reste de pâte, au sucre ou à la confiture pour le dessert."]'::jsonb),
('Galette forestière', 'Une galette de sarrasin garnie de champignons à la crème, de jambon et d''emmental.', 15, 25, 4, 2, 'gras', '["breton", "français", "étudiant", "économique", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire revenir l''échalote hachée et les champignons émincés dans 10 g de beurre 6 min, ajouter la crème, saler, poivrer et réserver.", "Pâte : mélanger la farine de sarrasin et le sel, ajouter 1 œuf, puis l''eau petit à petit en fouettant jusqu''à obtenir une pâte lisse et fluide. Idéalement, la laisser reposer 1h (elle se garde 2 jours au frais).", "Chauffer une grande poêle beurrée à feu moyen-vif, verser une louche de pâte en inclinant la poêle pour couvrir le fond. Cuire 2 min, puis retourner la galette.", "Parsemer d''emmental, ajouter une demi-tranche de jambon et une cuillerée de champignons à la crème. Replier les bords et laisser 1 min pour que le fromage fonde. Servir aussitôt."]'::jsonb),
('Galette-saucisse', 'La spécialité rennaise : une saucisse grillée roulée dans une galette de sarrasin.', 10, 20, 4, 1, 'gras', '["breton", "français", "étudiant", "économique", "street-food", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Cuire les saucisses à la poêle à feu moyen 15 min en les retournant, jusqu''à ce qu''elles soient dorées et cuites à cœur. À côté, faire fondre l''oignon émincé dans l''huile 8 min.", "Pâte : mélanger la farine de sarrasin et le sel, ajouter 1 œuf, puis l''eau petit à petit en fouettant jusqu''à obtenir une pâte lisse et fluide. Idéalement, la laisser reposer 1h (elle se garde 2 jours au frais).", "Cuire les galettes une à une dans la poêle beurrée, 2 min de chaque côté.", "Tartiner chaque galette d''un peu de moutarde, poser une saucisse et des oignons, et rouler bien serré. À manger à la main, comme sur les marchés bretons."]'::jsonb),
('Galette chèvre, miel et noix', 'Une galette de sarrasin au fromage de chèvre fondu, miel et noix, avec de la salade.', 10, 20, 4, 1, 'gras', '["breton", "français", "étudiant", "économique", "végétarien", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Pâte : mélanger la farine de sarrasin et le sel, ajouter 1 œuf, puis l''eau petit à petit en fouettant jusqu''à obtenir une pâte lisse et fluide. Idéalement, la laisser reposer 1h (elle se garde 2 jours au frais).", "Chauffer une grande poêle beurrée à feu moyen-vif, verser une louche de pâte en inclinant la poêle pour couvrir le fond. Cuire 2 min, puis retourner la galette.", "Garnir de rondelles de chèvre et de quelques noix concassées, replier les bords en carré et laisser 2 min pour que le chèvre fonde.", "Arroser d''un filet de miel et servir avec la salade assaisonnée d''huile d''olive."]'::jsonb),
('Wraps poulet-crudités sauce yaourt', 'Des wraps au poulet poêlé, carottes râpées et salade, avec une sauce yaourt-citron.', 15, 10, 4, 1, 'protéiné', '["étudiant", "économique", "rapide", "poulet", "sandwich", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper le poulet en lanières, le mélanger avec le paprika, du sel et du poivre, et le cuire dans l''huile 6 min jusqu''à ce qu''il soit cuit à cœur.", "Râper les carottes, émincer la salade et couper les tomates en dés.", "Sauce : mélanger le yaourt avec le jus du demi-citron, du sel et du poivre.", "Garnir les tortillas de crudités, de poulet et de sauce, puis les rouler serré. Se transportent bien, enveloppées dans du papier aluminium."]'::jsonb),
('Omelette jambon-fromage et salade', 'L''omelette baveuse au jambon et à l''emmental, avec une salade verte : le dîner prêt en 10 minutes.', 5, 5, 1, 1, 'protéiné', '["français", "étudiant", "économique", "rapide", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Battre les œufs avec du sel et du poivre.", "Faire mousser le beurre dans une poêle à feu moyen, verser les œufs et remuer doucement 1 min en ramenant les bords vers le centre.", "Quand le dessus est encore un peu coulant, ajouter le jambon en lanières et le fromage sur une moitié, plier l''omelette et la glisser dans l''assiette.", "Servir avec la salade assaisonnée d''huile d''olive, de vinaigre, de sel et de poivre."]'::jsonb),
('Steak haché sauce crème-champignons et purée', 'Le classique : des steaks hachés nappés d''une sauce crème aux champignons, avec une purée maison.', 15, 25, 4, 1, 'gras', '["français", "étudiant", "économique", "viande", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Cuire les pommes de terre épluchées et coupées dans de l''eau froide salée portée à ébullition, 20 min. Les écraser avec 20 g de beurre et le lait chaud. Saler et poivrer.", "Cuire les steaks dans l''huile 3 min par face (cuisson à cœur recommandée pour la viande hachée). Les réserver au chaud.", "Dans la même poêle, faire revenir l''échalote hachée et les champignons émincés dans le reste du beurre 5 min.", "Ajouter la crème, laisser épaissir 2 min, saler et poivrer. Napper les steaks et servir avec la purée."]'::jsonb),
('Chakchouka', 'Des œufs pochés dans une sauce de tomates et de poivrons épicée, à saucer avec du pain.', 10, 25, 2, 1, 'light', '["maghrébin", "étudiant", "économique", "végétarien", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Faire fondre l''oignon émincé et le poivron en lanières dans l''huile 8 min à feu moyen.", "Ajouter l''ail haché, le cumin et le paprika 1 min, puis les tomates. Saler et laisser mijoter 10 min, jusqu''à ce que la sauce épaississe.", "Creuser 4 petits puits dans la sauce et y casser les œufs. Couvrir et cuire 5 à 7 min à feu doux, jusqu''à ce que les blancs soient pris et les jaunes encore coulants.", "Parsemer de persil et servir dans la poêle, avec du pain pour saucer."]'::jsonb),
('Salade César au poulet frit maison', 'La salade César avec du poulet pané et frit maison, bien croustillant : romaine, croûtons à l''ail, parmesan et vraie sauce César aux anchois.', 30, 20, 4, 2, 'gras', '["américain", "salade", "poulet", "friture", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Marinade : couper les blancs de poulet en lanières épaisses. Mélanger 250 ml de lait avec 2 c.à.s de jus de citron (il caille légèrement, c''est voulu : il attendrit la viande), le paprika, l''ail en poudre, 1 c.à.c de sel et du poivre. Y plonger le poulet et laisser au moins 30 min au frais (jusqu''à une nuit).", "Sauce César : écraser les anchois et 1 gousse d''ail râpée, puis mélanger avec la mayonnaise, la moutarde, la sauce Worcestershire, le reste du jus de citron (1 c.à.s), la moitié du parmesan râpé finement et le reste du lait (1 c.à.s) pour la détendre. Poivrer et garder au frais.", "Croûtons : couper le pain en cubes de 2 cm. Les faire dorer 5 à 6 min à la poêle dans l''huile d''olive avec la seconde gousse d''ail écrasée, en remuant souvent. Égoutter sur du papier absorbant.", "Chauffer l''huile de friture à 170°C dans une friteuse ou une grande casserole à bords hauts (jamais remplie à plus de la moitié, sans la quitter des yeux). Mélanger la farine et la maïzena avec une pincée de sel.", "Égoutter les lanières de poulet et les rouler une à une dans la farine en appuyant bien pour former une croûte épaisse. Frire en 3 ou 4 fois, sans surcharger, 5 à 6 min, jusqu''à ce qu''elles soient bien dorées et cuites à cœur (74°C, chair blanche et jus clair au centre). Égoutter sur une grille ou du papier absorbant et saler aussitôt.", "Laver et essorer la romaine, la couper en gros morceaux et la mélanger avec la sauce. Répartir dans les assiettes, ajouter les croûtons, le poulet frit coupé en morceaux et le reste du parmesan en copeaux. Servir tout de suite, pour que le poulet reste croustillant."]'::jsonb),
('Tarte au citron meringuée', 'Une pâte sablée, une crème au citron acidulée et un nuage de meringue doré : le grand classique de la pâtisserie française.', 45, 40, 8, 3, 'gras', '["français", "dessert", "four", "goûter"]'::jsonb, 'public', '["oven", "stovetop"]'::jsonb, '["Pâte sablée : mélanger du bout des doigts la farine, le sucre glace, la poudre d''amande, une pincée de sel et 100 g de beurre froid en dés, jusqu''à obtenir un sable. Ajouter 1 œuf et rassembler en boule sans trop travailler la pâte. L''aplatir, la filmer et la laisser 1h au frais.", "Étaler la pâte sur 3 mm et foncer un moule à tarte de 24 cm. Piquer le fond à la fourchette et remettre 30 min au frais (la pâte se rétractera moins à la cuisson).", "Préchauffer le four à 170°C. Couvrir la pâte de papier cuisson, la remplir de légumes secs et cuire à blanc 15 min. Retirer papier et légumes secs et cuire encore 10 à 12 min, jusqu''à ce que le fond soit doré. Laisser refroidir.", "Crème au citron : prélever le zeste de 2 citrons et presser les 3 (environ 120 ml de jus). Dans une casserole, fouetter 1 œuf entier et 3 jaunes (garder les 3 blancs pour la meringue) avec 120 g de sucre et la maïzena, puis ajouter le jus et les zestes.", "Cuire à feu moyen sans cesser de fouetter jusqu''aux premiers bouillons : la crème épaissit d''un coup. Laisser bouillir 1 min en fouettant, retirer du feu et incorporer les 60 g de beurre restants en morceaux. Verser sur le fond de tarte refroidi et laisser prendre 1h au frais.", "Meringue : monter les 3 blancs en neige avec une pincée de sel (au batteur électrique, c''est bien plus facile). Quand ils sont mousseux, ajouter les 150 g de sucre restants en 3 fois et fouetter jusqu''à une meringue ferme et brillante, qui forme un bec.", "Préchauffer le four à 180°C. Étaler ou pocher la meringue sur la crème au citron, en faisant des pics à la cuillère. Enfourner 8 à 10 min, jusqu''à ce que les pointes soient dorées (ou utiliser un chalumeau de cuisine).", "Laisser refroidir puis garder la tarte au frais jusqu''au service (au moins 1h). Elle se coupe mieux avec un couteau trempé dans l''eau chaude. Se conserve 2 jours au réfrigérateur."]'::jsonb),
('Tarte aux fraises ou aux framboises', 'Une pâte sablée croustillante, une crème pâtissière à la vanille et des fraises fraîches, ou des framboises selon la saison.', 40, 35, 8, 2, 'gras', '["français", "dessert", "four", "goûter"]'::jsonb, 'public', '["oven", "stovetop"]'::jsonb, '["Pâte sablée : mélanger du bout des doigts la farine, le sucre glace, la poudre d''amande, une pincée de sel et 100 g de beurre froid en dés, jusqu''à obtenir un sable. Ajouter 1 œuf et rassembler en boule sans trop travailler la pâte. L''aplatir, la filmer et la laisser 1h au frais.", "Étaler la pâte sur 3 mm et foncer un moule à tarte de 24 cm. Piquer le fond à la fourchette et remettre 30 min au frais (la pâte se rétractera moins à la cuisson).", "Préchauffer le four à 170°C. Couvrir la pâte de papier cuisson, la remplir de légumes secs et cuire à blanc 15 min. Retirer papier et légumes secs et cuire encore 10 à 12 min, jusqu''à ce que le fond soit doré. Laisser refroidir.", "Crème pâtissière : fendre la gousse de vanille, gratter les graines et les mettre avec la gousse dans le lait. Porter à frémissement puis retirer du feu.", "Fouetter 4 jaunes d''œufs avec le sucre jusqu''à ce que le mélange blanchisse, puis ajouter la maïzena. Verser le lait chaud en filet (sans la gousse) en fouettant, reverser le tout dans la casserole et cuire à feu moyen sans cesser de fouetter jusqu''à épaississement, puis encore 1 min.", "Verser la crème dans un plat, la couvrir de film au contact (pour éviter qu''une peau se forme) et la laisser refroidir complètement au frais, au moins 1h.", "Laver rapidement les fraises, les sécher, les équeuter et les couper en deux (les framboises ne se lavent pas : il suffit de les trier). Fouetter la crème pâtissière froide pour la lisser et l''étaler sur le fond de tarte refroidi.", "Disposer les fraises serrées sur la crème, pointe vers le haut. Faire tiédir la gelée de groseille avec 1 c.à.s d''eau et en badigeonner les fruits au pinceau pour les faire briller. Garder au frais jusqu''au service (le jour même, la pâte ramollit ensuite) et saupoudrer d''un peu de sucre glace."]'::jsonb),
('Poulet à la crème, champignons et pâtes (ou riz)', 'Des morceaux de poulet et des champignons dorés dans une sauce à la crème fraîche, avec des tagliatelles ou du riz : le plat en sauce simple et réconfortant des soirs de semaine.', 10, 20, 4, 1, 'protéiné', '["étudiant", "économique", "rapide", "poulet", "pâtes", "plat"]'::jsonb, 'public', '["stovetop"]'::jsonb, '["Couper le poulet en morceaux, émincer l''oignon et l''ail, nettoyer et trancher les champignons. Mettre une grande casserole d''eau salée à chauffer pour les tagliatelles (ou cuire 300 g de riz selon le paquet à la place).", "Dans une grande poêle, faire dorer le poulet dans l''huile 5 à 6 min à feu vif. Le réserver dans une assiette.", "Dans la même poêle, faire fondre le beurre et y faire dorer les champignons et l''oignon 6 à 7 min, jusqu''à ce que l''eau des champignons soit évaporée. Ajouter l''ail 1 min.", "Remettre le poulet, ajouter le demi-cube de bouillon émietté dans 100 ml d''eau chaude, puis la crème fraîche et la moutarde. Laisser mijoter 5 min à feu doux, jusqu''à ce que la sauce nappe la cuillère et que le poulet soit cuit à cœur (74°C, plus de rose au centre). Poivrer et goûter avant de saler.", "Pendant ce temps, cuire les tagliatelles selon le paquet et les égoutter. Servir le poulet et sa sauce sur les pâtes (ou le riz), parsemé de persil."]'::jsonb)
