-- ============================================================================
-- MealsUp — RECETTES DE BASE (données)
-- ============================================================================
-- À exécuter dans le SQL Editor de Supabase, APRÈS schema.sql.
-- Idempotent : peut être rejoué. Une recette existante (même titre) est mise
-- à jour ; ses ingrédients sont supprimés puis réinsérés.
--
-- Ces recettes sont "système" (created_by = NULL, visibles par tous). Les
-- recettes créées par les utilisateurs (created_by renseigné) ne sont jamais
-- touchées par ce fichier.
--
-- PROVENANCE :
--   - 28 recettes adaptées du jeu de données ouvert UniTools Recipes
--     (https://theunitools.com/recipes, licence CC BY-SA 4.0 — attribution :
--     "Recette adaptée de UniTools — theunitools.com (CC BY-SA 4.0)"),
--     traduites en français puis relues et complétées.
--   - Les autres recettes sont rédigées à la main et recoupées avec des
--     recettes de référence (températures, temps de cuisson et de pousse,
--     ratios) ; cuissons à cœur : 74°C volaille, 70-71°C viande hachée.
--   - Photos : Wikimedia Commons, licences libres (auteur et licence
--     de chaque photo dans image_credit).
--
-- Catégories de repas (tags) : 'petit-déjeuner', 'plat', 'goûter', 'apéro'.
-- Chaque recette en a au moins une ; l'app s'en sert pour les filtres.
-- ============================================================================

ON CONFLICT (title) WHERE created_by IS NULL DO UPDATE SET
  description = EXCLUDED.description,
  prep_time_mins = EXCLUDED.prep_time_mins,
  cook_time_mins = EXCLUDED.cook_time_mins,
  servings = EXCLUDED.servings,
  difficulty = EXCLUDED.difficulty,
  dietary_type = EXCLUDED.dietary_type,
  tags = EXCLUDED.tags,
  visibility = EXCLUDED.visibility,
  equipment_needed = EXCLUDED.equipment_needed,
  instructions = EXCLUDED.instructions;


