-- ===== Catalogue d'ingrédients : retire ceux qui ne servent plus =====
-- (les produits du catalogue, qui ont un rayon, sont gardés)
DELETE FROM ingredients i
WHERE i.category IS NULL
  AND NOT EXISTS (SELECT 1 FROM recipe_ingredients ri WHERE ri.ingredient_id = i.id);


-- ===== Catalogue produits (table ingredients) =====
-- Tous les produits proposés dans l'app (onglet Ingrédients des courses, frigo),
-- avec leur rayon. Généré avec src/constants/groceryCatalog.ts.
ON CONFLICT (norm_key) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category;

-- Anciens noms de produits renommés (ex. « Cola » -> « Cola (Coca-Cola) »), sauf s'ils servent à une recette
DELETE FROM ingredients i
WHERE i.name IN ('Bitter apéritif (pour spritz)', 'Boisson énergisante', 'Chocolat en poudre', 'Cola', 'Cola sans sucres', 'Céréales au chocolat', 'Liqueur de café', 'Pastis', 'Pâte à tartiner', 'Soda à l''orange', 'Speculoos à tartiner', 'Thé glacé', 'Tonic', 'Triple sec', 'Vermouth blanc')
  AND NOT EXISTS (SELECT 1 FROM recipe_ingredients ri WHERE ri.ingredient_id = i.id);
